final_template:
terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  default_tags = {
    Project     = "route53-dns-query-logging"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

variable "tags" {
  description = "Additional user-defined tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

# Public hosted zone for DNS query logging (stateful, protected from deletion)
resource "aws_route53_zone" "primary" {
  name = "example.com"

  tags = merge(local.default_tags, var.tags)

  lifecycle {
    prevent_destroy = true
  }
}

# CloudWatch Logs log group that receives the DNS query logs for the zone.
# Retention is finite (90 days) to avoid indefinite log storage.
resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name              = "aws_route53_example_com"
  retention_in_days = 90

  tags = merge(local.default_tags, var.tags)
}

# Least-privilege resource policy granting the Route 53 service principal
# only the actions required to write query logs into the log group above.
data "aws_iam_policy_document" "route53_query_logging" {
  statement {
    sid    = "Route53LogsToCloudWatchLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["route53.amazonaws.com"]
    }

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.aws_route53_example_com.arn,
      "${aws_cloudwatch_log_group.aws_route53_example_com.arn}:*",
    ]
  }
}

resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  policy_name     = "route53-query-logging-policy"
  policy_document = data.aws_iam_policy_document.route53_query_logging.json
}

# Associates the hosted zone with the CloudWatch log group. The resource
# policy must exist before the query logging configuration is created.
resource "aws_route53_query_log" "primary" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
  zone_id                  = aws_route53_zone.primary.zone_id

  depends_on = [
    aws_cloudwatch_log_resource_policy.route53_query_logging_policy,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Domain name used for both the public and private split-view hosted zones."
  type        = string
  default     = "example.com"
}

locals {
  db_engine          = "postgres"
  db_engine_version  = "15"
  db_instance_class  = "db.t3.micro"
  db_port            = 5432
  db_master_username = "dbadmin"
  db_record_name     = "db.${var.domain_name}"
  db_record_ttl      = 300

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = "10.0.${count.index + 11}.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "private-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Database subnet group (spans private and public subnets across two AZs)
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "internal" {
  name        = "internal"
  description = "Internal database access - PostgreSQL only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "PostgreSQL responses to within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "internal"
  })
}

resource "aws_security_group" "public" {
  name        = "public"
  description = "Externally reachable database access - PostgreSQL port only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from anywhere - explicitly required for the externally reachable database endpoint"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "PostgreSQL to within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

# ---------------------------------------------------------------------------
# RDS instances (identical engine configuration for interchangeable endpoints)
# ---------------------------------------------------------------------------

resource "aws_db_instance" "internal" {
  identifier     = "internal"
  engine         = local.db_engine
  engine_version = local.db_engine_version
  instance_class = local.db_instance_class
  port           = local.db_port

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  username                    = local.db_master_username
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.internal.id]
  publicly_accessible    = false

  multi_az                = false
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "internal"
  })
}

resource "aws_db_instance" "public" {
  identifier     = "public"
  engine         = local.db_engine
  engine_version = local.db_engine_version
  instance_class = local.db_instance_class
  port           = local.db_port

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  username                    = local.db_master_username
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.public.id]
  publicly_accessible    = true

  multi_az                = false
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = true

  # Ensure internet-routable subnets (IGW and default routes) exist before the
  # publicly accessible instance is provisioned so it receives a public endpoint.
  depends_on = [aws_route_table_association.public]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

# ---------------------------------------------------------------------------
# Split-view DNS (Route 53)
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "public" {
  name = var.domain_name

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

resource "aws_route53_zone" "private" {
  name = var.domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(local.common_tags, {
    Name = "private"
  })
}

resource "aws_route53_record" "internal" {
  zone_id = aws_route53_zone.private.zone_id
  name    = local.db_record_name
  type    = "CNAME"
  ttl     = local.db_record_ttl
  records = [aws_db_instance.internal.address]
}

resource "aws_route53_record" "public" {
  zone_id = aws_route53_zone.public.zone_id
  name    = local.db_record_name
  type    = "CNAME"
  ttl     = local.db_record_ttl
  records = [aws_db_instance.public.address]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_ids = join(",", [aws_subnet.public_a.id, aws_subnet.public_b.id])
}

# -----------------------------------------------------------------------------
# Networking foundation (greenfield — everything defined in-file)
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "eb-main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "eb-main-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "eb-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role + instance profile shared by both environments
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role for enhanced health / managed updates
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_service_role" {
  name = "eb_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application (single, shared by both environments)
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my_application"
  description = "Shared Elastic Beanstalk application for multiple environments"
}

# -----------------------------------------------------------------------------
# Environment one
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_environment" "env_one" {
  name                = "my-app-one"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.1 running Python 3.11"
  tier                = "WebServer"
  cname_prefix        = "my-app-one"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }
}

# -----------------------------------------------------------------------------
# Environment two
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_environment" "env_two" {
  name                = "my-app-two"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.1 running Python 3.11"
  tier                = "WebServer"
  cname_prefix        = "my-app-two"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables - user-controlled, non-infrastructure values only (all with
# defaults so `terraform apply` runs unattended)
###############################################################################

variable "domain_name" {
  description = "Root domain for the public Route53 hosted zone that serves the weighted records (e.g. \"example.com\")."
  type        = string
  default     = "example.com"
}

variable "record_subdomain" {
  description = "Single DNS label for the weighted CNAME records. Records live at \"<record_subdomain>.<domain_name>\" (e.g. \"app\" -> \"app.example.com\")."
  type        = string
  default     = "app"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]*[a-z0-9])?$", var.record_subdomain))
    error_message = "record_subdomain must be a single lowercase DNS label (letters, digits, hyphens)."
  }
}

variable "blue_weight" {
  description = "Route53 weighted routing weight for the blue environment (0-255)."
  type        = number
  default     = 100

  validation {
    condition     = var.blue_weight >= 0 && var.blue_weight <= 255 && floor(var.blue_weight) == var.blue_weight
    error_message = "blue_weight must be an integer between 0 and 255."
  }
}

variable "green_weight" {
  description = "Route53 weighted routing weight for the green environment (0-255). Raise gradually (e.g. 10 -> 50 -> 100) while lowering blue_weight to shift traffic blue -> green."
  type        = number
  default     = 0

  validation {
    condition     = var.green_weight >= 0 && var.green_weight <= 255 && floor(var.green_weight) == var.green_weight
    error_message = "green_weight must be an integer between 0 and 255."
  }
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack used by both environments."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.5.0 running Python 3.11"
}

variable "instance_type" {
  description = "EC2 instance type for the Beanstalk auto scaling instances."
  type        = string
  default     = "t3.small"
}

variable "tags" {
  description = "Additional tags merged into every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources - static provider metadata only
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  record_fqdn = "${var.record_subdomain}.${var.domain_name}"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  shared_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      Environment = "shared"
    },
  )

  blue_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      Environment = "blue"
    },
  )

  green_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      Environment = "green"
    },
  )
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.shared_tags, { Name = "bgapp-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.shared_tags, { Name = "bgapp-igw" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.shared_tags, { Name = "bgapp-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.shared_tags, { Name = "bgapp-public-b" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.shared_tags, { Name = "bgapp-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group for the Beanstalk EC2 instances (public web tier)
#
# Ingress justification: these instances are the public web tier that directly
# serves end-user HTTP/HTTPS traffic (the Beanstalk load balancer forwards to
# them), so ports 80 and 443 must be reachable from the internet. All other
# inbound ports are deliberately closed. Egress is unrestricted so instances
# can reach AWS service endpoints and package repositories.
###############################################################################

resource "aws_security_group" "beanstalk_instances" {
  name        = "bgapp-beanstalk-instances"
  description = "Beanstalk EC2 web tier: ingress limited to HTTP (80) and HTTPS (443) only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (public web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (public web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Unrestricted outbound access"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.shared_tags, { Name = "bgapp-beanstalk-instances" })
}

###############################################################################
# IAM - Elastic Beanstalk service role
###############################################################################

resource "aws_iam_role" "beanstalk_service" {
  name = "bgapp-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticBeanstalkToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      },
    ]
  })

  tags = merge(local.shared_tags, { Name = "bgapp-eb-service-role" })
}

resource "aws_iam_role_policy_attachment" "service_enhanced_health" {
  role       = aws_iam_role.beanstalk_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "service_managed_updates" {
  role       = aws_iam_role.beanstalk_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

###############################################################################
# IAM - EC2 instance role used by the Beanstalk instances
###############################################################################

resource "aws_iam_role" "beanstalk_ec2" {
  name = "bgapp-eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.shared_tags, { Name = "bgapp-eb-ec2-role" })
}

resource "aws_iam_role_policy_attachment" "ec2_web_tier" {
  role       = aws_iam_role.beanstalk_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "ec2_worker_tier" {
  role       = aws_iam_role.beanstalk_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "ec2_multicontainer_docker" {
  role       = aws_iam_role.beanstalk_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "beanstalk_ec2" {
  name = "bgapp-eb-ec2-instance-profile"
  role = aws_iam_role.beanstalk_ec2.name

  tags = merge(local.shared_tags, { Name = "bgapp-eb-ec2-instance-profile" })
}

###############################################################################
# Elastic Beanstalk application + blue/green environments
# (version_label intentionally omitted so Beanstalk launches its built-in
# sample application - no S3 bundle or external artifacts required)
###############################################################################

resource "aws_elastic_beanstalk_application" "bgapp" {
  name        = "bgapp"
  description = "Blue/Green weighted-routing application"

  tags = merge(local.shared_tags, { Name = "bgapp" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.bgapp.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  wait_for_ready_timeout = "20m"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.beanstalk_service.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.beanstalk_ec2.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:health_reporting"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(local.blue_tags, { Name = "bgapp-blue" })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.service_enhanced_health,
    aws_iam_role_policy_attachment.service_managed_updates,
    aws_iam_role_policy_attachment.ec2_web_tier,
    aws_iam_role_policy_attachment.ec2_worker_tier,
    aws_iam_role_policy_attachment.ec2_multicontainer_docker,
  ]
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.bgapp.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  wait_for_ready_timeout = "20m"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.beanstalk_service.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.beanstalk_ec2.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:health_reporting"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(local.green_tags, { Name = "bgapp-green" })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.service_enhanced_health,
    aws_iam_role_policy_attachment.service_managed_updates,
    aws_iam_role_policy_attachment.ec2_web_tier,
    aws_iam_role_policy_attachment.ec2_worker_tier,
    aws_iam_role_policy_attachment.ec2_multicontainer_docker,
  ]
}

###############################################################################
# Route53 - public hosted zone, per-environment health checks, weighted records
#
# Weighted routing (provider v5 idiom): the routing policy is declared by the
# presence of the nested `weighted_routing_policy` block plus `set_identifier`
# on each record - there is no `routing_policy` argument in provider v5.
# Traffic shifting: change var.blue_weight / var.green_weight (e.g. blue 90 /
# green 10, then 50/50, then 0/100) and re-apply to gradually move traffic from
# blue to green. If an environment fails its health check, Route53 withholds
# its answers regardless of the configured weight, protecting end users during
# a failed deployment.
###############################################################################

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = merge(local.shared_tags, { Name = "bgapp-zone" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "blue" {
  fqdn              = aws_elastic_beanstalk_environment.blue.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.blue_tags, { Name = "bgapp-health-check-blue" })
}

resource "aws_route53_health_check" "green" {
  fqdn              = aws_elastic_beanstalk_environment.green.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.green_tags, { Name = "bgapp-health-check-green" })
}

resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.record_fqdn
  type    = "CNAME"
  ttl     = 60

  weighted_routing_policy {
    weight = var.blue_weight
  }

  set_identifier  = "blue"
  health_check_id = aws_route53_health_check.blue.id
  records         = [aws_elastic_beanstalk_environment.blue.cname]
}

resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.record_fqdn
  type    = "CNAME"
  ttl     = 60

  weighted_routing_policy {
    weight = var.green_weight
  }

  set_identifier  = "green"
  health_check_id = aws_route53_health_check.green.id
  records         = [aws_elastic_beanstalk_environment.green.cname]
}

###############################################################################
# Outputs
###############################################################################

output "weighted_record_fqdn" {
  description = "Public FQDN served by the weighted blue/green CNAME records."
  value       = local.record_fqdn
}

output "hosted_zone_id" {
  description = "Route53 hosted zone ID (for external DNS delegation)."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Route53 name servers to delegate var.domain_name to."
  value       = aws_route53_zone.main.name_servers
}

output "blue_environment_id" {
  description = "Elastic Beanstalk environment ID for blue."
  value       = aws_elastic_beanstalk_environment.blue.id
}

output "blue_environment_cname" {
  description = "Elastic Beanstalk CNAME for blue."
  value       = aws_elastic_beanstalk_environment.blue.cname
}

output "green_environment_id" {
  description = "Elastic Beanstalk environment ID for green."
  value       = aws_elastic_beanstalk_environment.green.id
}

output "green_environment_cname" {
  description = "Elastic Beanstalk CNAME for green."
  value       = aws_elastic_beanstalk_environment.green.cname
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Locals (non-secret values only)
#------------------------------------------------------------------------------

locals {
  db_master_username = "dbadmin" # Non-secret master username
  db_name            = "my_db"
}

#------------------------------------------------------------------------------
# Availability zone lookup (static provider metadata)
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Networking: VPC, subnets, IGW, NAT gateway, routing
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "my-app-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "my-app-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "my-app-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "my-app-private-${count.index}"
  }
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "my-app-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "my-app-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "my-app-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "my-app-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

#------------------------------------------------------------------------------
# Security groups
#------------------------------------------------------------------------------

resource "aws_security_group" "eb_alb" {
  name        = "my-app-eb-alb-sg"
  description = "Elastic Beanstalk ALB security group - inbound HTTP/HTTPS only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-app-eb-alb-sg"
  }
}

resource "aws_security_group" "eb_instances" {
  name        = "my-app-eb-instances-sg"
  description = "Elastic Beanstalk EC2 instances - inbound only from the ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "All traffic from the ALB security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.eb_alb.id]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-app-eb-instances-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "my-app-rds-sg"
  description = "RDS security group - inbound PostgreSQL only from EB instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from EB instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-app-rds-sg"
  }
}

#------------------------------------------------------------------------------
# IAM: EC2 instance profile for Beanstalk instances and EB service role
#------------------------------------------------------------------------------

resource "aws_iam_role" "ec2_eb_role" {
  name = "ec2-eb-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "ec2-eb-instance-role"
  }
}

resource "aws_iam_role_policy_attachment" "ec2_eb_web_tier" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "ec2_eb_worker_tier" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "ec2_eb_multicontainer_docker" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "ec2_eb_profile1" {
  name = "ec2_eb_profile1"
  role = aws_iam_role.ec2_eb_role.name

  depends_on = [
    aws_iam_role_policy_attachment.ec2_eb_web_tier,
    aws_iam_role_policy_attachment.ec2_eb_worker_tier,
    aws_iam_role_policy_attachment.ec2_eb_multicontainer_docker,
  ]
}

resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "beanstalk.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "eb-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_service_role_policy" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

#------------------------------------------------------------------------------
# Elastic Beanstalk application (shared by blue and green environments)
#------------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "my_app" {
  name        = "my_app"
  description = "Blue/green Elastic Beanstalk application backed by Amazon RDS"
}

#------------------------------------------------------------------------------
# RDS: subnet group, generated credentials, secret storage, instance, snapshot
#------------------------------------------------------------------------------

resource "aws_db_subnet_group" "my_db_subnets" {
  name       = "my_db_subnets"
  subnet_ids = [aws_subnet.private[0].id, aws_subnet.private[1].id]

  tags = {
    Name = "my_db_subnets"
  }
}

resource "random_password" "db_master" {
  length      = 24
  special     = false
  min_lower   = 1
  min_upper   = 1
  min_numeric = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "my-db-master-credentials"
  description             = "Master credentials for the my-db PostgreSQL instance"
  recovery_window_in_days = 7

  tags = {
    Name = "my-db-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
  })
}

resource "aws_db_instance" "my_db" {
  identifier                = "my-db"
  engine                    = "postgres"
  instance_class            = "db.t3.micro"
  allocated_storage         = 20
  storage_encrypted         = true
  db_name                   = local.db_name
  username                  = local.db_master_username
  password                  = random_password.db_master.result
  port                      = 5432
  multi_az                  = true
  publicly_accessible       = false
  db_subnet_group_name      = aws_db_subnet_group.my_db_subnets.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  backup_retention_period   = 7
  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "my-db-final"

  tags = {
    Name = "my_db"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Pre-deployment snapshot of the my_db instance
resource "aws_db_snapshot" "pre_deploy" {
  db_instance_identifier = aws_db_instance.my_db.identifier
  db_snapshot_identifier = "my-db-pre-deploy"

  tags = {
    Name = "my-db-pre-deploy"
  }

  depends_on = [aws_db_instance.my_db]
}

#------------------------------------------------------------------------------
# Blue/green Elastic Beanstalk environments
#
# Both environments belong to aws_elastic_beanstalk_application.my_app and
# carry an identical configuration (same instance profile, service role,
# network, security groups, and RDS_* properties). Promotion is performed by
# swapping the two cname_prefix values between
# aws_elastic_beanstalk_environment.blue and
# aws_elastic_beanstalk_environment.green in a subsequent apply, which shifts
# traffic without replacing the EC2 instances. Both environments depend on
# aws_db_snapshot.pre_deploy so the pre-deployment database snapshot always
# precedes the first deployment.
#------------------------------------------------------------------------------

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "my-app-blue"
  application         = aws_elastic_beanstalk_application.my_app.name
  cname_prefix        = "my-app-blue-bgpoc"
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Python 3.12"
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.ec2_eb_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.private[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  # ELB (ALB) security groups - restricted to the 80/443-only ALB SG
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_alb.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.my_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.my_db.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = local.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = local.db_master_username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = random_password.db_master.result
  }

  tags = {
    Environment = "blue"
  }

  depends_on = [
    aws_db_snapshot.pre_deploy,
    aws_iam_role_policy_attachment.ec2_eb_web_tier,
    aws_iam_role_policy_attachment.ec2_eb_worker_tier,
    aws_iam_role_policy_attachment.ec2_eb_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_role_policy,
  ]
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "my-app-green"
  application         = aws_elastic_beanstalk_application.my_app.name
  cname_prefix        = "my-app-green-bgpoc"
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Python 3.12"
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.ec2_eb_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.private[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  # ELB (ALB) security groups - restricted to the 80/443-only ALB SG
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_alb.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.my_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.my_db.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = local.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = local.db_master_username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = random_password.db_master.result
  }

  tags = {
    Environment = "green"
  }

  depends_on = [
    aws_db_snapshot.pre_deploy,
    aws_iam_role_policy_attachment.ec2_eb_web_tier,
    aws_iam_role_policy_attachment.ec2_eb_worker_tier,
    aws_iam_role_policy_attachment.ec2_eb_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_role_policy,
  ]
}

#------------------------------------------------------------------------------
# Outputs (no secret values are ever exposed)
#------------------------------------------------------------------------------

output "blue_environment_cname" {
  description = "CNAME of the blue Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.blue.cname
}

output "green_environment_cname" {
  description = "CNAME of the green Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.green.cname
}

output "rds_endpoint" {
  description = "Connection endpoint of the my-db RDS instance"
  value       = aws_db_instance.my_db.endpoint
  sensitive   = true
}

###############################################################################
# Terraform + Provider
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static, local-only lookups (no dependency on pre-existing infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables — the only user-controlled values in this configuration
###############################################################################

variable "record_fqdn" {
  description = "Fully qualified domain name that the A record maps to the target IPv4 address (e.g. app.example.com)."
  type        = string
  default     = "app.example.com"
}

variable "parent_domain" {
  description = "Parent domain for the public Route 53 hosted zone (e.g. example.com)."
  type        = string
  default     = "example.com"
}

variable "ipv4_address" {
  description = "Target IPv4 address the record resolves to (e.g. 203.0.113.10)."
  type        = string
  default     = "203.0.113.10"

  validation {
    condition     = can(cidrnetmask("${var.ipv4_address}/32"))
    error_message = "ipv4_address must be a valid IPv4 address (e.g. 203.0.113.10)."
  }
}

variable "environment" {
  description = "Environment name used for the Environment tag."
  type        = string
  default     = "production"
}

###############################################################################
# Locals
###############################################################################

locals {
  parent_domain_normalized = trimsuffix(var.parent_domain, ".")

  common_tags = {
    Name        = local.parent_domain_normalized
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  # Route 53 KSK names may only contain letters, digits, and underscores.
  ksk_name = replace(local.parent_domain_normalized, ".", "_")

  # Customer-managed KMS key policy for Route 53 DNSSEC signing.
  # The key must be an asymmetric ECC_NIST_P256 SIGN_VERIFY key; asymmetric
  # keys do not support automatic rotation, so enable_key_rotation stays off.
  route53_dnssec_key_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "route53-dnssec-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:DescribeKey",
          "kms:DisableKey",
          "kms:EnableKey",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:GetPublicKey",
          "kms:ListKeyPolicies",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateKeyDescription"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Route 53 DNSSEC Service"
        Effect = "Allow"
        Principal = {
          Service = "dnssec-route53.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GetPublicKey",
          "kms:Sign"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

###############################################################################
# Public hosted zone for the parent domain
###############################################################################

resource "aws_route53_zone" "main" {
  name = var.parent_domain

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# A record: <record_fqdn> -> <ipv4_address>
#
# Omitting any routing-policy block selects the SIMPLE routing policy.
# Note: AWS Route 53 does not support tagging individual DNS record sets
# (the TagResource API only accepts hosted zones and health checks), so the
# consistent tag set is applied to the hosted zone and KMS key resources.
###############################################################################

resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.record_fqdn
  type    = "A"
  ttl     = 300
  records = [var.ipv4_address]
}

###############################################################################
# DNSSEC signing: customer-managed KMS key + key signing key + activation
###############################################################################

resource "aws_kms_key" "dnssec_signing" {
  description              = "Route 53 DNSSEC signing key for ${local.parent_domain_normalized}"
  customer_master_key_spec = "ECC_NIST_P256"
  key_usage                = "SIGN_VERIFY"
  deletion_window_in_days  = 30
  policy                   = local.route53_dnssec_key_policy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_key_signing_key" "main" {
  hosted_zone_id             = aws_route53_zone.main.zone_id
  key_management_service_arn = aws_kms_key.dnssec_signing.arn
  name                       = local.ksk_name
  status                     = "ACTIVE"
}

resource "aws_route53_hosted_zone_dnssec" "main" {
  hosted_zone_id = aws_route53_zone.main.zone_id
  signing_status = "SIGNING"

  depends_on = [aws_route53_key_signing_key.main]
}

###############################################################################
# Outputs
###############################################################################

output "hosted_zone_name_servers" {
  description = "Name servers of the public hosted zone. Configure these as the NS records for the parent domain at the registrar after apply."
  value       = aws_route53_zone.main.name_servers
}

output "record_fqdn" {
  description = "Fully qualified domain name of the A record managed by this configuration."
  value       = aws_route53_record.main.fqdn
}

output "hosted_zone_dnssec_ds_record" {
  description = "DS record contents to register with the domain registrar to complete DNSSEC delegation."
  value       = aws_route53_key_signing_key.main.ds_record
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables: non-infrastructure values only, all defaulted for unattended apply
# -----------------------------------------------------------------------------
variable "domain_name" {
  description = "Root domain name to manage in Route 53. The domain must be registered with an external registrar and delegated to the hosted zone."
  type        = string
  default     = "example.com"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

variable "db_engine" {
  description = "Database engine for the RDS instance (postgres or mysql)."
  type        = string
  default     = "postgres"
}

variable "db_engine_version" {
  description = "Database engine version for the RDS instance."
  type        = string
  default     = "15.5"
}

# -----------------------------------------------------------------------------
# Locals and static provider metadata
# -----------------------------------------------------------------------------
locals {
  common_tags = {
    Environment = var.environment
    Project     = "myapp"
    ManagedBy   = "terraform"
  }

  # RDS listen port derived from the selected engine (never exposed publicly)
  db_port = var.db_engine == "mysql" ? 3306 : 5432

  public_subnets  = [aws_subnet.public_1.id, aws_subnet.public_2.id]
  private_subnets = [aws_subnet.private_1.id, aws_subnet.private_2.id]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking foundation (greenfield - everything created in this file)
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "myapp-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "myapp-igw" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "myapp-public-subnet-1", Tier = "public" })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "myapp-public-subnet-2", Tier = "public" })
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "myapp-private-subnet-1", Tier = "private" })
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "myapp-private-subnet-2", Tier = "private" })
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "myapp-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_1.id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "myapp-nat-gateway" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "myapp-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "myapp-private-rt" })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Route 53: hosted zone and record routing traffic to the Beanstalk environment
# -----------------------------------------------------------------------------
resource "aws_route53_zone" "main" {
  name = var.domain_name

  # The domain must be registered externally (e.g. with a domain registrar).
  # Delegate the domain to the name servers of this hosted zone (see the
  # route53_name_servers output) so DNS traffic resolves through Route 53.
  comment = "Public hosted zone for ${var.domain_name}. The domain must be registered externally and its name servers delegated to this zone."

  tags = merge(local.common_tags, {
    Name        = var.domain_name
    Environment = var.environment
  })
}

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${var.domain_name}"
  type    = "CNAME"
  ttl     = 300

  records = [aws_elastic_beanstalk_environment.myenv.cname]
}

# -----------------------------------------------------------------------------
# IAM execution stack for Beanstalk EC2 instances
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

# Least-privilege inline policy: instances may read ONLY the DB credentials secret.
# The secret is fetched at runtime by the application via the instance profile
# instead of embedding the password in environment variables.
resource "aws_iam_role_policy" "eb_secrets_read" {
  name = "eb-secrets-read"
  role = aws_iam_role.eb_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.db_credentials.arn
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile1" {
  name = "eb_ec2_profile1"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "eb_ec2" {
  name        = "myapp-eb-ec2-sg"
  description = "Elastic Beanstalk EC2 instances: public web traffic on 80/443 only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (public web traffic)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (public web traffic)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "myapp-eb-ec2-sg" })
}

resource "aws_security_group" "rds" {
  name        = "myapp-rds-sg"
  description = "myapp_db database: reachable only from the Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Database port from Beanstalk EC2 instances only"
    from_port       = local.db_port
    to_port         = local.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_ec2.id]
  }

  tags = merge(local.common_tags, { Name = "myapp-rds-sg" })
}

# -----------------------------------------------------------------------------
# Database subnet group (private subnets across two AZs)
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "myapp_db_subnets" {
  name        = "myapp-db-subnet-group"
  description = "Private subnets across two AZs for myapp_db"
  subnet_ids  = local.private_subnets

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Database credentials: generated, never hardcoded, stored in Secrets Manager
# -----------------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "myapp/db/credentials"
  description             = "Master credentials for the myapp-db RDS instance"
  recovery_window_in_days = 7

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = "myappadmin"
    password = random_password.db_master.result
  })
}

# -----------------------------------------------------------------------------
# RDS instance
# Naming rules differ for the two "name-like" attributes of an RDS instance:
#   - identifier: AWS resource name, permits ONLY lowercase alphanumeric
#     characters and hyphens (no underscores) -> "myapp-db".
#   - db_name: PostgreSQL database name, permits lowercase letters, digits,
#     and underscores -> "myapp_db" (satisfies the requested database name).
# Do NOT "fix" db_name to hyphen form, and do NOT regress identifier to
# underscore form when trying to satisfy the "myapp_db" naming requirement.
# -----------------------------------------------------------------------------
resource "aws_db_instance" "myapp_db" {
  identifier     = "myapp-db"
  db_name        = "myapp_db"
  engine         = var.db_engine
  engine_version = var.db_engine_version
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_encrypted     = true

  username = "myappadmin"
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.myapp_db_subnets.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false
  multi_az               = true

  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "myapp-db-final-snapshot"

  tags = merge(local.common_tags, { Name = "myapp_db" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "Elastic Beanstalk application serving the myapp web tier, backed by myapp_db"

  tags = local.common_tags
}

resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.1 running Python 3.11"

  tags = merge(local.common_tags, { Name = "myenv" })

  # --- Launch configuration: instance profile and EC2 security groups ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_ec2.id
  }

  # --- VPC placement: EC2 in private subnets, ALB in public subnets ---
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.private_subnets)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnets)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "internet-facing"
  }

  # --- Load-balanced environment with an internet-facing ALB ---
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  # --- Enhanced health reporting so Route 53 traffic only hits healthy hosts ---
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckPath"
    value     = "/"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckProtocol"
    value     = "HTTP"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckPort"
    value     = "80"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckInterval"
    value     = "15"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckTimeout"
    value     = "5"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthyThresholdCount"
    value     = "3"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "UnhealthyThresholdCount"
    value     = "3"
  }

  # --- Auto Scaling bounds ---
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  # --- Application environment: database connectivity via attribute references.
  #     The password is NEVER injected here; instances fetch it at runtime from
  #     Secrets Manager (ARN below) using the instance profile's IAM policy. ---
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.myapp_db.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.myapp_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.myapp_db.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_credentials.arn
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "route53_record_fqdn" {
  description = "FQDN of the Route 53 record routing traffic to the Elastic Beanstalk environment"
  value       = aws_route53_record.app.fqdn
}

output "beanstalk_environment_cname" {
  description = "CNAME endpoint of the myenv Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.myenv.cname
}

output "rds_endpoint" {
  description = "Connection endpoint of the myapp-db RDS instance hosting the myapp_db database"
  value       = aws_db_instance.myapp_db.endpoint
}

output "route53_name_servers" {
  description = "Name servers to which the externally registered domain must be delegated for Route 53 to serve DNS"
  value       = aws_route53_zone.main.name_servers
}

###############################################################################
# Elastic Beanstalk application template
#
# Greenfield, self-contained configuration: creates the full network
# foundation, IAM roles, artifacts bucket, application version bundle and a
# WebServer-tier Elastic Beanstalk environment running a minimal WSGI app.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables (user-controlled, non-infrastructure values)
###############################################################################

variable "project_name" {
  description = "Short project identifier used as the naming prefix for all resources."
  type        = string
  default     = "ebapp"

  validation {
    condition     = can(regex("^[a-zA-Z0-9][a-zA-Z0-9-]{1,18}[a-zA-Z0-9]$", var.project_name))
    error_message = "project_name must be 3-20 alphanumeric characters or hyphens, and cannot start or end with a hyphen."
  }
}

variable "environment_name" {
  description = "Logical environment name, e.g. dev, staging, prod."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-zA-Z0-9][a-zA-Z0-9-]{1,13}[a-zA-Z0-9]$", var.environment_name))
    error_message = "environment_name must be 3-15 alphanumeric characters or hyphens, and cannot start or end with a hyphen."
  }
}

variable "environment_type" {
  description = "Elastic Beanstalk environment layout. Valid values: LoadBalanced, SingleInstance."
  type        = string
  default     = "LoadBalanced"

  validation {
    condition     = contains(["LoadBalanced", "SingleInstance"], var.environment_type)
    error_message = "environment_type must be either LoadBalanced or SingleInstance."
  }
}

variable "instance_type" {
  description = "EC2 instance type used by the Elastic Beanstalk environment."
  type        = string
  default     = "t3.small"
}

variable "solution_stack" {
  description = "Elastic Beanstalk platform (solution stack) for the environment."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.5.0 running Python 3.11"
}

variable "tags" {
  description = "Additional tags merged over the default tag set."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = lower(replace("${var.project_name}-${var.environment_name}", "/[^a-zA-Z0-9-]/", "-"))

  is_load_balanced = var.environment_type == "LoadBalanced"

  common_tags = merge(
    {
      environment  = var.environment_name
      project      = var.project_name
      "managed-by" = "terraform"
    },
    var.tags
  )
}

###############################################################################
# Availability zone discovery (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group dedicated to the EB EC2 instances (HTTP/HTTPS ingress only)
###############################################################################

resource "aws_security_group" "eb_instances" {
  name        = "${local.name_prefix}-eb-instances"
  description = "Elastic Beanstalk EC2 instances - inbound HTTP/HTTPS only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-eb-instances" })
}

###############################################################################
# Elastic Beanstalk service role
###############################################################################

resource "aws_iam_role" "eb_service_role" {
  name = "${local.name_prefix}-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "elasticbeanstalk.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_instances" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedInstancesCustomerPolicy"
}

resource "aws_iam_role_policy_attachment" "eb_service" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

resource "aws_iam_role_policy" "eb_service_passrole" {
  name = "${local.name_prefix}-eb-pass-instance-role"
  role = aws_iam_role.eb_service_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PassInstanceProfileRoleToElasticBeanstalk"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = aws_iam_role.eb_ec2_role.arn
      }
    ]
  })
}

###############################################################################
# EC2 instance profile for the EB instances
###############################################################################

resource "aws_iam_role" "eb_ec2_role" {
  name = "${local.name_prefix}-eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_profile" {
  name = "${local.name_prefix}-eb-instance-profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = local.common_tags
}

###############################################################################
# Dedicated S3 bucket for Elastic Beanstalk application versions
###############################################################################

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  special = false
}

resource "aws_s3_bucket" "eb_versions" {
  bucket = "${local.name_prefix}-eb-versions-${random_string.suffix.result}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-eb-versions" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  depends_on = [aws_s3_bucket_versioning.eb_versions]

  rule {
    id     = "expire-noncurrent-artifacts"
    status = "Enabled"
    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

resource "aws_s3_bucket_policy" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowElasticBeanstalkInstancesRead"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_ec2_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.eb_versions.arn}/*"
      },
      {
        Sid       = "AllowElasticBeanstalkServiceAccess"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = [aws_s3_bucket.eb_versions.arn, "${aws_s3_bucket.eb_versions.arn}/*"]
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.eb_versions,
    aws_s3_bucket_server_side_encryption_configuration.eb_versions,
    aws_s3_bucket_versioning.eb_versions,
    aws_s3_bucket_ownership_controls.eb_versions,
  ]
}

###############################################################################
# Application source bundle (generated locally, zipped, uploaded)
###############################################################################

data "archive_file" "app_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/eb-application-bundle.zip"

  source {
    filename = "application.py"
    content  = <<-EOT
      def application(environ, start_response):
          status = "200 OK"
          body = b"Hello from Elastic Beanstalk, deployed by Terraform!"
          headers = [
              ("Content-Type", "text/plain"),
              ("Content-Length", str(len(body))),
          ]
          start_response(status, headers)
          return [body]
    EOT
  }
}

resource "aws_s3_object" "app_bundle" {
  bucket       = aws_s3_bucket.eb_versions.id
  key          = "artifacts/${local.name_prefix}-application-bundle.zip"
  source       = data.archive_file.app_bundle.output_path
  etag         = data.archive_file.app_bundle.output_md5
  content_type = "application/zip"

  depends_on = [
    aws_s3_bucket_versioning.eb_versions,
    aws_s3_bucket_ownership_controls.eb_versions,
  ]
}

###############################################################################
# Elastic Beanstalk application and application version
###############################################################################

resource "aws_elastic_beanstalk_application" "main" {
  name        = "${local.name_prefix}-app"
  description = "Elastic Beanstalk application managed by Terraform"

  appversion_lifecycle {
    service_role          = aws_iam_role.eb_service_role.arn
    max_count             = 20
    delete_source_from_s3 = false
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-app" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application_version" "app" {
  name        = "v1.0.0"
  application = aws_elastic_beanstalk_application.main.name
  description = "Initial application version deployed by Terraform"
  bucket      = aws_s3_bucket.eb_versions.id
  key         = aws_s3_object.app_bundle.key

  depends_on = [aws_s3_bucket_policy.eb_versions]
}

###############################################################################
# Elastic Beanstalk WebServer environment
###############################################################################

resource "aws_elastic_beanstalk_environment" "web" {
  name                   = "${local.name_prefix}-web"
  application            = aws_elastic_beanstalk_application.main.name
  description            = "WebServer environment managed by Terraform"
  cname_prefix           = "${local.name_prefix}-web-${random_string.suffix.result}"
  solution_stack_name    = var.solution_stack
  version_label          = aws_elastic_beanstalk_application_version.app.name
  tier                   = "WebServer"
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = var.environment_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "StreamLogs"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "RetentionInDays"
    value     = "7"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "DeleteOnTerminate"
    value     = "false"
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:ec2:vpc"
      name      = "ELBSubnets"
      value     = join(",", aws_subnet.public[*].id)
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:elasticbeanstalk:environment"
      name      = "LoadBalancerType"
      value     = "application"
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:elasticbeanstalk:environment:process:default"
      name      = "HealthCheckPath"
      value     = "/"
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:autoscaling:asg"
      name      = "MinSize"
      value     = "1"
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:autoscaling:asg"
      name      = "MaxSize"
      value     = "3"
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-web" })

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_managed_instances,
    aws_iam_role_policy_attachment.eb_service,
    aws_iam_role_policy.eb_service_passrole,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_s3_bucket_policy.eb_versions,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk web environment."
  value       = "http://${aws_elastic_beanstalk_environment.web.cname}"
}

output "environment_cname" {
  description = "CNAME (DNS hostname) of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.web.cname
}

output "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.web.name
}

output "application_name" {
  description = "Name of the Elastic Beanstalk application."
  value       = aws_elastic_beanstalk_application.main.name
}

output "artifacts_bucket_name" {
  description = "Name of the S3 bucket storing Elastic Beanstalk application versions."
  value       = aws_s3_bucket.eb_versions.id
}

output "artifacts_bucket_arn" {
  description = "ARN of the S3 bucket storing Elastic Beanstalk application versions."
  value       = aws_s3_bucket.eb_versions.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "application_name" {
  description = "Name of the Elastic Beanstalk application."
  type        = string
  default     = "my-eb-application"
}

locals {
  environment = "production"
  owner       = "platform-team"
  purpose     = "elastic-beanstalk-appversion-lifecycle"

  common_tags = {
    Environment = local.environment
    Owner       = local.owner
    Purpose     = local.purpose
  }
}

resource "aws_iam_role" "eb_service_role" {
  name        = "eb-service-role-${var.application_name}"
  description = "Service role that allows Elastic Beanstalk to manage application version lifecycle"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid     = "AllowElasticBeanstalkServiceAssume"
        Effect  = "Allow"
        Action  = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })

  max_session_duration = 3600
  path                 = "/service-role/"

  tags = merge(
    local.common_tags,
    {
      Name = "eb-service-role-${var.application_name}"
    }
  )
}

resource "aws_iam_role_policy" "eb_service_role_version_bucket" {
  name = "eb-service-role-version-bucket-access"
  role = aws_iam_role.eb_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListVersionBuckets"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListObjects"
        ]
        Resource = [
          "arn:aws:s3:::elasticbeanstalk-*"
        ]
      },
      {
        Sid    = "ManageVersionObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "arn:aws:s3:::elasticbeanstalk-*/*"
        ]
      }
    ]
  })
}

resource "aws_elastic_beanstalk_application" "main" {
  name        = var.application_name
  description = "Elastic Beanstalk application with a 5 day application version retention lifecycle"

  appversion_lifecycle {
    service_role          = aws_iam_role.eb_service_role.arn
    max_age_in_days       = 5
    delete_source_from_s3 = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.application_name
    }
  )
}

# Terraform settings and provider (region pinned for this deployment)

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "github_repository_url" {
  description = "GitHub repository URL used as the source for the CodeBuild project."
  type        = string
  default     = "https://github.com/example/hello-world.git"
}

variable "github_personal_access_token" {
  description = "GitHub personal access token used for private repository access. Stored in AWS Secrets Manager and registered as a CodeBuild source credential. Replace the default with a real token for private repositories."
  type        = string
  default     = "REPLACE_ME_WITH_A_REAL_GITHUB_PAT"
  sensitive   = true
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  project_name         = "codebuild_example_project"
  artifact_bucket_name = lower("codebuild-example-artifacts-${data.aws_caller_identity.current.account_id}")

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "codebuild_example"
  }

  buildspec = yamlencode({
    version = "0.2"
    phases = {
      install = {
        commands = ["echo \"Installing dependencies\""]
      }
      build = {
        commands = ["echo \"Building the application\""]
      }
      post_build = {
        commands = [
          "echo \"Build completed on $(date)\"",
          "echo \"Packaging artifacts for upload to s3://${local.artifact_bucket_name}\"",
        ]
      }
    }
    artifacts = {
      files = ["**/*"]
    }
    cache = {
      paths = ["node_modules/**/*"]
    }
  })
}

###############################################################################
# S3 artifact bucket (build outputs + build cache)
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket = local.artifact_bucket_name

  tags = merge(local.common_tags, { Name = local.artifact_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

###############################################################################
# IAM role and least-privilege policy for CodeBuild
###############################################################################

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild_example_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "codebuild_example_role" })
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild_example_policy"
  description = "least_privilege_policy_for_the_example_codebuild_project"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
        ]
      },
      {
        Sid      = "ArtifactBucketList"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.artifacts.arn]
      },
      {
        Sid    = "ArtifactBucketReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Resource = ["${aws_s3_bucket.artifacts.arn}/*"]
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "codebuild_example_policy" })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

###############################################################################
# CloudWatch log group for build logs
###############################################################################

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "codebuild_example_logs" })
}

###############################################################################
# GitHub source credential backed by Secrets Manager
###############################################################################

resource "aws_secretsmanager_secret" "github_pat" {
  name        = "codebuild/github_pat"
  description = "github_personal_access_token_used_by_the_codebuild_source_credential"

  tags = merge(local.common_tags, { Name = "codebuild_github_pat" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "github_pat" {
  secret_id     = aws_secretsmanager_secret.github_pat.id
  secret_string = var.github_personal_access_token
}

resource "aws_codebuild_source_credential" "github_pat" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = aws_secretsmanager_secret_version.github_pat.secret_string
}

###############################################################################
# CodeBuild project
###############################################################################

resource "aws_codebuild_project" "codebuild_example" {
  name         = local.project_name
  description  = "example_codebuild_project_with_github_source_s3_artifacts_and_s3_cache"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type                = "GITHUB"
    location            = var.github_repository_url
    buildspec           = local.buildspec
    report_build_status = true
  }

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.artifacts.id
    packaging      = "ZIP"
    name           = "build_output"
    namespace_type = "BUILD_ID"
    path           = "builds"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.artifacts.id
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
      status     = "ENABLED"
    }
  }

  tags = merge(local.common_tags, { Name = local.project_name })

  depends_on = [aws_iam_role_policy_attachment.codebuild_policy]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Permitted static metadata lookups (pure local, no pre-existing remote state)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  project_name          = "example-codebuild-project"
  artifacts_bucket_name = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

# -----------------------------------------------------------------------------
# S3 bucket for CodeBuild build artifacts
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "codebuild_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = {
    Name = local.artifacts_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "codebuild_artifacts_bucket_policy" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.codebuild_artifacts.arn,
      "${aws_s3_bucket.codebuild_artifacts.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id
  policy = data.aws_iam_policy_document.codebuild_artifacts_bucket_policy.json
}

# -----------------------------------------------------------------------------
# CloudWatch log group for build logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30
}

# -----------------------------------------------------------------------------
# IAM trust policy shared by both CodeBuild roles
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    sid     = "AllowCodeBuildToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

# -----------------------------------------------------------------------------
# CodeBuild project service role + least-privilege policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_service_role" {
  name               = "codebuild-service-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

data "aws_iam_policy_document" "codebuild_service_policy" {
  statement {
    sid       = "ListArtifactsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.codebuild_artifacts.arn]
  }

  statement {
    sid    = "ReadWriteArtifactObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [
      aws_s3_bucket.codebuild_artifacts.arn,
      "${aws_s3_bucket.codebuild_artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "WriteBuildLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.codebuild_logs.arn,
      "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "codebuild_service_policy" {
  name        = "codebuild-service-policy"
  description = "Least-privilege permissions for the CodeBuild project service role"
  policy      = data.aws_iam_policy_document.codebuild_service_policy.json
}

resource "aws_iam_role_policy_attachment" "codebuild_service_policy_attach" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = aws_iam_policy.codebuild_service_policy.arn
}

# -----------------------------------------------------------------------------
# Dedicated batch service role + least-privilege policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_batch_role" {
  name               = "codebuild-batch-service-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

data "aws_iam_policy_document" "codebuild_batch_policy" {
  statement {
    sid    = "ManageProjectBuildsAndBuildBatches"
    effect = "Allow"
    actions = [
      "codebuild:StartBuildBatch",
      "codebuild:StopBuildBatch",
      "codebuild:RetryBuildBatch",
      "codebuild:StartBuild",
      "codebuild:StopBuild",
      "codebuild:RetryBuild",
    ]
    resources = [aws_codebuild_project.example.arn]
  }

  statement {
    sid    = "ManageCodeBuildEventBridgeRules"
    effect = "Allow"
    actions = [
      "events:PutTargets",
      "events:PutRule",
      "events:DescribeRule",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:events:${data.aws_region.current.name}:*:rule/codebuild*",
    ]
  }
}

resource "aws_iam_policy" "codebuild_batch_policy" {
  name        = "codebuild-batch-policy"
  description = "Least-privilege permissions for the CodeBuild batch service role"
  policy      = data.aws_iam_policy_document.codebuild_batch_policy.json
}

resource "aws_iam_role_policy_attachment" "codebuild_batch_policy_attach" {
  role       = aws_iam_role.codebuild_batch_role.name
  policy_arn = aws_iam_policy.codebuild_batch_policy.arn
}

# -----------------------------------------------------------------------------
# CodeBuild project with batch build configuration
# -----------------------------------------------------------------------------

resource "aws_codebuild_project" "example" {
  name         = local.project_name
  description  = "Example CodeBuild project with batch build configuration"
  service_role = aws_iam_role.codebuild_service_role.arn

  source {
    type      = "NO_SOURCE"
    buildspec = <<BUILDSPEC
version: 0.2

phases:
  install:
    commands:
      - echo "Install phase started on `date`"
      - aws --version
  build:
    commands:
      - echo "Build phase started on `date`"
      - mkdir -p build_output
      - echo "hello from CodeBuild" > build_output/hello.txt
  post_build:
    commands:
      - echo "Build phase completed on `date`"

artifacts:
  files:
    - 'build_output/**/*'
BUILDSPEC
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.codebuild_artifacts.id
    name           = "build-output"
    namespace_type = "BUILD_ID"
    packaging      = "ZIP"
    path           = "artifacts"
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  build_batch_config {
    service_role    = aws_iam_role.codebuild_batch_role.arn
    timeout_in_mins = 15

    restrictions {
      maximum_builds_allowed = 5
      compute_types_allowed  = ["BUILD_GENERAL1_SMALL"]
    }
  }

  tags = {
    Name = local.project_name
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "bot_name" {
  description = "Name of the Amazon Lex V2 pizza ordering bot."
  type        = string
  default     = "PizzaOrderingBot"
}

variable "environment" {
  description = "Environment label applied to the common tag set."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into the common tag set."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Project     = "pizza-ordering-bot"
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

# ---------------------------------------------------------------------------
# IAM: role assumed by the Lex bot, least-privilege inline policy for Polly
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "lex_bot_assume_role" {
  statement {
    sid     = "AllowLexV2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lexv2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lex_bot_polly" {
  statement {
    sid       = "AllowPollySpeechSynthesis"
    effect    = "Allow"
    actions   = ["polly:SynthesizeSpeech"]
    resources = ["*"]
  }
}

resource "aws_iam_role" "lex_bot_role" {
  name               = "${var.bot_name}-lex-role"
  description        = "Service role assumed by the pizza ordering Lex bot."
  assume_role_policy = data.aws_iam_policy_document.lex_bot_assume_role.json
}

resource "aws_iam_role_policy" "lex_bot_polly" {
  name   = "${var.bot_name}-polly-speech"
  role   = aws_iam_role.lex_bot_role.id
  policy = data.aws_iam_policy_document.lex_bot_polly.json
}

# ---------------------------------------------------------------------------
# Lex V2 bot and en_US locale (draft, with neural voice for spoken prompts)
# ---------------------------------------------------------------------------

resource "aws_lexv2models_bot" "pizza_ordering_bot" {
  name                        = var.bot_name
  description                 = "Conversational bot for ordering pizza with a drink or dessert followup."
  role_arn                    = aws_iam_role.lex_bot_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "US English locale for the pizza ordering bot."
  n_lu_intent_confidence_threshold = 0.7

  voice_settings {
    voice_id = "Joanna"
    engine   = "neural"
  }
}

# ---------------------------------------------------------------------------
# Custom slot types
# ---------------------------------------------------------------------------

resource "aws_lexv2models_slot_type" "crust_type" {
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id
  name        = "CrustType"
  description = "Available pizza crust options."

  slot_type_values {
    sample_value {
      value = "thin"
    }
  }

  slot_type_values {
    sample_value {
      value = "thick"
    }
  }

  slot_type_values {
    sample_value {
      value = "stuffed"
    }
  }

  value_selection_setting {
    resolution_strategy = "OriginalValue"
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

resource "aws_lexv2models_slot_type" "toppings" {
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id
  name        = "Toppings"
  description = "Available pizza toppings."

  slot_type_values {
    sample_value {
      value = "pepperoni"
    }
  }

  slot_type_values {
    sample_value {
      value = "sausage"
    }
  }

  slot_type_values {
    sample_value {
      value = "mushrooms"
    }
  }

  slot_type_values {
    sample_value {
      value = "onions"
    }
  }

  slot_type_values {
    sample_value {
      value = "green peppers"
    }
  }

  slot_type_values {
    sample_value {
      value = "black olives"
    }
  }

  slot_type_values {
    sample_value {
      value = "bacon"
    }
  }

  slot_type_values {
    sample_value {
      value = "pineapple"
    }
  }

  slot_type_values {
    sample_value {
      value = "extra cheese"
    }
  }

  value_selection_setting {
    resolution_strategy = "OriginalValue"
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

# ---------------------------------------------------------------------------
# Intents (slots are declared as standalone aws_lexv2models_slot resources)
# ---------------------------------------------------------------------------

resource "aws_lexv2models_intent" "order_pizza" {
  name        = "OrderPizza"
  description = "Captures a pizza order: kind, size, quantity, crust, and optional toppings."
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
    utterance = "I want to order a pizza"
  }

  sample_utterance {
    utterance = "I'd like to order a pizza"
  }

  sample_utterance {
    utterance = "pizza please"
  }

  sample_utterance {
    utterance = "order a pizza"
  }

  # Followup question: once the pizza is fully specified, ask about extras.
  confirmation_setting {
    prompt_specification {
      allow_interrupt = true
      max_retries     = 2

      message_group {
        message {
          plain_text_message {
            value = "Would you like to add a drink or dessert to your order?"
          }
        }
      }
    }

    confirmation_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Great! Let's get that added to your order."
          }
        }
      }
    }

    declination_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Okay, no problem."
          }
        }
      }
    }
  }

  closing_setting {
    active = true

    closing_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Awesome! Your pizza order is confirmed."
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

resource "aws_lexv2models_intent" "order_drink" {
  name        = "OrderDrink"
  description = "Followup intent that captures the drink added to the pizza order."
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
