    aws_lexv2models_slot.drink_kind,
    aws_lexv2models_slot.drink_size,
  ]
}

# Pizza Pal Kids - Lex V2 bot for ordering pizzas, designed for children.
# All resources are self-contained: IAM role, Lex V2 bot, locale, slot types,
# intent, and slot resources.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name applied as a tag to all taggable resources."
  type        = string
  default     = "pizza-pal-kids"
}

variable "environment" {
  description = "Environment applied as a tag to all taggable resources."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    project        = var.project_name
    environment    = var.environment
    child_directed = "true"
  }
}

# ------------------------------------------------------------------------------
# IAM service role trusted ONLY by the Lex V2 service principal, with a
# least-privilege inline policy (Polly speech synthesis + CloudWatch Logs writes)
# attached via a standalone aws_iam_role_policy resource.
# ------------------------------------------------------------------------------
resource "aws_iam_role" "lex_bot_service_role" {
  name        = "pizza-pal-kids-lex-bot-service-role"
  description = "Service role assumed only by the Pizza Pal Kids Amazon Lex V2 bot."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowLexV2ServiceToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "lex_bot_least_privilege" {
  name = "pizza-pal-kids-lex-bot-least-privilege"
  role = aws_iam_role.lex_bot_service_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SynthesizeKidFriendlySpeech"
        Effect   = "Allow"
        Action   = "polly:SynthesizeSpeech"
        Resource = "*"
      },
      {
        Sid    = "WriteLexConversationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:aws:logs:*:*:log-group:/aws/lex/*",
          "arn:aws:logs:*:*:log-group:/aws/lex/*:log-stream:*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Child-directed (COPPA) Lex V2 bot with a short idle session timeout for kids.
# depends_on guarantees the least-privilege policy attachment exists before the
# bot consumes the role, since Lex validates permissions at bot creation time.
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot" "pizza_pal_kids" {
  name                        = "PizzaPalKids"
  description                 = "A friendly pizza ordering assistant designed just for kids."
  role_arn                    = aws_iam_role.lex_bot_service_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = true
  }

  depends_on = [aws_iam_role_policy.lex_bot_least_privilege]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.pizza_pal_kids.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "English (US) locale with the kid-friendly Amazon Polly voice Ivy."
  n_lu_intent_confidence_threshold = 0.40

  voice_settings {
    voice_id = "Ivy"
  }
}

# ------------------------------------------------------------------------------
# Custom slot types with kid-friendly synonyms and misspelling tolerance.
# ------------------------------------------------------------------------------
resource "aws_lexv2models_slot_type" "pizza_size" {
