# ------------------------------------------------------------------------------
# Kid-friendly pizza ordering intent. No fulfillment Lambda or code hook is
# used; the intent completes with a built-in Close confirmation message.
#
# The three required slots (size, crust, toppings) are managed as separate
# aws_lexv2models_slot resources below. All are slot_constraint = "Required",
# so Lex elicits every slot before the intent closes regardless of elicitation
# order — the self-describing child prompts make the default order acceptable.
# slot_priority blocks are deliberately omitted: a priority entry referencing
# aws_lexv2models_slot.*.slot_id would create an unresolvable
# intent -> slot -> intent dependency cycle at plan time.
# ------------------------------------------------------------------------------
resource "aws_lexv2models_intent" "order_pizza_intent" {
  bot_id      = aws_lexv2models_bot.pizza_pal_kids.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id
  name        = "OrderPizza"
  description = "Lets kids order a pizza by answering three fun questions."

  sample_utterance {
    utterance = "i want a pizza"
  }

  sample_utterance {
    utterance = "make me a pizza please"
  }

  sample_utterance {
    utterance = "can i have a cheese pizza"
  }

  closing_setting {
    active = true

    closing_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Yay! One {size} pizza with {toppings} is coming up!"
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Slot resources: required slots elicited by the OrderPizza intent, using the
# V2 message structure (message_group -> message -> plain_text_message -> value)
# with gentle re-prompts for kids who misspeak.
# ------------------------------------------------------------------------------
resource "aws_lexv2models_slot" "pizza_size_slot" {
  bot_id       = aws_lexv2models_bot.pizza_pal_kids.id
  bot_version  = "DRAFT"
  intent_id    = aws_lexv2models_intent.order_pizza_intent.intent_id
  locale_id    = aws_lexv2models_bot_locale.en_us.locale_id
  name         = "size"
  slot_type_id = aws_lexv2models_slot_type.pizza_size.slot_type_id

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      allow_interrupt            = true
      max_retries                = 2
      message_selection_strategy = "Ordered"

      message_group {
        message {
          plain_text_message {
            value = "What size pizza do you want — small, medium, or large?"
          }
        }
      }

      message_group {
        message {
          plain_text_message {
            value = "No worries! Just pick one: small, medium, or large."
          }
        }
      }

      message_group {
        message {
          plain_text_message {
            value = "Almost there! Is your pizza small, medium, or large?"
          }
        }
      }
    }
  }
}

resource "aws_lexv2models_slot" "pizza_crust_slot" {
  bot_id       = aws_lexv2models_bot.pizza_pal_kids.id
  bot_version  = "DRAFT"
  intent_id    = aws_lexv2models_intent.order_pizza_intent.intent_id
  locale_id    = aws_lexv2models_bot_locale.en_us.locale_id
  name         = "crust"
  slot_type_id = aws_lexv2models_slot_type.pizza_crust.slot_type_id

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      allow_interrupt            = true
      max_retries                = 2
      message_selection_strategy = "Ordered"

      message_group {
        message {
          plain_text_message {
            value = "What kind of crust do you want — thin, regular, or thick?"
          }
        }
      }

      message_group {
        message {
          plain_text_message {
            value = "That's okay! Would you like a thin, regular, or thick crust?"
          }
        }
      }

      message_group {
        message {
          plain_text_message {
            value = "Pick a crust please: thin, regular, or thick!"
          }
        }
      }
    }
  }
}

resource "aws_lexv2models_slot" "pizza_toppings_slot" {
  bot_id       = aws_lexv2models_bot.pizza_pal_kids.id
  bot_version  = "DRAFT"
  intent_id    = aws_lexv2models_intent.order_pizza_intent.intent_id
  locale_id    = aws_lexv2models_bot_locale.en_us.locale_id
  name         = "toppings"
  slot_type_id = aws_lexv2models_slot_type.pizza_topping.slot_type_id

  multiple_values_setting {
    allow_multiple_values = true
  }

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      allow_interrupt            = true
      max_retries                = 2
      message_selection_strategy = "Ordered"

      message_group {
        message {
          plain_text_message {
            value = "What yummy toppings do you want? You can pick more than one, like cheese or pepperoni!"
          }
        }
      }

      message_group {
        message {
          plain_text_message {
            value = "No problem! Choose your favorite toppings, like cheese or pepperoni."
          }
        }
      }

      message_group {
        message {
          plain_text_message {
            value = "Last step! What toppings should I put on your pizza?"
          }
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "bot_name" {
  description = "User-controlled name of the child-friendly Lex V2 bot."
  type        = string
  default     = "children_assistant_bot"
}

variable "description" {
  description = "User-controlled description identifying the bot as a kid-friendly assistant."
  type        = string
  default     = "Kid-friendly assistant bot for children with age-appropriate conversation design and COPPA child-directed data handling."
}

variable "environment" {
  description = "User-controlled environment tag applied to tagged resources."
  type        = string
  default     = "dev"
}

resource "aws_iam_role" "lex_bot_runtime" {
  name        = "children-assistant-bot-runtime"
  description = "Runtime service role assumed by Amazon Lex V2 for the children assistant bot."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLexV2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name        = "children-assistant-bot-runtime"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "lex_bot_runtime" {
  name = "children-assistant-bot-runtime-policy"
  role = aws_iam_role.lex_bot_runtime.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LexRuntimeSpeechAndSentiment"
        Effect = "Allow"
        Action = [
          "polly:SynthesizeSpeech",
          "comprehend:DetectSentiment"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_lexv2models_bot" "children_bot" {
  name        = var.bot_name
  description = var.description
  role_arn    = aws_iam_role.lex_bot_runtime.arn

  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = true
  }

  tags = {
    Name        = var.bot_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  bot_version = "DRAFT"
  locale_id   = "en_US"

  description = "Child-friendly en_US locale using the Ivy neural voice."

  n_lu_intent_confidence_threshold = 0.40

  voice_settings {
    voice_id = "Ivy"
    engine   = "neural"
  }
}

resource "aws_lexv2models_intent" "greeting" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  bot_version = "DRAFT"
  locale_id   = "en_US"
  name        = "Greeting"

  description = "Age-appropriate greeting intent so children can say hi and hear what the bot can do."

  sample_utterance {
    utterance = "hi"
  }

  sample_utterance {
    utterance = "hello"
  }

  sample_utterance {
    utterance = "what can you do"
  }

  closing_setting {
    active = true

    closing_response {
      message_group {
        message {
          plain_text_message {
            value = "Hi friend! I am your buddy bot. You can say hi, hello, or ask me what I can do. See you soon!"
          }
        }
      }
    }
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us
  ]
}

resource "aws_lexv2models_bot_version" "children_bot_v1" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  description = "Stable numbered snapshot of the children assistant DRAFT bot for downstream consumers."

  locale_specification = {
    "en_US" = {
      source_bot_version = "DRAFT"
    }
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_intent.greeting
  ]
}

output "bot_id" {
  description = "Unique identifier of the children assistant Lex V2 bot."
  value       = aws_lexv2models_bot.children_bot.id
}

output "bot_arn" {
  description = "ARN of the children assistant Lex V2 bot."
  value       = aws_lexv2models_bot.children_bot.arn
}

output "bot_version" {
  description = "Stable numbered bot version created from the DRAFT locale snapshot."
  value       = aws_lexv2models_bot_version.children_bot_v1.bot_version
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "env" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

locals {
  stream_name  = "${var.env}-data-stream"
  kms_key_name = "${var.env}-kinesis-data-stream-key"

  common_tags = {
    Environment = var.env
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "kinesis" {
  description             = "Customer managed KMS key used for server-side encryption of the ${local.stream_name} Kinesis data stream."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = local.kms_key_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kinesis_stream" "data_stream" {
  name             = local.stream_name
  shard_count      = 1
  retention_period = 24

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  shard_level_metrics = [
    "IncomingBytes",
    "IncomingRecords",
    "OutgoingBytes",
    "OutgoingRecords",
    "WriteProvisionedThroughputExceeded",
    "ReadProvisionedThroughputExceeded",
    "IteratorAgeMilliseconds",
  ]

  tags = merge(local.common_tags, {
    Name = local.stream_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "data_stream_name" {
  description = "Name of the Kinesis data stream."
  value       = aws_kinesis_stream.data_stream.name
}

output "data_stream_arn" {
  description = "ARN of the Kinesis data stream."
  value       = aws_kinesis_stream.data_stream.arn
}

output "data_stream_shard_count" {
  description = "Number of shards in the Kinesis data stream."
  value       = aws_kinesis_stream.data_stream.shard_count
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for server-side encryption of the stream."
  value       = aws_kms_key.kinesis.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables: user-controlled, non-infrastructure values only (all defaulted so
# `terraform apply` runs unattended). No variable holds a secret or substitutes
# for a resource attribute.
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags to merge onto every taggable resource."
  type        = map(string)
  default     = {}
}

variable "vpc_cidr" {
  description = "CIDR block for the greenfield VPC hosting the Redshift cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "admin_cidr" {
  description = "Private CIDR of the administrator network allowed to reach Redshift on TCP 5439."
  type        = string
  default     = "192.168.0.0/16"
}

variable "destination_table_name" {
  description = "Redshift destination table for the Firehose COPY command (table DDL is managed out-of-band)."
  type        = string
  default     = "firehose_events"
}

# -----------------------------------------------------------------------------
# Static provider metadata lookup only (no infrastructure discovery).
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix          = "firehose-redshift-${var.environment}"
  firehose_stream_name = "firehose_redshift_${var.environment}"
  database_name        = "firehose_db"
  master_username      = "admin"

  # The exported `endpoint` attribute is in `hostname:port` form, so the JDBC
  # URL needs no separate port segment. Declared once so the Firehose
  # destination and the output are guaranteed consistent.
  redshift_jdbc_url = "jdbc:redshift://${aws_redshift_cluster.main.endpoint}/${aws_redshift_cluster.main.database_name}"

  common_tags = merge(var.tags, {
    Environment = var.environment
    Purpose     = "kinesis-firehose-redshift-delivery"
    ManagedBy   = "terraform"
  })
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Customer managed KMS key: used for S3 staging (SSE-KMS) and Redshift
# cluster-at-rest encryption.
# -----------------------------------------------------------------------------

resource "aws_kms_key" "firehose_redshift" {
  description             = "Key for Firehose S3 staging encryption (SSE-KMS) and Redshift cluster encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-key" })
}

# -----------------------------------------------------------------------------
# Redshift master credentials: generated at apply time, stored in Secrets
# Manager. Never a plaintext literal or a variable default. The same
# apply-time-generated password is injected directly into the Redshift cluster
# (`master_password`) and stored in the secret; the Firehose delivery stream
# resolves credentials at delivery time via dynamic references to the secret.
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length      = 32
  special     = false
  min_upper   = 2
  min_lower   = 2
  min_numeric = 2
}

resource "aws_secretsmanager_secret" "redshift_master_credentials" {
  name                    = "${local.name_prefix}-master-credentials"
  description             = "Master credentials for the ${local.name_prefix} Redshift cluster"
  recovery_window_in_days = 0

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "redshift_master_credentials" {
  secret_id = aws_secretsmanager_secret.redshift_master_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# Firehose intermediate staging bucket (SSE-KMS, versioned, fully blocked
# from public access, protected from destruction).
# -----------------------------------------------------------------------------

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_s3_bucket" "staging" {
  bucket = "${local.name_prefix}-staging-${random_string.bucket_suffix.result}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-staging" })
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.staging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.firehose_redshift.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "staging" {
  bucket = aws_s3_bucket.staging.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Redshift security group.
#
# Justification (objective 4): Redshift ingress is restricted to TCP 5439 only,
# sourced from the VPC CIDR and the administrator CIDR. AWS Kinesis Data
# Firehose connects from AWS public space to the cluster's publicly accessible
# endpoint, so port 5439 must be reachable by the Firehose service; no other
# ports and no unnecessary 0.0.0.0/0 rules are permitted.
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift access on TCP 5439 only: VPC and admin CIDRs, plus AWS Kinesis Data Firehose via the cluster's public endpoint. No other ports or 0.0.0.0/0."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift engine port 5439 from the VPC CIDR"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Redshift engine port 5439 from the administrator CIDR"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
}

# -----------------------------------------------------------------------------
# Redshift subnet group and parameter group (require_ssl enforces TLS on all
# connections, including the Firehose COPY command).
# -----------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for the ${local.name_prefix} Redshift cluster"
  subnet_ids  = aws_subnet.public[*].id

  tags = local.common_tags
}

resource "aws_redshift_parameter_group" "main" {
  name        = "${local.name_prefix}-params"
  family      = "redshift-1.0"
  description = "Enforce TLS for all Redshift connections including the Firehose COPY command"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# CloudWatch log groups for Firehose S3-delivery and Redshift-delivery errors.
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose_s3_delivery" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}-s3"
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "firehose_redshift_delivery" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}-redshift"
  retention_in_days = 30

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Firehose IAM role: least-privilege policy scoped to the staging bucket,
# the customer managed KMS key, the delivery error log groups, and read access
# to the single Redshift master credential secret (required so the
# `{{resolve:secretsmanager:...}}` dynamic references in the Redshift
# destination configuration resolve at delivery time).
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_delivery" {
  name               = "${local.name_prefix}-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "firehose_delivery" {
  statement {
    sid    = "StagingBucketAccess"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
    ]

    resources = [
      aws_s3_bucket.staging.arn,
      "${aws_s3_bucket.staging.arn}/*",
    ]
  }

  statement {
    sid    = "StagingBucketKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.firehose_redshift.arn]
  }

  statement {
    sid    = "DeliveryErrorLogging"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "${aws_cloudwatch_log_group.firehose_s3_delivery.arn}:*",
      "${aws_cloudwatch_log_group.firehose_redshift_delivery.arn}:*",
    ]
  }

  statement {
    sid    = "ReadRedshiftCredentials"
    effect = "Allow"

    actions = [
      "secretsmanager:GetSecretValue",
    ]

    resources = [aws_secretsmanager_secret.redshift_master_credentials.arn]
  }
}

resource "aws_iam_policy" "firehose_delivery" {
  name        = "${local.name_prefix}-delivery-policy"
  description = "Least-privilege permissions for the Firehose delivery stream (S3 staging, KMS, CloudWatch Logs, credential secret)"
  policy      = data.aws_iam_policy_document.firehose_delivery.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "firehose_delivery" {
  role       = aws_iam_role.firehose_delivery.name
  policy_arn = aws_iam_policy.firehose_delivery.arn
}

# -----------------------------------------------------------------------------
# Redshift cluster (publicly accessible so the Firehose service can reach the
# cluster endpoint, encrypted with the customer managed KMS key, master
# password injected directly from the apply-time random_password that is also
# stored in Secrets Manager — no plaintext literal, no variable default, and
# `master_password_secret_arn` is a computed-only attribute and is never set).
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier  = "${local.name_prefix}-cluster"
  cluster_type        = "single-node"
  node_type           = "dc2.large"
  database_name       = local.database_name
  master_username     = jsondecode(aws_secretsmanager_secret_version.redshift_master_credentials.secret_string)["username"]
  master_password     = random_password.redshift_master.result

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]

  publicly_accessible = true
  encrypted           = true
  kms_key_id          = aws_kms_key.firehose_redshift.arn

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream: for the Redshift destination the
# intermediate S3 staging configuration is nested inside
# `redshift_configuration` (required by the provider schema). Staging uses
# GZIP compression, SSE-KMS with the customer managed key, and 128 MB / 300 s
# buffering (`buffering_size`/`buffering_interval`, the v5 schema names for the
# Redshift-destination nested S3 block); Redshift credentials are dynamic
# references to Secrets Manager, resolvable by the stream role's scoped
# `secretsmanager:GetSecretValue` grant. The `cluster_jdbcurl` is composed
# from the exported `endpoint` attribute (`hostname:port` form) plus the
# database name — no separate port segment, matching the provider's documented
# Redshift-destination example.
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = local.firehose_stream_name
  destination = "redshift"

  redshift_configuration {
    role_arn        = aws_iam_role.firehose_delivery.arn
    cluster_jdbcurl = local.redshift_jdbc_url

    username = "{{resolve:secretsmanager:${aws_secretsmanager_secret.redshift_master_credentials.arn}:SecretString:username}}"
    password = "{{resolve:secretsmanager:${aws_secretsmanager_secret.redshift_master_credentials.arn}:SecretString:password}}"

    data_table_name = var.destination_table_name
    copy_options    = "GZIP"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_redshift_delivery.name
      log_stream_name = "RedshiftDelivery"
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery.arn
      bucket_arn         = aws_s3_bucket.staging.arn
      prefix             = "staging/"
      buffering_size     = 128
      buffering_interval = 300

      compression_format = "GZIP"
      kms_key_arn        = aws_kms_key.firehose_redshift.arn

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_s3_delivery.name
        log_stream_name = "S3Delivery"
      }
    }
  }

  depends_on = [aws_secretsmanager_secret_version.redshift_master_credentials]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs (metadata only — never secret values).
# -----------------------------------------------------------------------------

output "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.main.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.main.arn
}

output "staging_bucket_name" {
  description = "Name of the intermediate S3 staging bucket."
  value       = aws_s3_bucket.staging.id
}

output "staging_bucket_arn" {
  description = "ARN of the intermediate S3 staging bucket."
  value       = aws_s3_bucket.staging.arn
}

output "redshift_cluster_endpoint" {
  description = "Public endpoint of the Redshift cluster."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_cluster_jdbc_url" {
  description = "JDBC URL of the Redshift cluster used by the Firehose COPY command."
  value       = local.redshift_jdbc_url
}

output "redshift_cluster_port" {
  description = "Port the Redshift cluster listens on."
  value       = aws_redshift_cluster.main.port
}

output "redshift_database_name" {
  description = "Name of the Redshift database."
  value       = aws_redshift_cluster.main.database_name
}

output "redshift_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redshift master credentials."
  value       = aws_secretsmanager_secret.redshift_master_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Local, well-known lookup of the current account ID. Used only for the Firehose
# trust-policy external ID and to build a globally-unique S3 bucket name.
data "aws_caller_identity" "current" {}

locals {
  collection_name      = "firehose-aoss"
  index_name           = "firehose-events"
  delivery_stream_name = "firehose-aoss-delivery-stream"
  backup_bucket_name   = "firehose-aoss-backup-${data.aws_caller_identity.current.account_id}"
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources (e.g. environment, owner)."
  type        = map(string)

  default = {
    Environment = "dev"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }

  validation {
    condition     = length(var.common_tags) > 0
    error_message = "common_tags must contain at least one tag."
  }
}

# -----------------------------------------------------------------------------
# KMS: dedicated customer-managed key for the collection and backup bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  description             = "Dedicated key for the Firehose OpenSearch Serverless collection and S3 backup bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = var.common_tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/firehose-aoss"
  target_key_id = aws_kms_key.this.key_id
}

# -----------------------------------------------------------------------------
# OpenSearch Serverless: security policies (encryption + network), collection, data policy
# -----------------------------------------------------------------------------

resource "aws_opensearchserverless_security_policy" "encryption" {
  name = "firehose-aoss-encryption"
  type = "encryption"

  policy = jsonencode({
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${local.collection_name}"]
      }
    ]
    AWSOwnedKey = false
    KmsARN      = aws_kms_key.this.arn
  })
}

# Network policy for OpenSearch Serverless is managed through the
# aws_opensearchserverless_security_policy resource with type = "network".
# It is a JSON array of rule sets (unlike the encryption policy, which is a
# single JSON object) — do not merge the two policy documents into one resource.
resource "aws_opensearchserverless_security_policy" "network" {
  name = "firehose-aoss-network"
  type = "network"

  policy = jsonencode([
    {
      Description = "Public access to the collection endpoint; authorization is handled via IAM and the data access policy."
      Rules = [
        {
          ResourceType = "collection"
          Resource     = ["collection/${local.collection_name}"]
        }
      ]
      AllowFromPublic = true
    }
  ])
}

resource "aws_opensearchserverless_collection" "this" {
  name        = local.collection_name
  type        = "SEARCH"
  description = "OpenSearch Serverless collection fed by Kinesis Data Firehose."

  tags = var.common_tags

  depends_on = [
    aws_opensearchserverless_security_policy.encryption,
    aws_opensearchserverless_security_policy.network,
  ]
}

resource "aws_opensearchserverless_access_policy" "data" {
  name = "firehose-aoss-data-access"
  type = "data"

  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "index"
          Resource     = ["index/${local.collection_name}/*"]
          Permission = [
            "aoss:CreateIndex",
            "aoss:DescribeIndex",
            "aoss:UpdateIndex",
            "aoss:WriteDocument"
          ]
        },
        {
          ResourceType = "collection"
          Resource     = ["collection/${local.collection_name}"]
          Permission = [
            "aoss:CreateCollectionItems",
            "aoss:DescribeCollectionItems",
            "aoss:UpdateCollectionItems"
          ]
        }
      ]
      Principal   = [aws_iam_role.firehose.arn]
      Description = "Grants the Firehose delivery role access to auto-create indexes and ingest documents."
    }
  ])
}

# -----------------------------------------------------------------------------
# IAM: Firehose delivery role with least-privilege inline policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "firehose" {
  name = "firehose-aoss-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy" "firehose" {
  name = "firehose-aoss-delivery-access"
  role = aws_iam_role.firehose.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "OpenSearchServerlessAPIAccess"
        Effect   = "Allow"
        Action   = ["aoss:APIAccessAll"]
        Resource = [aws_opensearchserverless_collection.this.arn]
      },
      {
        Sid    = "S3BackupBucket"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.backup.arn]
      },
      {
        Sid    = "S3BackupObjects"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:AbortMultipartUpload",
          "s3:GetObject"
        ]
        Resource = ["${aws_s3_bucket.backup.arn}/*"]
      },
      {
        Sid      = "KmsKeyUse"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.this.arn]
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose.arn,
          "${aws_cloudwatch_log_group.firehose.arn}:*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# S3 backup bucket for failed/undeliverable documents
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "backup" {
  bucket = local.backup_bucket_name

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Logs for Firehose delivery error logging
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  retention_in_days = 30

  tags = var.common_tags
}

resource "aws_cloudwatch_log_stream" "firehose" {
  name           = "FirehoseDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream -> OpenSearch Serverless
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = local.delivery_stream_name
  destination = "opensearch"

  opensearch_configuration {
    role_arn              = aws_iam_role.firehose.arn
    cluster_endpoint      = aws_opensearchserverless_collection.this.collection_endpoint
    index_name            = local.index_name
    index_rotation_period = "NoRotation"
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_size        = 5
    buffering_interval    = 60
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.firehose.name
    }

    # S3 backup configuration for failed/undeliverable documents must be nested
    # inside the destination block for the "opensearch" destination.
    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.backup.arn
      prefix              = "failed-documents/"
      error_output_prefix = "failed-documents-errors/!{firehose:error-output-type}/"
      buffering_size      = 5
      buffering_interval  = 300
      compression_format  = "GZIP"
      kms_key_arn         = aws_kms_key.this.arn
    }
  }

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_opensearchserverless_access_policy.data,
    aws_iam_role_policy.firehose,
    aws_s3_bucket.backup,
    aws_s3_bucket_ownership_controls.backup,
    aws_s3_bucket_public_access_block.backup,
    aws_s3_bucket_server_side_encryption_configuration.backup,
    aws_s3_bucket_versioning.backup,
    aws_cloudwatch_log_group.firehose,
    aws_cloudwatch_log_stream.firehose,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "opensearch_serverless_collection_endpoint" {
  description = "OpenSearch Serverless collection endpoint used by the Firehose delivery stream."
  value       = aws_opensearchserverless_collection.this.collection_endpoint
}

output "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.this.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.this.arn
}

output "backup_bucket_name" {
  description = "Name of the S3 backup bucket for failed documents."
  value       = aws_s3_bucket.backup.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "stream_name_suffix" {
  description = "Unique suffix appended to the Kinesis Video Stream name to guarantee a unique stream name in the account/region."
  type        = string
  default     = "001"

  validation {
    condition     = can(regex("^[a-zA-Z0-9_-]+$", var.stream_name_suffix))
    error_message = "stream_name_suffix must contain only alphanumeric characters, hyphens, and underscores."
  }
}

variable "device_name" {
  description = "Name of the source device producing the media."
  type        = string
  default     = "default-camera-device"
}

variable "data_retention_in_hours" {
  description = "Number of hours the stream retains recorded media data (0-87600)."
  type        = number
  default     = 168

  validation {
    condition     = var.data_retention_in_hours >= 0 && var.data_retention_in_hours <= 87600
    error_message = "data_retention_in_hours must be between 0 and 87600."
  }
}

variable "environment" {
  description = "Environment tag value applied to the stream."
  type        = string
  default     = "dev"
}

locals {
  stream_name = "basic-video-stream-${var.stream_name_suffix}"
  media_type  = "video/h264"

  common_tags = {
    Name        = local.stream_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_kinesis_video_stream" "main" {
  name                    = local.stream_name
  device_name             = var.device_name
  media_type              = local.media_type
  data_retention_in_hours = var.data_retention_in_hours

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "stream_name" {
  description = "Name of the Kinesis Video Stream."
  value       = aws_kinesis_video_stream.main.name
}

output "stream_arn" {
  description = "ARN of the Kinesis Video Stream."
  value       = aws_kinesis_video_stream.main.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "application_name" {
  description = "Name of the Kinesis Data Analytics SQL application."
  type        = string
  default     = "kinesis_analytics_sql_app"
}

variable "shard_count" {
  description = "Number of shards for each provisioned Kinesis stream."
  type        = number
  default     = 1
}

variable "retention_period_hours" {
  description = "Data retention period (in hours) for the Kinesis streams."
  type        = number
  default     = 24
}

variable "log_retention_in_days" {
  description = "CloudWatch Logs retention period (in days) for the application log group."
  type        = number
  default     = 30
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the KMS key is deleted after destruction is requested."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "production"
    Application = "kinesis-analytics-sql"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  application_name   = var.application_name
  input_stream_name  = "${var.application_name}-input"
  output_stream_name = "${var.application_name}-output"
  log_group_name     = "/aws/kinesisanalytics/${var.application_name}"
  log_stream_name    = "${var.application_name}-application-logs"
  common_tags        = var.tags

  # Inline SQL transformation code executed by the SQL-1_0 runtime.
  # SOURCE_SQL_STREAM_001 is the in-application stream created from the
  # configured input name prefix; DESTINATION_SQL_STREAM is bound to the
  # configured output destination.
  sql_application_code = <<-EOT
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
        "TICKER_SYMBOL" VARCHAR(16),
        "SECTOR"        VARCHAR(16),
        "CHANGE"        REAL,
        "PRICE"         REAL
    );

    CREATE OR REPLACE PUMP "OUTPUT_PUMP" AS
        INSERT INTO "DESTINATION_SQL_STREAM"
        SELECT STREAM "TICKER_SYMBOL", "SECTOR", "CHANGE", "PRICE"
        FROM "SOURCE_SQL_STREAM_001"
        WHERE "CHANGE" > 0;
  EOT
}

# -----------------------------------------------------------------------------
# KMS key for encrypting streams, logs, and the analytics application
# -----------------------------------------------------------------------------

resource "aws_kms_key" "kinesis" {
  description             = "KMS key for the Kinesis Data Analytics SQL application, its Kinesis streams, and CloudWatch logs."
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.application_name}-kms-key"
  })
}

# -----------------------------------------------------------------------------
# Kinesis streams: SQL application source and destination
# -----------------------------------------------------------------------------

resource "aws_kinesis_stream" "input" {
  name             = local.input_stream_name
  shard_count      = var.shard_count
  retention_period = var.retention_period_hours

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.input_stream_name
  })
}

resource "aws_kinesis_stream" "output" {
  name             = local.output_stream_name
  shard_count      = var.shard_count
  retention_period = var.retention_period_hours

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.output_stream_name
  })
}

# -----------------------------------------------------------------------------
# CloudWatch logging for the analytics application
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = local.log_group_name
  retention_in_days = var.log_retention_in_days
  kms_key_id        = aws_kms_key.kinesis.arn

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# -----------------------------------------------------------------------------
# Service execution role for the analytics application
# -----------------------------------------------------------------------------

resource "aws_iam_role" "kinesis_analytics" {
  name        = "${local.application_name}-role"
  description = "Service execution role for the Kinesis Data Analytics SQL application."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.application_name}-role"
  })
}

resource "aws_iam_role_policy" "kinesis_analytics" {
  name = "${local.application_name}-inline-policy"
  role = aws_iam_role.kinesis_analytics.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadInputStream"
        Effect   = "Allow"
        Action   = ["kinesis:DescribeStream", "kinesis:GetShardIterator", "kinesis:GetRecords", "kinesis:ListShards"]
        Resource = aws_kinesis_stream.input.arn
      },
      {
        Sid      = "WriteOutputStream"
        Effect   = "Allow"
        Action   = ["kinesis:PutRecord", "kinesis:PutRecords"]
        Resource = aws_kinesis_stream.output.arn
      },
      {
        Sid    = "ApplicationCloudWatchLogs"
        Effect = "Allow"
        Action = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          aws_cloudwatch_log_group.kinesis_analytics.arn,
          aws_cloudwatch_log_stream.kinesis_analytics.arn
        ]
      },
      {
        Sid      = "KmsAccessForStreamsAndLogs"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.kinesis.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Kinesis Data Analytics V2 SQL application
# -----------------------------------------------------------------------------

resource "aws_kinesisanalyticsv2_application" "sql_app" {
  name                  = local.application_name
  description           = "Kinesis Data Analytics SQL application that reads records from the input stream, filters on price change, and writes results to the output stream."
  runtime_environment   = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics.arn
  start_application     = true

  application_configuration {
    application_code_configuration {
      code_content {
        text_content = local.sql_application_code
      }

      code_content_type = "PLAINTEXT"
    }

    sql_application_configuration {
      input {
        name_prefix = "SOURCE_SQL_STREAM"

        input_schema {
          record_encoding = "UTF-8"

          record_column {
            name     = "TICKER_SYMBOL"
            mapping  = "$.ticker_symbol"
            sql_type = "VARCHAR(16)"
          }

          record_column {
            name     = "SECTOR"
            mapping  = "$.sector"
            sql_type = "VARCHAR(16)"
          }

          record_column {
            name     = "CHANGE"
            mapping  = "$.change"
            sql_type = "REAL"
          }

          record_column {
            name     = "PRICE"
            mapping  = "$.price"
            sql_type = "REAL"
          }

          record_format {
            record_format_type = "JSON"

            mapping_parameters {
              json_mapping_parameters {
                record_row_path = "$"
              }
            }
          }
        }

        input_parallelism {
          count = 1
        }

        input_starting_position_configuration {
          input_starting_position = "LAST_STOPPED_POINT"
        }

        kinesis_streams_input {
          resource_arn = aws_kinesis_stream.input.arn
        }
      }

      output {
        name = "DESTINATION_SQL_STREAM"

        destination_schema {
          record_format_type = "JSON"
        }

        kinesis_streams_output {
          resource_arn = aws_kinesis_stream.output.arn
        }
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy.kinesis_analytics,
    aws_cloudwatch_log_stream.kinesis_analytics,
  ]

  tags = merge(local.common_tags, {
    Name = local.application_name
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a consistent tag across all resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  index_name = "kendra-index-${var.environment}"

  common_tags = {
    Name        = local.index_name
    Environment = var.environment
  }
}

resource "aws_kms_key" "kendra" {
  description             = "Customer managed KMS key used to encrypt the Kendra index and its CloudWatch log group"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kendra_kms_key.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kendra_kms_key" {
  statement {
    sid    = "EnableRootAccountFullControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowKendraServiceEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["kendra.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "kendra_index" {
  name               = "${local.index_name}-role"
  description        = "IAM role assumed by the Amazon Kendra service for index operations"
  assume_role_policy = data.aws_iam_policy_document.kendra_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "kendra_assume_role" {
  statement {
    sid    = "AllowKendraServiceAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kendra.amazonaws.com"]
    }
  }
}

resource "aws_cloudwatch_log_group" "kendra_index" {
  name              = "/aws/kendra/${local.index_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.kendra.arn
  tags              = local.common_tags
}

data "aws_iam_policy_document" "kendra_index_cloudwatch" {
  statement {
    sid       = "AllowKendraCreateLogGroups"
    effect    = "Allow"
    actions   = ["logs:CreateLogGroup"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowKendraWriteIndexLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.kendra_index.arn,
      "${aws_cloudwatch_log_group.kendra_index.arn}:*",
    ]
  }

  statement {
    sid       = "AllowKendraPublishMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "kendra_index_cloudwatch" {
  name   = "${local.index_name}-cloudwatch"
  role   = aws_iam_role.kendra_index.name
  policy = data.aws_iam_policy_document.kendra_index_cloudwatch.json
}

resource "aws_kendra_index" "main" {
  name        = local.index_name
  description = "Main Kendra index using the default document metadata configuration"
  role_arn    = aws_iam_role.kendra_index.arn
  edition     = "DEVELOPER_EDITION"

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra.arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_iam_role_policy.kendra_index_cloudwatch]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_route53_zone" "private_zone" {
  name = "internal.example53.com"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "internal.example53.com"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.private_zone.zone_id
  name    = "app.internal.example53.com"
  type    = "A"
  ttl     = 300
  records = ["10.0.1.10"]
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu"
  region = "eu-central-1"
}

variable "zone_name" {
  description = "Domain name for the primary public hosted zone."
  type        = string
  default     = "primary.example.com"
}

data "aws_availability_zones" "us" {
  state = "available"
}

data "aws_availability_zones" "eu" {
  provider = aws.eu
  state    = "available"
}

locals {
  record_name = "app"
  record_fqdn = "${local.record_name}.${aws_route53_zone.primary.name}"
}

resource "aws_route53_zone" "primary" {
  name = var.zone_name

  tags = {
    Name = "primary"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# us-east-1 networking (default provider)
# -----------------------------------------------------------------------------
resource "aws_vpc" "us" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = "primary-us-east-1"
    Region = "us-east-1"
  }
}

resource "aws_subnet" "us_a" {
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.us.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name   = "primary-us-east-1-public-a"
    Region = "us-east-1"
  }
}

resource "aws_subnet" "us_b" {
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.us.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name   = "primary-us-east-1-public-b"
    Region = "us-east-1"
  }
}

resource "aws_internet_gateway" "us" {
  vpc_id = aws_vpc.us.id

  tags = {
    Name   = "primary-us-east-1-igw"
    Region = "us-east-1"
  }
}

resource "aws_route_table" "us" {
  vpc_id = aws_vpc.us.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us.id
  }

  tags = {
    Name   = "primary-us-east-1-rt"
    Region = "us-east-1"
  }
}

resource "aws_route_table_association" "us_a" {
  subnet_id      = aws_subnet.us_a.id
  route_table_id = aws_route_table.us.id
}

resource "aws_route_table_association" "us_b" {
  subnet_id      = aws_subnet.us_b.id
  route_table_id = aws_route_table.us.id
}

resource "aws_security_group" "us" {
  name        = "primary-us-east-1-alb-sg"
  description = "Allow HTTP and HTTPS ingress to the us-east-1 routing-policy endpoint"
  vpc_id      = aws_vpc.us.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name   = "primary-us-east-1-alb-sg"
    Region = "us-east-1"
  }
}

resource "aws_lb" "us" {
  name               = "primary-us-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.us.id]
  subnets            = [aws_subnet.us_a.id, aws_subnet.us_b.id]

  depends_on = [
    aws_route_table_association.us_a,
    aws_route_table_association.us_b,
  ]

  tags = {
    Name   = "primary-us-east-1-alb"
    Region = "us-east-1"
  }
}

resource "aws_lb_target_group" "us" {
  name     = "primary-us-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.us.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name   = "primary-us-east-1-tg"
    Region = "us-east-1"
  }
}

resource "aws_lb_listener" "us" {
  load_balancer_arn = aws_lb.us.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

# -----------------------------------------------------------------------------
# eu-central-1 networking (aliased provider aws.eu)
# -----------------------------------------------------------------------------
resource "aws_vpc" "eu" {
  provider             = aws.eu
  cidr_block           = "10.1.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = "primary-eu-central-1"
    Region = "eu-central-1"
  }
}

resource "aws_subnet" "eu_a" {
  provider                = aws.eu
  vpc_id                  = aws_vpc.eu.id
  cidr_block              = "10.1.1.0/24"
  availability_zone       = data.aws_availability_zones.eu.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name   = "primary-eu-central-1-public-a"
    Region = "eu-central-1"
  }
}

resource "aws_subnet" "eu_b" {
  provider                = aws.eu
  vpc_id                  = aws_vpc.eu.id
  cidr_block              = "10.1.2.0/24"
  availability_zone       = data.aws_availability_zones.eu.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name   = "primary-eu-central-1-public-b"
    Region = "eu-central-1"
  }
}

resource "aws_internet_gateway" "eu" {
  provider = aws.eu
  vpc_id   = aws_vpc.eu.id

  tags = {
    Name   = "primary-eu-central-1-igw"
    Region = "eu-central-1"
  }
}

resource "aws_route_table" "eu" {
  provider = aws.eu
  vpc_id   = aws_vpc.eu.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eu.id
  }

  tags = {
    Name   = "primary-eu-central-1-rt"
    Region = "eu-central-1"
  }
}

resource "aws_route_table_association" "eu_a" {
  provider       = aws.eu
  subnet_id      = aws_subnet.eu_a.id
  route_table_id = aws_route_table.eu.id
}

resource "aws_route_table_association" "eu_b" {
  provider       = aws.eu
  subnet_id      = aws_subnet.eu_b.id
  route_table_id = aws_route_table.eu.id
}

resource "aws_security_group" "eu" {
  provider    = aws.eu
  name        = "primary-eu-central-1-alb-sg"
  description = "Allow HTTP and HTTPS ingress to the eu-central-1 routing-policy endpoint"
  vpc_id      = aws_vpc.eu.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name   = "primary-eu-central-1-alb-sg"
    Region = "eu-central-1"
  }
}

resource "aws_lb" "eu" {
  provider           = aws.eu
  name               = "primary-eu-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.eu.id]
  subnets            = [aws_subnet.eu_a.id, aws_subnet.eu_b.id]

  depends_on = [
    aws_route_table_association.eu_a,
    aws_route_table_association.eu_b,
  ]

  tags = {
    Name   = "primary-eu-central-1-alb"
    Region = "eu-central-1"
  }
}

resource "aws_lb_target_group" "eu" {
  provider = aws.eu
  name     = "primary-eu-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.eu.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name   = "primary-eu-central-1-tg"
    Region = "eu-central-1"
  }
}

resource "aws_lb_listener" "eu" {
  provider          = aws.eu
  load_balancer_arn = aws_lb.eu.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

# -----------------------------------------------------------------------------
# Route 53 health checks and latency-based routing records
# -----------------------------------------------------------------------------
resource "aws_route53_health_check" "us_east_1" {
  fqdn              = aws_lb.us.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 10
  measure_latency   = true

  tags = {
    Name   = "primary-us-east-1-health-check"
    Region = "us-east-1"
  }
}

resource "aws_route53_health_check" "eu_central_1" {
  fqdn              = aws_lb.eu.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 10
  measure_latency   = true

  tags = {
    Name   = "primary-eu-central-1-health-check"
    Region = "eu-central-1"
  }
}

resource "aws_route53_record" "primary_us_east_1" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier  = "us-east-1"
  health_check_id = aws_route53_health_check.us_east_1.id

  latency_routing_policy {
    region = "us-east-1"
  }

  alias {
    name                   = aws_lb.us.dns_name
    zone_id                = aws_lb.us.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "primary_eu_central_1" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier  = "eu-central-1"
  health_check_id = aws_route53_health_check.eu_central_1.id

  latency_routing_policy {
    region = "eu-central-1"
  }

  alias {
    name                   = aws_lb.eu.dns_name
    zone_id                = aws_lb.eu.zone_id
    evaluate_target_health = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "hosted_zone_name_servers" {
  description = "Name servers for the primary hosted zone (use these for registrar delegation)."
  value       = aws_route53_zone.primary.name_servers
}

output "record_fqdn" {
  description = "Fully qualified name of the latency-routed record."
  value       = local.record_fqdn
}

output "us_east_1_endpoint_dns_name" {
  description = "DNS name of the us-east-1 ALB endpoint."
  value       = aws_lb.us.dns_name
}

output "eu_central_1_endpoint_dns_name" {
  description = "DNS name of the eu-central-1 ALB endpoint."
  value       = aws_lb.eu.dns_name
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = "eks-cluster-1"

  validation {
    condition     = length(trimspace(var.cluster_name)) > 0
    error_message = "cluster_name must not be empty."
  }
}

variable "kubernetes_version" {
  description = "Kubernetes version for the EKS cluster control plane."
  type        = string
  default     = "1.30"

  validation {
    condition     = can(regex("^1\\.[0-9]{2}$", var.kubernetes_version))
    error_message = "kubernetes_version must be a valid Kubernetes minor version, e.g. \"1.30\"."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the EKS VPC."
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]
}

# ------------------------------------------------------------------------------
# Networking foundation
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                                        = "${var.cluster_name}-public-${count.index + 1}"
    "kubernetes.io/role/elb"                    = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                                        = "${var.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb"           = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.cluster_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Cluster endpoint security group
# ------------------------------------------------------------------------------

resource "aws_security_group" "cluster_endpoint" {
  name        = "${var.cluster_name}-cluster-endpoint-sg"
  description = "Restrict HTTPS (443) access to the ${var.cluster_name} EKS cluster endpoint to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound so the control plane can respond"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.cluster_name}-cluster-endpoint-sg"
  }
}

# ------------------------------------------------------------------------------
# IAM
# ------------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster_1" {
  name = "eks-cluster-1"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eks-cluster-1"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_1.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# ------------------------------------------------------------------------------
# EKS cluster
# ------------------------------------------------------------------------------

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  version  = var.kubernetes_version
  role_arn = aws_iam_role.eks_cluster_1.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.private[*].id, aws_subnet.public[*].id)
    security_group_ids      = [aws_security_group.cluster_endpoint.id]
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  tags = {
    Name = var.cluster_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "cluster_name" {
  description = "Name of the EKS cluster."
  value       = aws_eks_cluster.main.name
}

output "cluster_endpoint" {
  description = "Endpoint for the EKS Kubernetes API server."
  value       = aws_eks_cluster.main.endpoint
}

output "cluster_certificate_authority_data" {
  description = "Base64-encoded certificate authority data for the EKS cluster."
  value       = aws_eks_cluster.main.certificate_authority[0].data
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = "example"
}

variable "target_namespace" {
  description = "Kubernetes namespace that the access policy association is scoped to."
  type        = string
  default     = "default"
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    {
      ManagedBy   = "terraform"
      ClusterName = var.cluster_name
    },
    var.tags,
  )
}

###############################################################################
# Static provider metadata (greenfield-safe lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name                                        = "${var.cluster_name}-public-a"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name                                        = "${var.cluster_name}-public-b"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# IAM
###############################################################################

resource "aws_iam_role" "eks_cluster_role" {
  name        = "${var.cluster_name}-cluster-role"
  description = "Control-plane IAM role for the ${var.cluster_name} EKS cluster."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-cluster-role"
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "access_principal" {
  name        = "${var.cluster_name}-access-principal"
  description = "Access-entry principal granted scoped Kubernetes RBAC access."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-access-principal"
  })
}

###############################################################################
# KMS key for Kubernetes secrets envelope encryption
###############################################################################

resource "aws_kms_key" "eks_secrets" {
  description             = "EKS secrets envelope encryption key for cluster ${var.cluster_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-secrets-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# EKS cluster
###############################################################################

resource "aws_eks_cluster" "example" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids              = [aws_subnet.public_a.id, aws_subnet.public_b.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  access_config {
    authentication_mode                         = "API"
    bootstrap_cluster_creator_admin_permissions = true
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
  }

  tags = merge(local.common_tags, {
    Name = var.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
  ]
}

###############################################################################
# Access entry + namespace-scoped access policy association
###############################################################################

resource "aws_eks_access_entry" "access_principal" {
  cluster_name  = aws_eks_cluster.example.name
  principal_arn = aws_iam_role.access_principal.arn

  tags = merge(local.common_tags, {
    Name = "${var.cluster_name}-access-entry"
  })
}

resource "aws_eks_access_policy_association" "example" {
  cluster_name  = aws_eks_cluster.example.name
  policy_arn    = "arn:aws:eks::aws:cluster-access-policy/AmazonEKSViewPolicy"
  principal_arn = aws_iam_role.access_principal.arn

  access_scope {
    type       = "namespace"
    namespaces = [var.target_namespace]
  }

  depends_on = [
    aws_eks_access_entry.access_principal,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
