  }
}

resource "aws_iam_role" "eks_fargate_profile_role" {
  name        = "eks-fargate-profile-example"
  description = "Pod execution role for Amazon EKS Fargate profiles. Assumed by the eks-fargate-pods.amazonaws.com service principal to run pods on AWS Fargate."

