terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Base name for the S3 bucket. A random suffix is appended to guarantee cross-account global uniqueness."
  type        = string
  default     = "my_unique_bucket_name"
}

variable "allowed_referer" {
  description = "The aws:Referer StringLike pattern permitted to perform s3:GetObject. The only user-controlled, non-infrastructure input."
  type        = string
  default     = "https://www.example.com/*"
}

locals {
  # S3 bucket names must be lowercase and cannot contain underscores;
  # normalize the input base name before appending the random suffix.
  base_bucket_name = lower(replace(var.bucket_name, "_", "-"))
  bucket_name      = "${local.base_bucket_name}-${random_id.bucket_suffix.hex}"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "referer_bucket" {
  bucket = local.bucket_name

  tags = {
    Name        = local.bucket_name
    Description = "Bucket with referer-conditioned public GetObject access enforced via bucket policy"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ObjectOwnership = BucketOwnerEnforced disables ACLs entirely.
# All access control is enforced exclusively via the bucket policy.
# aws_s3_bucket_acl is deprecated and intentionally NOT used.
resource "aws_s3_bucket_ownership_controls" "referer_bucket_ownership" {
  bucket = aws_s3_bucket.referer_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# block_public_acls and ignore_public_acls remain enabled so all
# ACL-based public access vectors are fully blocked.
#
# Explicit justification for the exception:
# block_public_policy = false and restrict_public_buckets = false are
# required so the requested referer-conditioned public bucket policy
# (Principal "*") can take effect. Without this exception, AWS would
# reject the policy as publicly accessible. ACL-based vectors remain
# fully blocked, and the policy is the only public access path, further
# constrained by the aws:Referer condition and scoped to s3:GetObject.
resource "aws_s3_bucket_public_access_block" "referer_bucket_pab" {
  bucket = aws_s3_bucket.referer_bucket.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = false
  restrict_public_buckets = false
}

# SSE-S3 (AES256) is used instead of SSE-KMS because anonymous
# referer-gated GetObject requests cannot perform kms:Decrypt.
resource "aws_s3_bucket_server_side_encryption_configuration" "referer_bucket_encryption" {
  bucket = aws_s3_bucket.referer_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "referer_bucket_versioning" {
  bucket = aws_s3_bucket.referer_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "referer_policy" {
  statement {
    sid       = "AllowGetObjectsWithReferer"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = [aws_s3_bucket.referer_bucket.arn, "${aws_s3_bucket.referer_bucket.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringLike"
      variable = "aws:Referer"
      values   = [var.allowed_referer]
    }
  }
}

resource "aws_s3_bucket_policy" "referer_bucket_policy" {
  bucket = aws_s3_bucket.referer_bucket.id
  policy = data.aws_iam_policy_document.referer_policy.json

  # depends_on avoids the apply-time
  # "conflicting conditional operation is currently in progress" race
  # condition against the public access block and ownership controls.
  depends_on = [
    aws_s3_bucket_public_access_block.referer_bucket_pab,
    aws_s3_bucket_ownership_controls.referer_bucket_ownership,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Globally unique, lowercase, DNS-compliant name for the private S3 bucket."
  type        = string
  default     = "terraform-private-s3-bucket-example-001"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_owner_principal_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowBucketOwnerListBucket"
        Effect    = "Allow"
        Principal = {
          AWS = local.bucket_owner_principal_arn
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.this.arn
      },
      {
        Sid       = "AllowBucketOwnerGetObject"
        Effect    = "Allow"
        Principal = {
          AWS = local.bucket_owner_principal_arn
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_ownership_controls.this
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

output "ami_id" {
  description = "The ID of the latest Amazon Linux 2 AMI"
  value       = data.aws_ami.amazon_linux_2.id
}

output "ami_name" {
  description = "The name of the resolved Amazon Linux 2 AMI"
  value       = data.aws_ami.amazon_linux_2.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for consistent resource tagging."
  type        = string
  default     = "production"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  fleet_instance_name = "${var.environment}-fleet-instance"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.environment}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.environment}-igw" })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${var.environment}-public-subnet" })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${var.environment}-private-subnet" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${var.environment}-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, { Name = "${var.environment}-nat-gw" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-private-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_iam_role" "ec2_fleet_role" {
  name_prefix = "ec2-fleet-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.environment}-ec2-fleet-role" })
}

resource "aws_iam_role_policy_attachment" "ec2_fleet_ssm" {
  role       = aws_iam_role.ec2_fleet_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_fleet_profile" {
  name_prefix = "ec2-fleet-profile-"
  role        = aws_iam_role.ec2_fleet_role.name

  tags = merge(local.common_tags, { Name = "${var.environment}-ec2-fleet-profile" })

  depends_on = [aws_iam_role_policy_attachment.ec2_fleet_ssm]
}

resource "aws_security_group" "fleet_sg" {
  name_prefix = "ec2-fleet-sg-"
  description = "Security group for the EC2 Fleet instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-fleet-sg" })
}

resource "aws_launch_template" "on_demand" {
  name_prefix   = "fleet-on-demand-"
  description   = "On-Demand launch template for the EC2 Fleet"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.medium"
  ebs_optimized = true

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_profile.name
  }

  network_interfaces {
    associate_public_ip_address = false
    security_groups             = [aws_security_group.fleet_sg.id]
    device_index                = 0
    delete_on_termination       = true
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 20
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, { Name = local.fleet_instance_name })
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-on-demand-launch-template" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_launch_template" "spot" {
  name_prefix   = "fleet-spot-"
  description   = "Spot launch template for the EC2 Fleet"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.medium"
  ebs_optimized = true

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_profile.name
  }

  network_interfaces {
    associate_public_ip_address = false
    security_groups             = [aws_security_group.fleet_sg.id]
    device_index                = 0
    delete_on_termination       = true
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 20
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  instance_market_options {
    market_type = "spot"
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, { Name = local.fleet_instance_name })
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-spot-launch-template" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ec2_fleet" "main" {
  type = "maintain"

  target_capacity_specification {
    total_target_capacity        = 9
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
    default_target_capacity_type = "on-demand"
  }

  on_demand_options {
    allocation_strategy = "prioritized"
  }

  spot_options {
    allocation_strategy         = "capacity-optimized"
    instance_pools_to_use_count = 2
  }

  replace_unhealthy_instances         = true
  terminate_instances                 = true
  terminate_instances_with_expiration = true

  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.on_demand.id
      version            = aws_launch_template.on_demand.latest_version
    }

    override {
      instance_type = "t3.medium"
      priority      = 1
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3.large"
      priority      = 2
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.medium"
      priority      = 3
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.large"
      priority      = 4
      subnet_id     = aws_subnet.private.id
    }
  }

  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.spot.id
      version            = aws_launch_template.spot.latest_version
    }

    override {
      instance_type = "t3.medium"
      priority      = 5
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3.large"
      priority      = 6
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.medium"
      priority      = 7
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.large"
      priority      = 8
      subnet_id     = aws_subnet.private.id
    }
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-ec2-fleet" })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables (all non-sensitive defaults)
# ------------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and the Name tag convention."
  type        = string
  default     = "memcached-cluster"
}

variable "environment" {
  description = "Deployment environment used for naming and tagging."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC hosting the Memcached cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "num_cache_nodes" {
  description = "Number of Memcached cache nodes. A value of 2 or more enables multi-node auto-discovery."
  type        = number
  default     = 2

  validation {
    condition     = var.num_cache_nodes >= 1 && var.num_cache_nodes <= 40
    error_message = "num_cache_nodes must be between 1 and 40."
  }
}

variable "node_type" {
  description = "ElastiCache node type for the Memcached cluster."
  type        = string
  default     = "cache.t3.small"
}

variable "engine_version" {
  description = "Supported Memcached engine version (1.6.x series)."
  type        = string
  default     = "1.6.22"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  name = var.project_name

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-subnet-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Security group (Memcached TCP 11211 from the VPC CIDR only)
# ------------------------------------------------------------------------------

resource "aws_security_group" "memcached" {
  name        = "${local.name}-sg"
  description = "Allow inbound Memcached traffic on TCP 11211 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Memcached client traffic from within the VPC"
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-sg"
  })
}

# ------------------------------------------------------------------------------
# ElastiCache Memcached cluster
# ------------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "memcached" {
  name       = "${local.name}-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-group"
  })
}

resource "aws_elasticache_cluster" "memcached" {
  cluster_id = "${local.name}-${var.environment}"
  engine     = "memcached"

  engine_version       = var.engine_version
  node_type            = var.node_type
  num_cache_nodes      = var.num_cache_nodes
  parameter_group_name = "default.memcached1.6"
  port                 = 11211

  subnet_group_name  = aws_elasticache_subnet_group.memcached.name
  security_group_ids = [aws_security_group.memcached.id]

  # Spread nodes across AZs when running more than one node for high availability.
  az_mode = var.num_cache_nodes > 1 ? "cross-az" : "single-az"

  # Maintenance best practices. Memcached does not support snapshots, so no
  # snapshot settings apply; automatic minor version upgrades keep the 1.6.x
  # engine current. notification_topic_arn is intentionally omitted because no
  # SNS topic is created in this configuration.
  maintenance_window         = "sun:05:00-sun:07:00"
  auto_minor_version_upgrade = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "memcached_configuration_endpoint" {
  description = "Configuration endpoint (address and port) for Memcached client auto-discovery."
  value       = aws_elasticache_cluster.memcached.configuration_endpoint
}

output "memcached_port" {
  description = "Port that the Memcached cluster listens on."
  value       = aws_elasticache_cluster.memcached.port
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to the tags of all resources."
  type        = string
  default     = "production"
}

locals {
  elasticache_user_name = "cache_app_user"

  tags = {
    Name        = "elasticache-user-${local.elasticache_user_name}"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_password" "elasticache_user_password" {
  length           = 32
  lower            = true
  upper            = true
  numeric          = true
  special          = true
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "elasticache_user_credential" {
  name        = "elasticache/${local.elasticache_user_name}"
  description = "Credential for the ElastiCache Redis ACL user ${local.elasticache_user_name}."
  tags        = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "elasticache_user_credential" {
  secret_id = aws_secretsmanager_secret.elasticache_user_credential.id
  secret_string = jsonencode({
    username = local.elasticache_user_name
    password = random_password.elasticache_user_password.result
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user" "cache_app_user" {
  user_id       = local.elasticache_user_name
  user_name     = local.elasticache_user_name
  engine        = "REDIS"
  access_string = "on ~app:* -@all +@read +@write -@dangerous"

  authentication_mode {
    type      = "password"
    passwords = [random_password.elasticache_user_password.result]
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "common_tags" {
  description = "Additional common tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix     = "redshift-${var.environment}"
  master_username = "redshiftadmin"
  database_name   = "analyticsdb"

  common_tags = merge(
    var.common_tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}-master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-b"
  })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Restrict Redshift access to the VPC CIDR on the Redshift port"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets across two AZs for the Redshift cluster"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-group"
  })
}

resource "aws_kms_key" "redshift" {
  description             = "Customer managed KMS key used to encrypt the Redshift cluster"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "wlm_json_configuration"
    value = jsonencode([
      {
        auto_wlm            = true
        concurrency_scaling = "auto"
      },
    ])
  }

  parameter {
    name  = "max_concurrency_scaling_clusters"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-parameter-group"
  })
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = "${local.name_prefix}-cluster"
  database_name                       = local.database_name
  cluster_type                        = "multi-node"
  node_type                           = "ra3.xlplus"
  number_of_nodes                     = 2
  master_username                     = local.master_username
  master_password                     = random_password.redshift_master.result
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name        = aws_redshift_parameter_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  port                                = 5439
  publicly_accessible                 = false
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  cluster_version                     = "1.0"
  automated_snapshot_retention_period = 7
  preferred_maintenance_window        = "sun:04:30-sun:05:30"
  allow_version_upgrade               = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

resource "aws_redshift_usage_limit" "concurrency_scaling_daily" {
  cluster_identifier = aws_redshift_cluster.main.cluster_identifier
  feature_type       = "concurrency-scaling"
  limit_type         = "time"
  amount             = 60
  period             = "daily"
  breach_action      = "disable"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-concurrency-scaling-limit"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data sources (pure static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Variables (non-infrastructure values only; all defaulted for unattended apply)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "redshift-ha"
}

variable "environment" {
  description = "Value used for the Environment tag."
  type        = string
  default     = "production"
}

variable "managed_by" {
  description = "Value used for the ManagedBy tag."
  type        = string
  default     = "terraform"
}

variable "master_username" {
  description = "Admin username for the Redshift cluster. The password is generated by random_password and stored in Secrets Manager."
  type        = string
  default     = "redshiftadmin"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix   = var.project_name
  database_name = "analytics_db"
  log_prefix    = "audit-logs/"

  common_tags = {
    Environment = var.environment
    ManagedBy   = var.managed_by
    Project     = var.project_name
  }
}

# -----------------------------------------------------------------------------
# Network foundation: VPC + one subnet per AZ (us-east-1a / us-east-1b)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "redshift_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-a"
  })
}

resource "aws_subnet" "redshift_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-b"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route_table_association" "redshift_a" {
  subnet_id      = aws_subnet.redshift_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "redshift_b" {
  subnet_id      = aws_subnet.redshift_b.id
  route_table_id = aws_route_table.main.id
}

# S3 gateway endpoint so COPY/UNLOAD and audit log delivery work without internet access.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  })
}

# -----------------------------------------------------------------------------
# Security group: ingress on 5439 restricted to the VPC CIDR only
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-cluster-sg"
  description = "Restrict Redshift access to the VPC CIDR; S3 access via gateway endpoint"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift SQL connections from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Cluster-internal leader/compute node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Cluster-internal leader/compute node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description     = "HTTPS to Amazon S3 through the gateway endpoint"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.s3.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster-sg"
  })
}

# -----------------------------------------------------------------------------
# KMS encryption key and alias for the cluster and audit log bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Key for Redshift cluster encryption and audit log bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdmin"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowRedshiftLogDelivery"
        Effect    = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift-key"
  target_key_id = aws_kms_key.redshift.key_id
}

# -----------------------------------------------------------------------------
# Master credentials: generated, stored in Secrets Manager, never plaintext
# -----------------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%*+-_="
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}-master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.redshift_master.result
    engine   = "redshift"
    port     = 5439
    dbname   = local.database_name
  })
}

# -----------------------------------------------------------------------------
# S3 audit log bucket (private, KMS-encrypted, versioned)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "audit_logs" {
  bucket = "${local.name_prefix}-audit-logs-${random_id.suffix.hex}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-audit-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.redshift.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "audit_logs_bucket" {
  statement {
    sid       = "RedshiftLogDeliveryAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.audit_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }

  statement {
    sid       = "RedshiftLogDeliveryPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.audit_logs.arn}/${local.log_prefix}*"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id
  policy = data.aws_iam_policy_document.audit_logs_bucket.json
}

# -----------------------------------------------------------------------------
# IAM role assumed by Redshift (least privilege, scoped to the audit log bucket)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "redshift_s3_access" {
  statement {
    sid       = "ListAuditLogBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.audit_logs.arn]
  }

  statement {
    sid       = "ReadWriteAuditLogBucketObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${aws_s3_bucket.audit_logs.arn}/*"]
  }

  statement {
    sid       = "UseRedshiftKmsKey"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_key.redshift.arn]
  }
}

resource "aws_iam_role" "redshift_s3" {
  name               = "${local.name_prefix}-s3-role"
  description        = "Role assumed by the Redshift cluster for S3 access"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-role"
  })
}

resource "aws_iam_policy" "redshift_s3_access" {
  name        = "${local.name_prefix}-s3-access"
  description = "Least-privilege S3 and KMS access for the Redshift cluster"
  policy      = data.aws_iam_policy_document.redshift_s3_access.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-access"
  })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_access" {
  role       = aws_iam_role.redshift_s3.name
  policy_arn = aws_iam_policy.redshift_s3_access.arn
}

# -----------------------------------------------------------------------------
# Redshift prerequisites: multi-AZ subnet group and hardened parameter group
# -----------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Multi-AZ subnet group spanning us-east-1a and us-east-1b"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-group"
  })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-params"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-params"
  })
}

# -----------------------------------------------------------------------------
# Highly available Redshift cluster (multi-AZ across two subnets)
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  # AWS cluster identifiers permit lowercase letters and hyphens only (no underscores)
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = local.database_name

  master_username = var.master_username

  node_type       = "ra3.xlplus"
  cluster_type    = "multi-node"
  number_of_nodes = 2
  multi_az        = true

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  publicly_accessible          = false
  port                         = 5439

  encrypted            = true
  kms_key_id           = aws_kms_key.redshift.arn
  enhanced_vpc_routing = true

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-cluster-final-${random_id.suffix.hex}"

  preferred_maintenance_window = "sun:01:00-sun:03:00"
  allow_version_upgrade        = true

  iam_roles = [aws_iam_role.redshift_s3.arn]

  logging {
    enable        = true
    bucket_name   = aws_s3_bucket.audit_logs.id
    s3_key_prefix = local.log_prefix
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  # Ensure the secret payload (containing the password key) exists before
  # Redshift consumes the secret during cluster creation.
  depends_on = [aws_secretsmanager_secret_version.redshift_master]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs (no master password or secret value exposed)
# -----------------------------------------------------------------------------

output "redshift_cluster_endpoint" {
  description = "Connection endpoint of the Redshift cluster (host:port)."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_cluster_port" {
  description = "Port on which the Redshift cluster accepts connections."
  value       = aws_redshift_cluster.main.port
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  cluster_identifier = "redshift-main"
  database_name      = "dev"
  master_username    = "adminuser"
  redshift_port      = 5439

  common_tags = {
    Project   = "redshift-main"
    ManagedBy = "terraform"
  }
}

variable "admin_cidr" {
  description = "Optional additional CIDR block (besides the VPC CIDR) allowed to reach the Redshift endpoint on TCP 5439. Must never be 0.0.0.0/0."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = var.admin_cidr != "0.0.0.0/0" && can(cidrnetmask(var.admin_cidr))
    error_message = "admin_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

###############################################################################
# Network foundation (greenfield): VPC, public subnets, IGW and routing so the
# Redshift cluster can be exposed through a publicly accessible endpoint.
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-vpc"
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "redshift-main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "redshift-main-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-main-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "redshift-main-subnet-group"
  })
}

###############################################################################
# Security group for the cluster. TCP 5439 is the Redshift wire-protocol port,
# so ingress on that port is required for any client to reach the publicly
# accessible cluster endpoint requested for this deployment.
###############################################################################

resource "aws_security_group" "redshift" {
  name        = "redshift-main-sg"
  description = "Access to the redshift-main Redshift cluster endpoint (TCP 5439)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift wire protocol (TCP 5439) from within the VPC"
    from_port   = local.redshift_port
    to_port     = local.redshift_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Redshift wire protocol (TCP 5439) from the admin CIDR"
    from_port   = local.redshift_port
    to_port     = local.redshift_port
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Allow all outbound traffic (cluster maintenance, S3 and KMS access)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "redshift-main-sg"
  })
}

###############################################################################
# Customer-managed encryption key used for cluster encryption at rest.
###############################################################################

resource "aws_kms_key" "redshift" {
  description             = "Customer-managed key used to encrypt the redshift-main Redshift cluster at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Master credentials: the password is generated at apply time, satisfies the
# Redshift password policy, and is stored only in Secrets Manager. The value is
# never written into the configuration, locals, or variable defaults.
###############################################################################

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  # Redshift forbids '/', '"', "'", '@' and spaces in master passwords
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "redshift-main-master-credentials"
  description = "Master credentials for the redshift-main Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, {
    Name = "redshift-main-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

###############################################################################
# Redshift cluster: 2 x ra3.xlplus multi-node cluster with a publicly
# accessible endpoint, encrypted at rest with the customer-managed KMS key.
# With skip_final_snapshot = false the provider always takes a final snapshot
# named by final_snapshot_identifier on destroy.
###############################################################################

resource "aws_redshift_cluster" "redshift_main" {
  cluster_identifier = local.cluster_identifier
  database_name      = local.database_name
  master_username    = local.master_username
  master_password    = random_password.redshift_master.result

  node_type       = "ra3.xlplus"
  cluster_type    = "multi-node"
  number_of_nodes = 2
  port            = local.redshift_port

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = true

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.cluster_identifier}-final-snapshot"

  automated_snapshot_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "redshift-main"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs: connection details for clients. Only the secret ARN is exposed,
# never the secret value itself.
###############################################################################

output "redshift_endpoint_address" {
  description = "Full Redshift connection endpoint string for the redshift-main cluster (host:port/database) — this is the canonical endpoint attribute, not just the hostname"
  value       = aws_redshift_cluster.redshift_main.endpoint
}

output "redshift_endpoint_port" {
  description = "Port of the redshift-main Redshift cluster endpoint"
  value       = aws_redshift_cluster.redshift_main.port
}

output "redshift_database_name" {
  description = "Initial database name on the redshift-main Redshift cluster"
  value       = aws_redshift_cluster.redshift_main.database_name
}

output "redshift_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (secret value is never exposed)"
  value       = aws_secretsmanager_secret.redshift_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as user-controlled tagging metadata only. Has a default so terraform apply runs unattended."
  type        = string
  default     = "dev"
}

locals {
  function_name      = "hello-app"
  handler            = "index.lambda_handler"
  runtime            = "python3.12"
  memory_size        = 256
  timeout            = 30
  log_retention_days = 14

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Lambda execution role (least privilege: basic execution policy only)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${local.function_name}-execution-role"
  description        = "Execution role for the ${local.function_name} Lambda function"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.function_name}-execution-role"
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# -----------------------------------------------------------------------------
# Handler source code and self-contained deployment package
# -----------------------------------------------------------------------------

resource "local_file" "handler" {
  filename = "${path.module}/src/index.py"
  content  = <<-EOF
    import json


    def lambda_handler(event, context):
        return {
            "statusCode": 200,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"message": "Hello from ${local.function_name}!"}),
        }
  EOF

  file_permission = "0644"
}

data "archive_file" "package" {
  type        = "zip"
  source_file = local_file.handler.filename
  output_path = "${path.module}/build/${local.function_name}.zip"
}

# -----------------------------------------------------------------------------
# Lambda function with published versions and a live alias
# -----------------------------------------------------------------------------

resource "aws_lambda_function" "app" {
  function_name = local.function_name
  description   = "Application Lambda function managed by Terraform"

  role    = aws_iam_role.lambda_exec.arn
  runtime = local.runtime
  handler = local.handler

  filename         = data.archive_file.package.output_path
  source_code_hash = data.archive_file.package.output_base64sha256

  memory_size = local.memory_size
  timeout     = local.timeout

  architectures = ["arm64"]

  # publish = true emits a numbered, immutable version on every deploy.
  # Aliases cannot point at $LATEST, so publishing is required for the alias below.
  publish = true

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_cloudwatch_log_group.app,
  ]

  tags = merge(local.common_tags, {
    Name = local.function_name
  })
}

resource "aws_lambda_alias" "live" {
  name             = "live"
  description      = "Points at the latest published version of the ${local.function_name} function"
  function_name    = aws_lambda_function.app.function_name
  function_version = aws_lambda_function.app.version
}

# -----------------------------------------------------------------------------
# CloudWatch log group with enforced retention for the function's logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "app" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = local.log_retention_days

  tags = merge(local.common_tags, {
    Name = "/aws/lambda/${local.function_name}"
  })
}

# -----------------------------------------------------------------------------
# Outputs for downstream consumers
# -----------------------------------------------------------------------------

output "lambda_function_arn" {
  description = "Unqualified ARN of the Lambda function."
  value       = aws_lambda_function.app.arn
}

output "lambda_function_qualified_arn" {
  description = "Qualified ARN (pinned to the latest published version) of the Lambda function."
  value       = aws_lambda_function.app.qualified_arn
}

output "lambda_alias_arn" {
  description = "ARN of the live alias pointing at the latest published version."
  value       = aws_lambda_alias.live.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  name           = "test_lambda"
  log_group_name = "/aws/lambda/${local.name}"

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  log_group_arn = "arn:aws:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"

  lambda_handler_source = <<-PY
import json
import logging

LOGGER = logging.getLogger()
LOGGER.setLevel(logging.INFO)


def lambda_handler(event, context):
    LOGGER.info("Received EventBridge event: %s", json.dumps(event, default=str))

    detail = event.get("detail", {}) or {}
    image_id = detail.get("image-id", "unknown")
    state = detail.get("state", "unknown")
    region = event.get("region", "unknown")

    LOGGER.info("AMI %s in region %s transitioned to state %s", image_id, region, state)

    return {
        "statusCode": 200,
        "body": json.dumps(
            {
                "message": f"AMI {image_id} is {state}",
                "imageId": image_id,
                "state": state,
                "region": region,
            }
        ),
    }
PY

  common_tags = {
    Name        = local.name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role" "test_lambda_exec" {
  name        = "test_lambda_exec_role"
  description = "Execution role for the test_lambda function."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "test_lambda_logging" {
  name        = "test_lambda_logging"
  description = "Least-privilege CloudWatch Logs access for the test_lambda function."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CreateFunctionLogGroup"
        Effect   = "Allow"
        Action   = "logs:CreateLogGroup"
        Resource = local.log_group_arn
      },
      {
        Sid    = "WriteFunctionLogStreams"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${local.log_group_arn}:*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "test_lambda_logging" {
  role       = aws_iam_role.test_lambda_exec.name
  policy_arn = aws_iam_policy.test_lambda_logging.arn
}

resource "aws_cloudwatch_log_group" "test_lambda" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = local.common_tags
}

data "archive_file" "test_lambda_payload" {
  type        = "zip"
  output_path = "${path.module}/test_lambda_payload.zip"

  source {
    content  = local.lambda_handler_source
    filename = "lambda_function.py"
  }
}

resource "aws_lambda_function" "test_lambda" {
  function_name = local.name
  description   = "Invoked by EventBridge when a new EC2 AMI becomes available."
  role          = aws_iam_role.test_lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"
  filename      = data.archive_file.test_lambda_payload.output_path
  source_code_hash = data.archive_file.test_lambda_payload.output_base64sha256
  timeout       = 30
  memory_size   = 256

  depends_on = [
    aws_cloudwatch_log_group.test_lambda,
    aws_iam_role_policy_attachment.test_lambda_logging
  ]

  tags = local.common_tags
}

resource "aws_cloudwatch_event_rule" "ec2_ami_available" {
  name        = "ec2-ami-available-${local.name}"
  description = "Matches EC2 AMI state change events and triggers ${local.name} when a new AMI becomes available."

  event_pattern = jsonencode({
    source        = ["aws.ec2"]
    "detail-type" = ["EC2 AMI State Change"]
    detail = {
      state = ["available"]
    }
  })

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "test_lambda" {
  rule      = aws_cloudwatch_event_rule.ec2_ami_available.name
  target_id = local.name
  arn       = aws_lambda_function.test_lambda.arn
}

resource "aws_lambda_permission" "test_lambda_from_eventbridge" {
  statement_id  = "AllowEventBridgeRuleInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.test_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.ec2_ami_available.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "cw-alarm-demo"
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "alarm_notification_email" {
  description = "Email address that receives CloudWatch alarm notifications."
  type        = string
  default     = "ops-team@example.com"
}

locals {
  tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_sqs_queue" "main" {
  name                       = "${var.project_name}-main-queue"
  visibility_timeout_seconds = 300
  message_retention_seconds  = 345600

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchAlarmsToUseKeyForPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "alarm_notifications" {
  description             = "CMK used for server-side encryption of the CloudWatch alarm notification SNS topic."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "alarm_notifications" {
  name              = "${var.project_name}-alarm-notifications"
  display_name      = "CloudWatch Alarm Notifications"
  kms_master_key_id = aws_kms_key.alarm_notifications.key_id

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_subscription" "alarm_email" {
  topic_arn = aws_sns_topic.alarm_notifications.arn
  protocol  = "email"
  endpoint  = var.alarm_notification_email
}

resource "aws_cloudwatch_metric_alarm" "sqs_oldest_message_age" {
  alarm_name          = "${var.project_name}-sqs-oldest-message-age"
  alarm_description   = "Alarms when the age of the oldest message in the main SQS queue exceeds one hour, indicating consumers are falling behind."
  namespace           = "AWS/SQS"
  metric_name         = "ApproximateAgeOfOldestMessage"
  statistic           = "Maximum"
  period              = 300
  evaluation_periods  = 2
  threshold           = 3600
  comparison_operator = "GreaterThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    QueueName = aws_sqs_queue.main.name
  }

  alarm_actions = [aws_sns_topic.alarm_notifications.arn]
  ok_actions    = [aws_sns_topic.alarm_notifications.arn]

  tags = local.tags
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.alarm_notifications.arn]

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_cloudwatch_metric_alarm.sqs_oldest_message_age.arn]
    }
  }
}

resource "aws_sns_topic_policy" "alarm_notifications" {
  arn    = aws_sns_topic.alarm_notifications.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40.0, < 6.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to the Environment tag on all taggable resources."
  type        = string
  default     = "dev"
}

locals {
  environment = var.environment
  managed_by  = "terraform"
  stream_name = "orders-stream"
}

resource "aws_dynamodb_table" "orders" {
  name         = "orders"
  hash_key     = "pk"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "pk"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = {
    Name        = "orders"
    Environment = local.environment
    ManagedBy   = local.managed_by
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "orders_stream" {
  description             = "Customer managed KMS key used to encrypt the orders Kinesis data stream."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name        = "${local.stream_name}-key"
    Environment = local.environment
    ManagedBy   = local.managed_by
  }
}

resource "aws_kinesis_stream" "orders_stream" {
  name             = local.stream_name
  retention_period = 24

  stream_mode_details {
    stream_mode = "ON_DEMAND"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.orders_stream.arn

  tags = {
    Name        = local.stream_name
    Environment = local.environment
    ManagedBy   = local.managed_by
  }
}

# The hashicorp/aws provider does not implement an
# aws_kinesis_streaming_destination resource type at any released version,
# so the DynamoDB -> Kinesis streaming destination is enabled by invoking
# the EnableKinesisStreamingDestination API directly (aws dynamodb
# enable-kinesis-streaming-destination) from a terraform_data local-exec
# provisioner. The triggers_replace list makes this step run only after both
# the table and the stream exist (implicit dependency, destination last) and
# re-run idempotently if either ARN ever changes. The command contains no
# credentials, tokens, or account IDs; it relies on the applying principal's
# normal credential chain, which must be allowed
# dynamodb:EnableKinesisStreamingDestination on the table. AWS creates the
# AWSServiceRoleForDynamoDBKinesis service-linked role automatically when
# the call succeeds, so no template-side IAM is required for the write path.
# Destination deletion protection is covered by the table's
# deletion_protection_enabled plus lifecycle { prevent_destroy }.
resource "terraform_data" "orders_streaming_destination" {
  triggers_replace = [
    aws_dynamodb_table.orders.arn,
    aws_kinesis_stream.orders_stream.arn,
  ]

  provisioner "local-exec" {
    command = "aws dynamodb enable-kinesis-streaming-destination --table-name ${aws_dynamodb_table.orders.name} --stream-arn ${aws_kinesis_stream.orders_stream.arn} --region us-east-1"
  }
}

output "kinesis_stream_arn" {
  description = "ARN of the Kinesis data stream receiving DynamoDB table changes."
  value       = aws_kinesis_stream.orders_stream.arn
}

output "kinesis_stream_name" {
  description = "Name of the Kinesis data stream."
  value       = aws_kinesis_stream.orders_stream.name
}

output "dynamodb_table_arn" {
  description = "ARN of the source DynamoDB table."
  value       = aws_dynamodb_table.orders.arn
}

output "dynamodb_table_name" {
  description = "Name of the source DynamoDB table."
  value       = aws_dynamodb_table.orders.name
}

output "streaming_destination_enable_task_id" {
  description = "Identity of the terraform_data resource that executes the enable-kinesis-streaming-destination call; its presence confirms the enable step ran. Post-apply destination status can be confirmed from the pipeline via dynamodb describe-kinesis-streaming-destination."
  value       = terraform_data.orders_streaming_destination.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (all have defaults so `terraform apply` runs unattended)
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "cluster_name" {
  description = "Name of the DAX cluster."
  type        = string
  default     = "dax-cache-cluster"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking (greenfield: everything created in this configuration)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# DynamoDB Gateway endpoint so DAX nodes in private subnets can reach
# DynamoDB without an internet gateway or NAT gateway. Its managed prefix
# list is reused to scope security group egress to DynamoDB traffic only.
resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["dynamodb:*"]
        Resource = ["*"]
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dynamodb-gateway-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Security group: DAX client traffic on port 8111 from the VPC CIDR only
# ---------------------------------------------------------------------------

resource "aws_security_group" "dax" {
  name        = "${var.environment}-dax-sg"
  description = "Allow inbound DAX client traffic on port 8111 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "DAX endpoint port (8111) from the VPC CIDR only"
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS to DynamoDB through the DynamoDB gateway endpoint prefix list"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.dynamodb.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-sg"
  })
}

# ---------------------------------------------------------------------------
# IAM: role trusted only by the DAX service, with least-privilege DynamoDB access
# ---------------------------------------------------------------------------

resource "aws_iam_role" "dax" {
  name = "${var.environment}-dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-role"
  })
}

resource "aws_iam_role_policy" "dax_dynamodb_access" {
  name = "${var.environment}-dax-dynamodb-access"
  role = aws_iam_role.dax.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:BatchGetItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:PutItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:ConditionCheckItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [
          "arn:aws:dynamodb:*:*:table/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# DAX subnet group and cluster
# Note: aws_dax_subnet_group does not support tagging in the provider schema,
# so environment traceability is embedded in its name and description.
# ---------------------------------------------------------------------------

resource "aws_dax_subnet_group" "dax" {
  name        = "${var.environment}-dax-subnet-group"
  description = "Private subnets for the ${var.environment} DAX cluster"
  subnet_ids  = aws_subnet.private[*].id
}

resource "aws_dax_cluster" "main" {
  cluster_name       = var.cluster_name
  node_type          = "dax.r4.large"
  replication_factor = 1
  iam_role_arn       = aws_iam_role.dax.arn
  subnet_group_name  = aws_dax_subnet_group.dax.name
  security_group_ids = [aws_security_group.dax.id]

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = var.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy.dax_dynamodb_access,
    aws_vpc_endpoint.dynamodb
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.tags
  }
}

#------------------------------------------------------------------------------
# User-controlled inputs (all with defaults so terraform apply is non-interactive)
#------------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "domain_name_prefix" {
  description = "Prefix used when composing the SageMaker domain name."
  type        = string
  default     = "ml"
}

variable "owner" {
  description = "Value recorded in the Owner tag on every resource."
  type        = string
  default     = "platform-team"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated SageMaker VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "default_ebs_volume_size_gb" {
  description = "Default EBS volume size (GB) for SageMaker user spaces."
  type        = number
  default     = 10

  validation {
    condition     = var.default_ebs_volume_size_gb >= 1 && var.default_ebs_volume_size_gb <= 16384
    error_message = "Default EBS volume size must be between 1 and 16384 GB."
  }
}

variable "max_ebs_volume_size_gb" {
  description = "Maximum EBS volume size (GB) a user may resize their space volume to. Must be strictly greater than the default size."
  type        = number
  default     = 30

  validation {
    condition     = var.max_ebs_volume_size_gb > var.default_ebs_volume_size_gb
    error_message = "Maximum EBS volume size must be strictly greater than the default EBS volume size."
  }
}

variable "tags" {
  description = "Additional tags merged into the shared tag map."
  type        = map(string)
  default     = {}
}

#------------------------------------------------------------------------------
# Shared locals and consistent tagging
#------------------------------------------------------------------------------

locals {
  name_prefix = "${var.domain_name_prefix}-${var.environment}"
  domain_name = "${local.name_prefix}-domain"

  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }

  tags = merge(local.common_tags, var.tags)
}

#------------------------------------------------------------------------------
# Static provider metadata lookups (well-known, no dependency on remote state)
#------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Dedicated networking for VpcOnly operation
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-${count.index + 1}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "sagemaker_domain" {
  name        = "${local.name_prefix}-sagemaker-domain-sg"
  description = "SageMaker domain VpcOnly traffic: only intra-domain (self-referencing) ingress."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Intra-domain traffic between SageMaker apps, the home EFS mount targets and VPC endpoints"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Outbound to SageMaker services, the home EFS and VPC endpoints"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-domain-sg" })
}

#------------------------------------------------------------------------------
# VPC endpoints required for VpcOnly operation
#------------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.tags, { Name = "${local.name_prefix}-s3-gateway-endpoint" })
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset([
    "sagemaker.api",
    "sagemaker.runtime",
    "sts",
    "logs",
  ])

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.sagemaker_domain.id]
  private_dns_enabled = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-${each.value}-endpoint" })
}

#------------------------------------------------------------------------------
# Customer managed KMS key for domain home-directory EFS and EBS encryption
#------------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_kms_key" {
  statement {
    sid    = "EnableAccountIAMPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:Create*",
      "kms:Decrypt",
      "kms:Delete*",
      "kms:Describe*",
      "kms:Disable*",
      "kms:Enable*",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:Get*",
      "kms:List*",
      "kms:Put*",
      "kms:ReEncrypt*",
      "kms:RetireGrant",
      "kms:Revoke*",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:Update*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSageMakerServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }

    actions = [
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sagemaker.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowAccountPrincipalsViaElasticFileSystem"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "sagemaker" {
  description             = "Customer managed key used to encrypt SageMaker domain home-directory EFS and EBS storage."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sagemaker_kms_key.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# S3 artifact bucket (scoping target for the execution role's S3 permissions)
#------------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_artifacts" {
  bucket = "${local.name_prefix}-sagemaker-artifacts-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sagemaker.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

#------------------------------------------------------------------------------
# Default execution role for the SageMaker domain
#------------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    sid    = "AllowSageMakerServiceToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sagemaker_execution" {
  name               = "${local.name_prefix}-sagemaker-execution"
  description        = "Default execution role for the SageMaker domain."
  assume_role_policy = data.aws_iam_policy_document.sagemaker_assume_role.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-execution" })
}

data "aws_iam_policy_document" "sagemaker_api_access" {
  statement {
    sid    = "SageMakerApiAccess"
    effect = "Allow"

    actions = [
      "sagemaker:CreateApp",
      "sagemaker:CreatePresignedDomainUrl",
      "sagemaker:DeleteApp",
      "sagemaker:DescribeApp",
      "sagemaker:DescribeAppImageConfig",
      "sagemaker:DescribeDomain",
      "sagemaker:DescribeImage",
      "sagemaker:DescribeImageVersion",
      "sagemaker:DescribeSpace",
      "sagemaker:DescribeStudioLifecycleConfig",
      "sagemaker:DescribeUserProfile",
      "sagemaker:ListApps",
      "sagemaker:ListAppImageConfigs",
      "sagemaker:ListDomains",
      "sagemaker:ListImages",
      "sagemaker:ListImageVersions",
      "sagemaker:ListSpaces",
      "sagemaker:ListStudioLifecycleConfigs",
      "sagemaker:ListUserProfiles",
      "sagemaker:Search",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "sagemaker_cloudwatch_logs" {
  statement {
    sid    = "SageMakerCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*",
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*:log-stream:*",
    ]
  }
}

data "aws_iam_policy_document" "sagemaker_s3_access" {
  statement {
    sid    = "SageMakerArtifactsBucketList"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.sagemaker_artifacts.arn]
  }

  statement {
    sid    = "SageMakerArtifactsBucketObjects"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:ListMultipartUploadParts",
      "s3:PutObject",
    ]

    resources = ["${aws_s3_bucket.sagemaker_artifacts.arn}/*"]
  }
}

data "aws_iam_policy_document" "sagemaker_kms_access" {
  statement {
    sid    = "SageMakerKeyUsage"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.sagemaker.arn]
  }
}

resource "aws_iam_policy" "sagemaker_api_access" {
  name        = "${local.name_prefix}-sagemaker-api-access"
  description = "Least-privilege SageMaker API access for the SageMaker domain execution role."
  policy      = data.aws_iam_policy_document.sagemaker_api_access.json

  tags = local.tags
}

resource "aws_iam_policy" "sagemaker_cloudwatch_logs" {
  name        = "${local.name_prefix}-sagemaker-cloudwatch-logs"
  description = "CloudWatch Logs permissions required by the SageMaker domain execution role."
  policy      = data.aws_iam_policy_document.sagemaker_cloudwatch_logs.json

  tags = local.tags
}

resource "aws_iam_policy" "sagemaker_s3_access" {
  name        = "${local.name_prefix}-sagemaker-s3-access"
  description = "S3 access scoped to the SageMaker artifacts bucket for the domain execution role."
  policy      = data.aws_iam_policy_document.sagemaker_s3_access.json

  tags = local.tags
}

resource "aws_iam_policy" "sagemaker_kms_access" {
  name        = "${local.name_prefix}-sagemaker-kms-access"
  description = "KMS decrypt/data-key permissions scoped to the SageMaker domain key."
  policy      = data.aws_iam_policy_document.sagemaker_kms_access.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_api_access" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_api_access.arn
}

resource "aws_iam_role_policy_attachment" "sagemaker_cloudwatch_logs" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_cloudwatch_logs.arn
}

resource "aws_iam_role_policy_attachment" "sagemaker_s3_access" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_s3_access.arn
}

resource "aws_iam_role_policy_attachment" "sagemaker_kms_access" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_kms_access.arn
}

#------------------------------------------------------------------------------
# SageMaker domain
#------------------------------------------------------------------------------

resource "aws_sagemaker_domain" "sagemaker_domain" {
  domain_name                   = local.domain_name
  auth_mode                     = "IAM"
  app_network_access_type       = "VpcOnly"
  app_security_group_management = "Customer"
  vpc_id                        = aws_vpc.main.id
  subnet_ids                    = aws_subnet.private[*].id
  kms_key_id                    = aws_kms_key.sagemaker.arn

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker_domain.id]

    space_storage_settings {
      default_ebs_storage_settings {
        default_ebs_volume_size_in_gb = var.default_ebs_volume_size_gb
        maximum_ebs_volume_size_in_gb = var.max_ebs_volume_size_gb
      }
    }

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }
  }

  retention_policy {
    home_efs_file_system = "Retain"
  }

  tags = merge(local.tags, { Name = local.domain_name })

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Outputs for downstream consumption
#------------------------------------------------------------------------------

output "sagemaker_domain_id" {
  description = "ID of the SageMaker domain."
  value       = aws_sagemaker_domain.sagemaker_domain.id
}

output "sagemaker_domain_arn" {
  description = "ARN of the SageMaker domain."
  value       = aws_sagemaker_domain.sagemaker_domain.arn
}

output "sagemaker_domain_security_group_id" {
  description = "ID of the security group attached to the SageMaker domain."
  value       = aws_security_group.sagemaker_domain.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags to apply to the SageMaker code repository. Defaults are safe so terraform apply runs non-interactively."
  type        = map(string)
  default = {
    Name        = "terraform-provider-aws"
    Environment = "production"
  }
}

resource "aws_sagemaker_code_repository" "this" {
  code_repository_name = "terraform-provider-aws"

  git_config {
    # Public repository: no secret_arn or Git credentials configured.
    repository_url = "https://github.com/hashicorp/terraform-provider-aws.git"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "code_repository_name" {
  description = "Name of the SageMaker code repository."
  value       = aws_sagemaker_code_repository.this.code_repository_name
}

output "code_repository_arn" {
  description = "ARN of the SageMaker code repository."
  value       = aws_sagemaker_code_repository.this.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "instance_type" {
  description = "EC2 instance type for the SageMaker notebook instance."
  type        = string
  default     = "ml.t3.medium"
}

variable "volume_size" {
  description = "Size in GB of the EBS root volume attached to the notebook instance."
  type        = number
  default     = 50

  validation {
    condition     = var.volume_size >= 20 && var.volume_size <= 16384
    error_message = "Notebook volume size must be between 20 and 16384 GB."
  }
}

variable "tags" {
  description = "Consistent tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
    Owner       = "platform-team"
    Project     = "sagemaker-terraform-provider-aws"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Networking: VPC, subnets, routing, NAT, and S3 gateway endpoint
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "sagemaker-notebook-vpc" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.tags, { Name = "sagemaker-public-${count.index + 1}" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "sagemaker-private-${count.index + 1}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "sagemaker-internet-gateway" })
}

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = merge(var.tags, { Name = "sagemaker-nat-eip-${count.index + 1}" })
}

resource "aws_nat_gateway" "main" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, { Name = "sagemaker-nat-gateway-${count.index + 1}" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "sagemaker-public-route-table" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "sagemaker-private-route-table-${count.index + 1}" })
}

resource "aws_route" "private_nat" {
  count                  = 2
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(var.tags, { Name = "sagemaker-s3-gateway-endpoint" })
}

# -----------------------------------------------------------------------------
# Security group: self-referencing 443/8443 ingress only, HTTPS-only egress
# -----------------------------------------------------------------------------

resource "aws_security_group" "sagemaker_notebook" {
  name        = "sagemaker-notebook-sg"
  description = "SageMaker notebook instance security group: self-referencing TCP 443/8443 ingress, TCP 443-only egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS from within the security group (required for in-VPC SageMaker service calls)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  ingress {
    description = "Port 8443 from within the security group (required for in-VPC SageMaker service calls)"
    from_port   = 8443
    to_port     = 8443
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "HTTPS egress only (enables git clone of the default code repository via NAT)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "sagemaker-notebook-sg" })
}

# -----------------------------------------------------------------------------
# KMS: customer-managed key for notebook volume and S3 artifacts
# -----------------------------------------------------------------------------

resource "aws_kms_key" "notebook" {
  description              = "Encrypts the SageMaker notebook instance root volume and S3 notebook artifacts"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation      = true
  deletion_window_in_days  = 30

  tags = merge(var.tags, { Name = "sagemaker-notebook-kms-key" })
}

resource "aws_kms_alias" "notebook" {
  name          = "alias/sagemaker-notebook-key"
  target_key_id = aws_kms_key.notebook.key_id
}

# -----------------------------------------------------------------------------
# IAM: least-privilege notebook execution role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_execution" {
  name = "sagemaker-notebook-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "sagemaker.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "sagemaker_notebook_artifacts" {
  name = "sagemaker-notebook-artifacts-access"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListNotebookArtifactsBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.notebook_artifacts.arn
      },
      {
        Sid      = "ReadWriteNotebookArtifactsObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = "${aws_s3_bucket.notebook_artifacts.arn}/*"
      },
      {
        Sid      = "NotebookVolumeAndArtifactKmsUsage"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.notebook.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# S3: dedicated, private, versioned, SSE-KMS encrypted artifacts bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "notebook_artifacts" {
  bucket = "sagemaker-notebook-artifacts-${data.aws_caller_identity.current.account_id}"

  tags = merge(var.tags, { Name = "sagemaker-notebook-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.notebook.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# SageMaker: code repository and VPC-isolated notebook instance
# -----------------------------------------------------------------------------

resource "aws_sagemaker_code_repository" "terraform_provider_aws" {
  code_repository_name = "terraform-provider-aws"

  git_config {
    repository_url = "https://github.com/hashicorp/terraform-provider-aws.git"
  }

  tags = var.tags
}

resource "aws_sagemaker_notebook_instance" "terraform_provider_aws" {
  name                    = "terraform-provider-aws-notebook"
  role_arn                = aws_iam_role.sagemaker_execution.arn
  instance_type           = var.instance_type
  volume_size             = var.volume_size
  subnet_id               = aws_subnet.private[0].id
  security_groups         = toset([aws_security_group.sagemaker_notebook.id])
  kms_key_id              = aws_kms_key.notebook.arn
  direct_internet_access  = "Disabled"
  default_code_repository = aws_sagemaker_code_repository.terraform_provider_aws.arn

  tags = merge(var.tags, { Name = "terraform-provider-aws-notebook" })

  depends_on = [
    aws_iam_role_policy.sagemaker_notebook_artifacts,
    aws_nat_gateway.main,
    aws_vpc_endpoint.s3_gateway,
    aws_route_table_association.private,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "notebook_instance_name" {
  description = "Name of the SageMaker notebook instance."
  value       = aws_sagemaker_notebook_instance.terraform_provider_aws.name
}

output "notebook_instance_arn" {
  description = "ARN of the SageMaker notebook instance."
  value       = aws_sagemaker_notebook_instance.terraform_provider_aws.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used to derive resource names."
  type        = string
  default     = "demo"
}

variable "image_tag" {
  description = "Container image tag within the inference ECR repository."
  type        = string
  default     = "latest"
}

variable "tags" {
  description = "Default tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  endpoint_name  = "sagemaker-${var.project_name}-endpoint"
  model_data_url = "s3://${aws_s3_bucket.model_artifacts.bucket}/${aws_s3_object.model_artifact.key}"
  common_tags    = merge(var.tags, { Project = var.project_name })
}

# -----------------------------------------------------------------------------
# KMS: encryption for model artifacts and endpoint storage volumes
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sagemaker" {
  description             = "KMS key for SageMaker model artifacts and endpoint storage volumes"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/sagemaker-${var.project_name}"
  target_key_id = aws_kms_key.sagemaker.key_id
}

# -----------------------------------------------------------------------------
# S3: model artifact bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "model_artifacts" {
  bucket = "sagemaker-model-artifacts-${var.project_name}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.model_artifacts.arn,
          "${aws_s3_bucket.model_artifacts.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_object" "model_artifact" {
  bucket                 = aws_s3_bucket.model_artifacts.bucket
  key                    = "models/model.tar.gz"
  content                = "placeholder model artifact"
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.sagemaker.arn

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# ECR: private inference container repository
# -----------------------------------------------------------------------------
resource "aws_ecr_repository" "inference" {
  name                 = "sagemaker-inference-${var.project_name}"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# IAM: SageMaker execution role with least-privilege inline policies
# -----------------------------------------------------------------------------
resource "aws_iam_role" "sagemaker_exec" {
  name = "sagemaker-exec-${var.project_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSageMakerAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "s3_model_artifacts" {
  name = "s3-model-artifacts-access"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListModelArtifactBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.model_artifacts.arn]
      },
      {
        Sid      = "GetModelArtifacts"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.model_artifacts.arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_logs" {
  name = "sagemaker-endpoint-logs"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerEndpointLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.endpoint.arn,
          "${aws_cloudwatch_log_group.endpoint.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecr_pull" {
  name = "ecr-inference-pull"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PullInferenceImage"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = [aws_ecr_repository.inference.arn]
      },
      {
        Sid      = "GetEcrAuthorizationToken"
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken"]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "kms_decrypt" {
  name = "kms-model-artifact-decrypt"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptModelArtifacts"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.sagemaker.arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch: endpoint inference log group
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "endpoint" {
  name              = "/aws/sagemaker/Endpoints/${local.endpoint_name}"
  retention_in_days = 30

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# SageMaker: model, endpoint configuration, and endpoint
# -----------------------------------------------------------------------------
resource "aws_sagemaker_model" "model" {
  name                     = "sagemaker-${var.project_name}-model"
  execution_role_arn       = aws_iam_role.sagemaker_exec.arn
  enable_network_isolation = true

  primary_container {
    image          = "${aws_ecr_repository.inference.repository_url}:${var.image_tag}"
    model_data_url = local.model_data_url
  }

  tags = local.common_tags
}

resource "aws_sagemaker_endpoint_configuration" "config" {
  name = "${local.endpoint_name}-config"

  production_variants {
    variant_name           = "AllTraffic"
    model_name             = aws_sagemaker_model.model.name
    instance_type          = "ml.m5.large"
    initial_instance_count = 1
  }

  kms_key_arn = aws_kms_key.sagemaker.arn

  tags = local.common_tags
}

resource "aws_sagemaker_endpoint" "endpoint" {
  name                 = local.endpoint_name
  endpoint_config_name = aws_sagemaker_endpoint_configuration.config.name

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "endpoint_name" {
  description = "Name of the SageMaker real-time inference endpoint."
  value       = aws_sagemaker_endpoint.endpoint.name
}

output "endpoint_arn" {
  description = "ARN of the SageMaker real-time inference endpoint."
  value       = aws_sagemaker_endpoint.endpoint.arn
}

output "model_artifact_s3_uri" {
  description = "S3 URI of the SageMaker model artifacts."
  value       = local.model_data_url
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used to prefix resource names and tags."
  type        = string
  default     = "terraform-demo"
}

variable "environment" {
  description = "Environment name applied to the Environment tag on all resources."
  type        = string
  default     = "dev"
}

variable "admin_ssh_cidr" {
  description = "CIDR block permitted to reach SSH (port 22) on the instances."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = can(cidrnetmask(var.admin_ssh_cidr))
    error_message = "admin_ssh_cidr must be a valid CIDR block (e.g. 10.0.0.0/8)."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-internet-gateway"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-subnet-${data.aws_availability_zones.available.names[0]}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-subnet-${data.aws_availability_zones.available.names[1]}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-route-table"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instance" {
  name        = "${var.project_name}-instance-sg"
  description = "Allow SSH from the admin CIDR and all outbound traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_ssh_cidr]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-sg"
  })
}

resource "aws_instance" "instance_a" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_a.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 8
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-${data.aws_availability_zones.available.names[0]}"
  })
}

resource "aws_instance" "instance_b" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_b.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 8
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-${data.aws_availability_zones.available.names[1]}"
  })
}

resource "aws_ebs_volume" "volume_a" {
  availability_zone = aws_instance.instance_a.availability_zone
  size              = 50
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-volume-${aws_instance.instance_a.availability_zone}"
  })
}

resource "aws_ebs_volume" "volume_b" {
  availability_zone = aws_instance.instance_b.availability_zone
  size              = 50
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-volume-${aws_instance.instance_b.availability_zone}"
  })
}

resource "aws_volume_attachment" "attachment_a" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.volume_a.id
  instance_id = aws_instance.instance_a.id
}

resource "aws_volume_attachment" "attachment_b" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.volume_b.id
  instance_id = aws_instance.instance_b.id
}

output "instance_a_id" {
  description = "Instance ID of instance A in the first availability zone."
  value       = aws_instance.instance_a.id
}

output "instance_a_public_ip" {
  description = "Public IP address of instance A."
  value       = aws_instance.instance_a.public_ip
}

output "instance_a_volume_id" {
  description = "ID of the 50 GB EBS data volume attached to instance A."
  value       = aws_ebs_volume.volume_a.id
}

output "instance_b_id" {
  description = "Instance ID of instance B in the second availability zone."
  value       = aws_instance.instance_b.id
}

output "instance_b_public_ip" {
  description = "Public IP address of instance B."
  value       = aws_instance.instance_b.public_ip
}

output "instance_b_volume_id" {
  description = "ID of the 50 GB EBS data volume attached to instance B."
  value       = aws_ebs_volume.volume_b.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "hpc_cluster"
}

variable "environment" {
  description = "Environment tag value applied to all resources."
  type        = string
  default     = "production"
}

variable "instance_type" {
  description = "Instance type for cluster nodes (must support cluster placement groups)."
  type        = string
  default     = "m5.large"
}

variable "admin_cidr" {
  description = "Restricted admin CIDR allowed to reach SSH on cluster nodes."
  type        = string
  default     = "203.0.113.0/24"
}

variable "ssh_public_key" {
  description = "OpenSSH public key material for the deployer key pair (public key only, never private key material)."
  type        = string
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGj0L3hG9R6vW8FqL1TqT3nK2mY5cB7dE9fH1jK3lN5 deployer@example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "base" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_subnet" "cluster" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cluster-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "cluster" {
  subnet_id      = aws_subnet.cluster.id
  route_table_id = aws_route_table.public.id
}

resource "aws_key_pair" "deployer" {
  key_name   = "${var.project_name}-deployer-key"
  public_key = var.ssh_public_key

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-deployer-key"
  })
}

resource "aws_security_group" "cluster" {
  name        = "${var.project_name}-cluster-sg"
  description = "Security group for cluster nodes: SSH from admin CIDR, internal cluster traffic within VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from restricted admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "Cluster internal node-to-node traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cluster-sg"
  })
}

resource "aws_placement_group" "cluster" {
  name     = "${var.project_name}-placement-group"
  strategy = "cluster"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-placement-group"
  })
}

resource "aws_instance" "cluster" {
  count = 3

  ami                    = data.aws_ami.base.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.cluster.id
  vpc_security_group_ids = [aws_security_group.cluster.id]
  key_name               = aws_key_pair.deployer.key_name
  placement_group        = aws_placement_group.cluster.name

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_tokens = "required"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cluster-node-${count.index + 1}"
  })
}

output "instance_ids" {
  description = "IDs of the three cluster instances."
  value       = aws_instance.cluster[*].id
}

output "instance_public_ips" {
  description = "Public IPs of the three cluster instances."
  value       = aws_instance.cluster[*].public_ip
}

output "placement_group_name" {
  description = "Name of the cluster placement group."
  value       = aws_placement_group.cluster.name
}

output "cluster_availability_zone" {
  description = "Availability zone hosting the cluster subnet and all three instances."
  value       = aws_subnet.cluster.availability_zone
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for consistent resource tagging."
  type        = string
  default     = "elasticache-redis-auth"
}

variable "environment" {
  description = "Environment name used for consistent resource tagging."
  type        = string
  default     = "dev"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  name_prefix = "app-redis"

  common_tags = {
    Project     = var.project
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Network foundation (internet/NAT free: subnets host only the cache tier)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_security_group" "cache" {
  name        = "${local.name_prefix}-cache-sg"
  description = "Permit Redis (TCP 6379) only from within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from within the VPC CIDR only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cache-sg" })
}

# -----------------------------------------------------------------------------
# Dynamic credential generation and secure storage
# -----------------------------------------------------------------------------

resource "random_password" "cache_user_password" {
  length           = 24
  special          = true
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "cache_user_credentials" {
  name                    = "elasticache/${local.name_prefix}-auth-user"
  description             = "Credentials for the ElastiCache Redis ACL user"
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-auth-user-secret" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "cache_user_credentials" {
  secret_id = aws_secretsmanager_secret.cache_user_credentials.id
  secret_string = jsonencode({
    username = aws_elasticache_user.app_auth_user.user_name
    password = random_password.cache_user_password.result
  })
}

# -----------------------------------------------------------------------------
# ElastiCache ACL user with password-based authentication
# -----------------------------------------------------------------------------

resource "aws_elasticache_user" "app_auth_user" {
  user_id       = "app_auth_user"
  user_name     = "app_auth_user"
  engine        = "REDIS"
  access_string = "on ~app:* +@read +@write -@dangerous"
  passwords     = [random_password.cache_user_password.result]
}

resource "aws_elasticache_user_group" "app_user_group" {
  user_group_id = "app_user_group"
  engine        = "redis"
  user_ids      = [aws_elasticache_user.app_auth_user.user_id]
}

# -----------------------------------------------------------------------------
# Cache tier building blocks
# -----------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "cache" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets for the Redis cache tier"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-group" })
}

resource "aws_elasticache_parameter_group" "redis7" {
  name        = "${local.name_prefix}-redis7-params"
  family      = "redis7"
  description = "Redis 7 parameter group supporting ACL user-group authentication"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redis7-params" })
}

# -----------------------------------------------------------------------------
# Replication group enforcing password (ACL) authentication on all connections
# -----------------------------------------------------------------------------

resource "aws_elasticache_replication_group" "main" {
  replication_group_id = "${local.name_prefix}-rg"
  description          = "Redis 7 replication group with ACL password authentication"
  engine               = "redis"
  engine_version       = "7.1"
  node_type            = "cache.t3.small"
  num_cache_clusters   = 2

  automatic_failover_enabled = true
  multi_az_enabled           = true

  parameter_group_name = aws_elasticache_parameter_group.redis7.name
  subnet_group_name    = aws_elasticache_subnet_group.cache.name
  security_group_ids   = [aws_security_group.cache.id]
  user_group_ids       = [aws_elasticache_user_group.app_user_group.user_group_id]

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true

  snapshot_retention_limit = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rg" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs (never expose the password value itself)
# -----------------------------------------------------------------------------

output "redis_primary_endpoint" {
  description = "Primary endpoint address of the Redis replication group."
  value       = aws_elasticache_replication_group.main.primary_endpoint_address
}

output "redis_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the ElastiCache username and password."
  value       = aws_secretsmanager_secret.cache_user_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (standard tagging — non-empty defaults, no secrets, no resource attrs)
# ---------------------------------------------------------------------------

variable "project" {
  description = "Project identifier used in resource names and tags."
  type        = string
  default     = "kafka-platform"
}

variable "environment" {
  description = "Environment identifier used in resource tags."
  type        = string
  default     = "dev"
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata lookups only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  msk_cluster_name = "${var.project}-msk-cluster"

  msk_topic_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:topic/${local.msk_cluster_name}/*"

  msk_group_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:group/${local.msk_cluster_name}/*"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking: dedicated VPC and one subnet per broker across distinct AZs
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-vpc"
  })
}

resource "aws_subnet" "msk" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-subnet-${count.index + 1}"
    AZ   = data.aws_availability_zones.available.names[count.index]
  })
}

# ---------------------------------------------------------------------------
# Security group: Kafka TLS (9094) and SASL/IAM (9096) listeners, VPC-internal only
# ---------------------------------------------------------------------------

resource "aws_security_group" "msk_brokers" {
  name        = "${var.project}-msk-brokers-sg"
  description = "MSK brokers - ingress restricted to Kafka TLS (9094) and SASL/IAM (9096) listeners from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka TLS listener (9094) from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka SASL/IAM listener (9096) from within the VPC"
    from_port   = 9096
    to_port     = 9096
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-brokers-sg"
  })
}

# ---------------------------------------------------------------------------
# KMS key for encryption at rest
# ---------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer managed KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${var.project}-msk"
  target_key_id = aws_kms_key.msk.key_id
}

# ---------------------------------------------------------------------------
# CloudWatch log group for broker logs
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${var.project}-cluster/broker-logs"
  retention_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-broker-logs"
  })
}

# ---------------------------------------------------------------------------
# MSK cluster: 3 brokers, TLS-only client-broker encryption, IAM + TLS auth
# ---------------------------------------------------------------------------

resource "aws_msk_cluster" "main" {
  cluster_name           = local.msk_cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }

    # TLS client authentication is enabled by the presence of this block
    # itself in provider ~> 5.0 (no `enabled` argument exists).
    tls {}
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  enhanced_monitoring = "PER_BROKER"

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = local.msk_cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM: least-privilege role and policy for IAM access control to the cluster
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_client_assume_role" {
  statement {
    sid     = "AllowKafkaClientsToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_client" {
  name               = "${var.project}-msk-client-role"
  description        = "Role assumed by Kafka clients for IAM access control to the MSK cluster"
  assume_role_policy = data.aws_iam_policy_document.msk_client_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-client-role"
  })
}

data "aws_iam_policy_document" "msk_access" {
  statement {
    sid       = "MSKClusterAccess"
    effect    = "Allow"
    actions   = ["kafka-cluster:*"]
    resources = [aws_msk_cluster.main.arn]
  }

  statement {
    sid       = "MSKTopicAccess"
    effect    = "Allow"
    actions   = ["kafka-cluster:*"]
    resources = [local.msk_topic_arn_pattern]
  }

  statement {
    sid       = "MSKConsumerGroupAccess"
    effect    = "Allow"
    actions   = ["kafka-cluster:*"]
    resources = [local.msk_group_arn_pattern]
  }

  statement {
    sid       = "MSKGetBootstrapBrokers"
    effect    = "Allow"
    actions   = ["kafka:GetBootstrapBrokers"]
    resources = [aws_msk_cluster.main.arn]
  }
}

resource "aws_iam_policy" "msk_access" {
  name        = "${var.project}-msk-access-policy"
  description = "Least-privilege Kafka access scoped to the MSK cluster, its topics, and its consumer groups"
  policy      = data.aws_iam_policy_document.msk_access.json

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-access-policy"
  })
}

resource "aws_iam_role_policy_attachment" "msk_access" {
  role       = aws_iam_role.msk_client.name
  policy_arn = aws_iam_policy.msk_access.arn
}

# ---------------------------------------------------------------------------
# Outputs: cluster connection information
# ---------------------------------------------------------------------------

output "bootstrap_brokers_tls" {
  description = "Comma-separated list of broker endpoints for TLS connections (port 9094)."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of broker endpoints for SASL/IAM connections (port 9096)."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "zookeeper_connect_string_tls" {
  description = "TLS-secured ZooKeeper connection string for the MSK cluster."
  value       = aws_msk_cluster.main.zookeeper_connect_string_tls
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources"
  type        = string
  default     = "production"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC"
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  name_prefix = "msk-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "msk-broker-logging"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_security_group" "msk" {
  name        = "${local.name_prefix}-brokers"
  description = "Inbound Kafka broker and ZooKeeper ports restricted to the MSK VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client plaintext (9092) from within the VPC"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka client TLS (9094) from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "ZooKeeper (2181) from within the VPC"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers"
  })
}

# -----------------------------------------------------------------------------
# S3 log destination
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_logs" {
  bucket = "${local.name_prefix}-broker-logs-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# -----------------------------------------------------------------------------
# Encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK cluster encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-encryption"
  })
}

# -----------------------------------------------------------------------------
# MSK cluster
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "logs/"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster"
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker string for connecting clients"
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_count" {
  description = "Number of private subnets (one per AZ) spanning the MSK Serverless cluster."
  type        = number
  default     = 3

  validation {
    condition     = var.subnet_count >= 2
    error_message = "MSK Serverless requires at least two subnets in distinct Availability Zones."
  }
}

variable "cluster_name" {
  description = "Name of the MSK Serverless cluster."
  type        = string
  default     = "msk-serverless-cluster"

  validation {
    condition     = can(regex("^[a-zA-Z0-9-]+$", var.cluster_name))
    error_message = "MSK cluster names may only contain alphanumeric characters and hyphens."
  }
}

variable "project" {
  description = "Project tag applied to all taggable resources."
  type        = string
  default     = "serverless-msk"
}

variable "environment" {
  description = "Environment tag applied to all taggable resources."
  type        = string
  default     = "production"
}

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  cluster_arn      = aws_msk_serverless_cluster.main.arn
  topic_arn_prefix = "${replace(local.cluster_arn, "cluster/${var.cluster_name}", "topic/${var.cluster_name}")}/*"
  group_arn_prefix = "${replace(local.cluster_arn, "cluster/${var.cluster_name}", "group/${var.cluster_name}")}/*"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-vpc"
    },
  )
}

resource "aws_subnet" "private" {
  count = var.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-private-${format("%02d", count.index + 1)}"
    },
  )
}

resource "aws_security_group" "kafka_clients" {
  name        = "${var.project}-kafka-clients"
  description = "Kafka client access to the MSK Serverless cluster over IAM-authenticated SASL/TLS (TCP 9098)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "IAM-authenticated SASL/TLS traffic from within the VPC only"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Egress restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-kafka-clients"
    },
  )
}

resource "aws_msk_serverless_cluster" "main" {
  cluster_name = var.cluster_name

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.kafka_clients.id]
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.cluster_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kafka_client" {
  name        = "${var.project}-kafka-client-role"
  description = "IAM role assumed by Kafka client workloads (EC2) connecting to the MSK Serverless cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_instance_profile" "kafka_client" {
  name = "${var.project}-kafka-client-profile"
  role = aws_iam_role.kafka_client.name

  tags = local.common_tags
}

resource "aws_iam_policy" "kafka_client" {
  name        = "${var.project}-kafka-client-policy"
  description = "Least-privilege Kafka client access to the MSK Serverless cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConnectToCluster"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
        ]
        Resource = [
          aws_msk_serverless_cluster.main.arn,
        ]
      },
      {
        Sid    = "TopicDataAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:CreateTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:WriteData",
          "kafka-cluster:ReadData",
        ]
        Resource = [
          local.topic_arn_prefix,
        ]
      },
      {
        Sid    = "ConsumerGroupAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:DescribeGroup",
        ]
        Resource = [
          local.group_arn_prefix,
        ]
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "kafka_client" {
  role       = aws_iam_role.kafka_client.name
  policy_arn = aws_iam_policy.kafka_client.arn
}

output "cluster_arn" {
  description = "ARN of the MSK Serverless cluster."
  value       = aws_msk_serverless_cluster.main.arn
}

output "bootstrap_servers_string" {
  description = "Comma-separated bootstrap broker endpoints (hostname:port) for IAM/SASL (TLS) access to the MSK Serverless cluster on port 9098."
  value       = aws_msk_serverless_cluster.main.bootstrap_brokers_sasl_iam
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = local.aws_region
}

# -----------------------------------------------------------------------------
# User-controlled metadata
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Optional user-defined tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Static / well-known lookups only (no pre-existing infrastructure is discovered)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Naming and tagging
# -----------------------------------------------------------------------------

resource "random_id" "log_bucket_suffix" {
  byte_length = 4
}

locals {
  # Static deployment parameter, declared once and shared by the provider
  # block and all policy ARN construction. The deployment targets us-east-1
  # per the grounded objectives; no region data source is required.
  aws_region = "us-east-1"

  name_prefix          = "kafka-broker-logs"
  environment          = "production"
  cluster_name         = "${local.name_prefix}-cluster"
  log_group_name       = "/aws/msk/${local.name_prefix}"
  bucket_name          = "${local.name_prefix}-${random_id.log_bucket_suffix.hex}"
  firehose_stream_name = "amazon-msk-${local.name_prefix}"
  s3_log_prefix        = "broker-logs"

  common_tags = merge(var.tags, {
    Name        = local.name_prefix
    Environment = local.environment
    ManagedBy   = "terraform"
  })
}

# -----------------------------------------------------------------------------
# Networking foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-1"
  })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-2"
  })
}

resource "aws_subnet" "public_3" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-3"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "public_3" {
  subnet_id      = aws_subnet.public_3.id
  route_table_id = aws_route_table.main.id
}

# -----------------------------------------------------------------------------
# MSK broker security group (VPC-only ingress, all egress allowed)
# -----------------------------------------------------------------------------

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "Kafka broker and ZooKeeper access restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "ZooKeeper (2181) from within the VPC"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka broker listener (9092) from within the VPC"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka TLS listener (9094) from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka SASL/IAM listener (9096) from within the VPC"
    from_port   = 9096
    to_port     = 9096
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

# -----------------------------------------------------------------------------
# KMS key: MSK encryption at rest + CloudWatch Logs encryption
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_kms_key" {
  statement {
    sid    = "EnableIAMPermissionsForAccountRoot"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAmazonMSKEncryptionAtRest"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["msk.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsBrokerLogEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.aws_region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values = [
        "arn:${data.aws_partition.current.partition}:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}",
        "arn:${data.aws_partition.current.partition}:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}:*",
      ]
    }
  }
}

resource "aws_kms_key" "msk" {
  description             = "MSK encryption at rest and broker log encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.msk_kms_key.json

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# CloudWatch Logs destination
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = local.log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.msk.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

# -----------------------------------------------------------------------------
# S3 destination bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_broker_logs" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.msk.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.msk_broker_logs.arn,
          "${aws_s3_bucket.msk_broker_logs.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.msk_broker_logs]
}

# -----------------------------------------------------------------------------
# IAM: MSK -> CloudWatch Logs
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_cloudwatch_logs_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_cloudwatch_logs" {
  name               = "${local.name_prefix}-cw-logs-role"
  description        = "Allows Amazon MSK to export broker logs to CloudWatch Logs"
  assume_role_policy = data.aws_iam_policy_document.msk_cloudwatch_logs_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "msk_cloudwatch_logs_write" {
  statement {
    sid    = "MSKBrokerLogsToCloudWatch"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.msk_broker_logs.arn,
      "${aws_cloudwatch_log_group.msk_broker_logs.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "msk_cloudwatch_logs_write" {
  name   = "${local.name_prefix}-cw-logs-write"
  role   = aws_iam_role.msk_cloudwatch_logs.name
  policy = data.aws_iam_policy_document.msk_cloudwatch_logs_write.json
}

# -----------------------------------------------------------------------------
# IAM: MSK -> Kinesis Data Firehose (producer)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_firehose_producer_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_firehose_producer" {
  name               = "${local.name_prefix}-firehose-producer-role"
  description        = "Allows Amazon MSK to export broker logs to Kinesis Data Firehose"
  assume_role_policy = data.aws_iam_policy_document.msk_firehose_producer_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "msk_firehose_producer_write" {
  statement {
    sid    = "MSKBrokerLogsToFirehose"
    effect = "Allow"

    actions = [
      "firehose:PutRecord",
      "firehose:PutRecordBatch",
      "firehose:CheckIfProducerIsDisabled",
      "firehose:DescribeDeliveryStream",
      "firehose:ListDeliveryStreams",
    ]

    resources = [aws_kinesis_firehose_delivery_stream.msk_broker_logs.arn]
  }
}

resource "aws_iam_role_policy" "msk_firehose_producer_write" {
  name   = "${local.name_prefix}-firehose-producer-write"
  role   = aws_iam_role.msk_firehose_producer.name
  policy = data.aws_iam_policy_document.msk_firehose_producer_write.json
}

# -----------------------------------------------------------------------------
# IAM: MSK -> S3 (direct broker log delivery)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_s3_logs_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_s3_logs" {
  name               = "${local.name_prefix}-s3-logs-role"
  description        = "Allows Amazon MSK to export broker logs directly to S3"
  assume_role_policy = data.aws_iam_policy_document.msk_s3_logs_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "msk_s3_logs_write" {
  statement {
    sid    = "MSKBrokerLogsToS3"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.msk_broker_logs.arn,
      "${aws_s3_bucket.msk_broker_logs.arn}/${local.s3_log_prefix}/*",
    ]
  }

  statement {
    sid    = "MSKBrokerLogsS3KMS"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_role_policy" "msk_s3_logs_write" {
  name   = "${local.name_prefix}-s3-logs-write"
  role   = aws_iam_role.msk_s3_logs.name
  policy = data.aws_iam_policy_document.msk_s3_logs_write.json
}

# -----------------------------------------------------------------------------
# IAM: Firehose -> S3 (delivery role)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "firehose_s3_delivery_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_s3_delivery" {
  name               = "${local.name_prefix}-firehose-s3-role"
  description        = "Allows Kinesis Data Firehose to deliver broker logs to S3"
  assume_role_policy = data.aws_iam_policy_document.firehose_s3_delivery_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "firehose_s3_delivery_write" {
  statement {
    sid    = "FirehoseBrokerLogsToS3"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.msk_broker_logs.arn,
      "${aws_s3_bucket.msk_broker_logs.arn}/${local.s3_log_prefix}/*",
    ]
  }

  statement {
    sid    = "FirehoseBrokerLogsS3KMS"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_role_policy" "firehose_s3_delivery_write" {
  name   = "${local.name_prefix}-firehose-s3-write"
  role   = aws_iam_role.firehose_s3_delivery.name
  policy = data.aws_iam_policy_document.firehose_s3_delivery_write.json
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream (name MUST begin with "amazon-msk-")
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "msk_broker_logs" {
  name        = local.firehose_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose_s3_delivery.arn
    bucket_arn         = aws_s3_bucket.msk_broker_logs.arn
    prefix             = "${local.s3_log_prefix}/"
    buffering_size     = 5
    buffering_interval = 300
    compression_format = "GZIP"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.firehose_stream_name
  })

  depends_on = [aws_iam_role_policy.firehose_s3_delivery_write]
}

# -----------------------------------------------------------------------------
# Amazon MSK cluster (3 brokers, encryption at rest + TLS in transit, open monitoring)
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "kafka" {
  cluster_name           = local.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.public_1.id,
      aws_subnet.public_2.id,
      aws_subnet.public_3.id,
    ]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }

    connectivity_info {
      public_access {
        type = "DISABLED"
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }

      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_broker_logs.name
      }

      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_broker_logs.bucket
        prefix  = local.s3_log_prefix
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  depends_on = [
    aws_iam_role_policy.msk_cloudwatch_logs_write,
    aws_iam_role_policy.msk_firehose_producer_write,
    aws_iam_role_policy.msk_s3_logs_write,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the Amazon MSK cluster."
  value       = aws_msk_cluster.kafka.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints for Kafka client configuration."
  value       = aws_msk_cluster.kafka.bootstrap_brokers_tls
  sensitive   = true
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch Logs log group receiving MSK broker logs."
  value       = aws_cloudwatch_log_group.msk_broker_logs.name
}

output "firehose_delivery_stream_name" {
  description = "Kinesis Data Firehose delivery stream receiving MSK broker logs."
  value       = aws_kinesis_firehose_delivery_stream.msk_broker_logs.name
}

output "s3_bucket_name" {
  description = "S3 bucket receiving MSK broker logs."
  value       = aws_s3_bucket.msk_broker_logs.bucket
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data sources: static provider metadata / well-known lookups only
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Variables: naming/tagging defaults only (never infrastructure attributes)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "aurora"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  name_prefix        = "${var.project_name}-${var.environment}"
  cluster_identifier = "${local.name_prefix}-pg-${random_id.suffix.hex}"
  master_username    = "dbadmin"
  database_name      = "appdb"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Public subnets carry the Internet Gateway route for future edge workloads.
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index}" })
}

# Private subnets host the Aurora cluster: isolated, no internet route.
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-${count.index}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# KMS encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "aurora" {
  description             = "KMS key for ${local.name_prefix} Aurora PostgreSQL storage and secret encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-kms" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "aurora" {
  name          = "alias/${local.cluster_identifier}"
  target_key_id = aws_kms_key.aurora.key_id
}

# -----------------------------------------------------------------------------
# Security group: TCP 5432 from the VPC CIDR only
# -----------------------------------------------------------------------------

resource "aws_security_group" "aurora" {
  name        = "${local.name_prefix}-pg-sg"
  description = "Aurora PostgreSQL access for ${local.name_prefix} (TCP 5432 from VPC only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Intra-VPC egress required for cluster replication and management traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-sg" })
}

# -----------------------------------------------------------------------------
# DB subnet group
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "aurora" {
  name        = "${local.name_prefix}-pg-subnets"
  description = "Private subnets for ${local.name_prefix} Aurora PostgreSQL across multiple AZs"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-subnets" })
}

# -----------------------------------------------------------------------------
# Master credentials: generated, never plaintext, stored in Secrets Manager
# -----------------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}-pg-master-credentials"
  description = "Master credentials for the ${local.name_prefix} Aurora PostgreSQL cluster"
  kms_key_id  = aws_kms_key.aurora.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username             = local.master_username
    password             = random_password.db_master.result
    engine               = "aurora-postgresql"
    host                 = aws_rds_cluster.aurora.endpoint
    port                 = aws_rds_cluster.aurora.port
    dbname               = local.database_name
    dbInstanceIdentifier = aws_rds_cluster.aurora.cluster_identifier
  })
}

# -----------------------------------------------------------------------------
# Parameter groups (Aurora PostgreSQL 15)
# -----------------------------------------------------------------------------

resource "aws_rds_cluster_parameter_group" "aurora_cluster" {
  name        = "${local.name_prefix}-pg15-cluster-params"
  family      = "aurora-postgresql15"
  description = "Cluster-level parameters for the ${local.name_prefix} Aurora PostgreSQL 15 cluster"

  parameter {
    name         = "rds.logical_replication"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = local.common_tags
}

resource "aws_db_parameter_group" "aurora_db" {
  name        = "${local.name_prefix}-pg15-db-params"
  family      = "aurora-postgresql15"
  description = "Instance-level logging parameters for the ${local.name_prefix} Aurora PostgreSQL 15 cluster"

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  parameter {
    name  = "log_min_error_statement"
    value = "error"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }

  parameter {
    name  = "log_lock_waits"
    value = "1"
  }

  parameter {
    name  = "log_statement"
    value = "ddl"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Enhanced monitoring IAM (least privilege)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "rds_enhanced_monitoring" {
  name = "${local.name_prefix}-rds-enhanced-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "monitoring.rds.amazonaws.com",
            "rds.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "rds_enhanced_monitoring" {
  name        = "${local.name_prefix}-rds-enhanced-monitoring-policy"
  description = "Least-privilege policy for RDS enhanced monitoring: CloudWatch metrics, RDS logs, and EC2 instance discovery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PutRdsMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = ["*"]
        Condition = {
          StringEquals = {
            "cloudwatch:namespace" = "AWS/RDS"
          }
        }
      },
      {
        Sid    = "RdsMonitoringLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:PutRetentionPolicy",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:RDS*",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:RDS*:log-stream:*"
        ]
      },
      {
        Sid    = "DiscoverInstances"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeTags"
        ]
        Resource = ["*"]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = aws_iam_policy.rds_enhanced_monitoring.arn
}

# -----------------------------------------------------------------------------
# CloudWatch log group for PostgreSQL logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "aurora_postgresql" {
  name              = "/aws/rds/cluster/${local.cluster_identifier}/postgresql"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-postgresql-logs" })
}

# -----------------------------------------------------------------------------
# Aurora PostgreSQL cluster
# -----------------------------------------------------------------------------

resource "aws_rds_cluster" "aurora" {
  cluster_identifier              = local.cluster_identifier
  engine                          = "aurora-postgresql"
  engine_version                  = "15.5"
  engine_mode                     = "provisioned"
  database_name                   = local.database_name
  master_username                 = local.master_username
  master_password                 = random_password.db_master.result
  port                            = 5432

  db_subnet_group_name            = aws_db_subnet_group.aurora.name
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora_cluster.name
  vpc_security_group_ids          = [aws_security_group.aurora.id]

  storage_encrypted = true
  kms_key_id        = aws_kms_key.aurora.arn

  deletion_protection          = true
  backup_retention_period      = 14
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot        = true
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${local.cluster_identifier}-final"

  enabled_cloudwatch_logs_exports = ["postgresql"]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-aurora" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier              = "${local.cluster_identifier}-writer"
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = "db.r6g.large"
  engine                  = "aurora-postgresql"
  engine_version          = aws_rds_cluster.aurora.engine_version
  db_parameter_group_name = aws_db_parameter_group.aurora_db.name

  availability_zone   = data.aws_availability_zones.available.names[0]
  publicly_accessible = false

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn

  monitoring_interval        = 60
  monitoring_role_arn        = aws_iam_role.rds_enhanced_monitoring.arn
  auto_minor_version_upgrade = true

  tags = merge(local.common_tags, { Name = "${local.cluster_identifier}-writer" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "reader" {
  identifier              = "${local.cluster_identifier}-reader"
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = "db.r6g.large"
  engine                  = "aurora-postgresql"
  engine_version          = aws_rds_cluster.aurora.engine_version
  db_parameter_group_name = aws_db_parameter_group.aurora_db.name

  availability_zone   = data.aws_availability_zones.available.names[1]
  publicly_accessible = false

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn

  monitoring_interval        = 60
  monitoring_role_arn        = aws_iam_role.rds_enhanced_monitoring.arn
  auto_minor_version_upgrade = true

  promotion_tier = 15

  depends_on = [aws_rds_cluster_instance.writer]

  tags = merge(local.common_tags, { Name = "${local.cluster_identifier}-reader" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cluster_writer_endpoint" {
  description = "Writer endpoint of the Aurora PostgreSQL cluster."
  value       = aws_rds_cluster.aurora.endpoint
}

output "cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora PostgreSQL cluster."
  value       = aws_rds_cluster.aurora.reader_endpoint
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Aurora PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups only
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Variable (tagging only)
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used exclusively for resource tags. Never used as a substitute for a resource attribute."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  db_master_username        = "dbadmin"
  final_snapshot_identifier = "greenfield-postgres-final-snapshot"

  common_tags = {
    environment = var.environment
    managed_by  = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking foundation
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { name = "main" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.11.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { name = "postgres-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.12.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { name = "postgres-private-b" })
}

resource "aws_db_subnet_group" "main" {
  name        = "postgres-private-subnet-group"
  description = "Private subnets spanning two AZs for the PostgreSQL instance"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = local.common_tags
}

resource "aws_security_group" "postgres" {
  name        = "postgres-access"
  description = "Allow inbound PostgreSQL (5432) from the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # Intentionally no egress rules: the database does not require outbound
  # access, and the security group is stateful for return traffic.

  tags = merge(local.common_tags, { name = "postgres-access" })
}

# ---------------------------------------------------------------------------
# Encryption key and master credentials (no plaintext secrets)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "rds" {
  description             = "Encrypts PostgreSQL storage, Performance Insights, and the master credentials secret"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.common_tags
}

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "rds/postgres/master-credentials"
  description = "Master credentials for the greenfield PostgreSQL instance"
  kms_key_id  = aws_kms_key.rds.arn

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.master.result
  })
}

# ---------------------------------------------------------------------------
# Enhanced monitoring IAM role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "rds_enhanced_monitoring" {
  name = "rds-enhanced-monitoring"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# ---------------------------------------------------------------------------
# Parameter group (security and audit settings)
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "postgres16" {
  name        = "postgres16-secure"
  family      = "postgres16"
  description = "Security and audit parameters for PostgreSQL 16"

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_disconnections"
    value        = "1"
    apply_method = "immediate"
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# PostgreSQL instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "postgres" {
  identifier     = "greenfield-postgres"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.medium"

  db_name  = "appdb"
  port     = 5432
  username = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["password"]

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  parameter_group_name   = aws_db_parameter_group.postgres16.name
  publicly_accessible    = false

  multi_az                   = true
  auto_minor_version_upgrade = true

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = local.final_snapshot_identifier

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_enhanced_monitoring.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { name = "greenfield-postgres" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "database_endpoint" {
  description = "Hostname (address) of the PostgreSQL instance."
  value       = aws_db_instance.postgres.address
  sensitive   = true
}

output "database_port" {
  description = "Port the PostgreSQL instance listens on."
  value       = aws_db_instance.postgres.port
}

output "database_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db_credentials.arn
  sensitive   = true
}

###############################################################################
# Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Primary region. Replica regions are declared on the table resource itself.
provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "tags" {
  description = "Non-secret tags applied to the DynamoDB table (name, environment, managed-by)."
  type        = map(string)

  default = {
    "name"       = "global-data-table"
    "managed-by" = "terraform"
    "environment" = "production"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # Single source of truth for the table name, taken from the tags map.
  table_name = var.tags["name"]
}

###############################################################################
# DynamoDB Global Table
# Primary: us-east-1 | Replicas: us-west-1, us-west-2
###############################################################################

resource "aws_dynamodb_table" "global_table" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST" # Required for global table replicas
  hash_key     = "PK"

  attribute {
    name = "PK"
    type = "S"
  }

  # DynamoDB Streams are a prerequisite for global table replication.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  # Replica in us-west-1.
  replica {
    region_name = "us-west-1"
  }

  # Replica in us-west-2.
  replica {
    region_name = "us-west-2"
  }

  # Server-side encryption using the AWS-managed DynamoDB KMS key.
  # A customer-managed key is intentionally not pinned, because global table
  # replicas require a per-region key to function correctly.
  server_side_encryption {
    enabled = true
  }

  # Point-in-time recovery for the table.
  point_in_time_recovery {
    enabled = true
  }

  # Deletion protection for the table.
  deletion_protection_enabled = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "table_name" {
  description = "Name of the DynamoDB global table."
  value       = aws_dynamodb_table.global_table.name
}

output "table_arn" {
  description = "ARN of the DynamoDB global table (primary region: us-east-1)."
  value       = aws_dynamodb_table.global_table.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  environment = "production"
  vpc_cidr    = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "dax-vpc"
    Environment = local.environment
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "dax-private-subnet-${count.index}"
    Environment = local.environment
  }
}

resource "aws_dax_subnet_group" "main" {
  name        = "dax_subnet_group_main"
  description = "DAX subnet group spanning private subnets in two Availability Zones"
  subnet_ids  = [aws_subnet.private[0].id, aws_subnet.private[1].id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

locals {
  dynamodb_table_name = "application_data"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "dynamodb_key" {
  description             = "Customer-managed KMS key for DynamoDB server-side encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "dynamodb-table-key"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dynamodb_key" {
  name          = "alias/dynamodb-table-key"
  target_key_id = aws_kms_key.dynamodb_key.key_id
}

resource "aws_dynamodb_table" "main" {
  name         = local.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_key.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.dynamodb_table_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
