terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  description = "EC2 instance type for the Ubuntu server."
  type        = string
  default     = "t3.micro"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "IPv4 CIDR block for the public subnet, carved from the VPC range."
  type        = string
  default     = "10.0.1.0/24"
}

locals {
  project_name = "ubuntu-ec2-vpc"

  common_tags = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu_2004" {
  most_recent = true
  owners      = ["099720109477", "self"]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.project_name}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.project_name}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.project_name}-public-subnet"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.project_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "${local.project_name}-web-sg"
  description = "Allow inbound HTTP and HTTPS only, all outbound"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.project_name}-web-sg"
    }
  )
}

resource "aws_instance" "ubuntu" {
  ami                         = data.aws_ami.ubuntu_2004.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.project_name}-instance"
    }
  )
}

# -----------------------------------------------------------------------------
# Neptune deployment: dedicated VPC, multi-AZ subnets, custom cluster and
# instance parameter groups, KMS-encrypted cluster with one writer instance.
# -----------------------------------------------------------------------------

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs (single variable for common tagging)
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and applied as a common tag to all resources."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,18}$", var.environment))
    error_message = "Environment name must start with a lowercase letter and contain only lowercase letters, digits, and hyphens (max 19 characters), since it is embedded in AWS resource identifiers."
  }
}

locals {
  name = "neptune-${var.environment}"

  common_tags = {
    Environment = var.environment
    Component   = "neptune"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "neptune_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-a"
  })
}

resource "aws_subnet" "neptune_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-b"
  })
}

resource "aws_neptune_subnet_group" "main" {
  name       = "${local.name}-subnet-group"
  subnet_ids = [aws_subnet.neptune_a.id, aws_subnet.neptune_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-group"
  })
}

resource "aws_security_group" "neptune" {
  name        = "${local.name}-sg"
  description = "Permit Neptune engine traffic on TCP 8182 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Neptune engine access from VPC CIDR only"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-sg"
  })
}

# -----------------------------------------------------------------------------
# Encryption key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "neptune" {
  description             = "Customer-managed key for Neptune cluster storage encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.name}-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Parameter groups
# -----------------------------------------------------------------------------

resource "aws_neptune_cluster_parameter_group" "main" {
  family = "neptune1.3"
  name   = "${local.name}-cluster-pg"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  parameter {
    name  = "neptune_lab_mode"
    value = "disabled"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster-pg"
  })
}

resource "aws_neptune_parameter_group" "writer" {
  family = "neptune1.3"
  name   = "${local.name}-instance-pg"

  parameter {
    name  = "neptune_query_timeout"
    value = "120000"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-instance-pg"
  })
}

# -----------------------------------------------------------------------------
# Neptune cluster and writer instance
# -----------------------------------------------------------------------------

resource "aws_neptune_cluster" "main" {
  cluster_identifier                   = "${local.name}-cluster"
  engine                               = "neptune"
  engine_version                       = "1.3.2.1"
  port                                 = 8182
  neptune_subnet_group_name            = aws_neptune_subnet_group.main.name
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.main.id
  vpc_security_group_ids               = [aws_security_group.neptune.id]

  storage_encrypted               = true
  kms_key_arn                     = aws_kms_key.neptune.arn
  enable_cloudwatch_logs_exports  = ["audit"]

  deletion_protection          = true
  backup_retention_period      = 7
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${local.name}-cluster-final"

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "writer" {
  identifier                   = "${local.name}-writer"
  cluster_identifier           = aws_neptune_cluster.main.id
  engine                       = "neptune"
  engine_version               = "1.3.2.1"
  instance_class               = "db.r5.large"
  neptune_parameter_group_name = aws_neptune_parameter_group.writer.id

  # Tier 0 = highest failover priority; this single member is the cluster writer.
  promotion_tier = 0

  tags = merge(local.common_tags, {
    Name = "${local.name}-writer"
    Role = "writer"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  environment                    = "production"
  primary_voice_connector_name   = "primary-voice-connector"
  secondary_voice_connector_name = "secondary-voice-connector"
  voice_connector_group_name     = "voice-connector-group-main"
}

resource "aws_chime_voice_connector" "primary" {
  name               = local.primary_voice_connector_name
  aws_region         = "us-east-1"
  require_encryption = true

  tags = {
    Name        = local.primary_voice_connector_name
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector" "secondary" {
  name               = local.secondary_voice_connector_name
  aws_region         = "us-east-1"
  require_encryption = true

  tags = {
    Name        = local.secondary_voice_connector_name
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector_group" "main" {
  name = local.voice_connector_group_name

  connector {
    voice_connector_id = aws_chime_voice_connector.primary.id
    priority           = 1
  }

  connector {
    voice_connector_id = aws_chime_voice_connector.secondary.id
    priority           = 3
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to the Chime Voice Connector."
  type        = map(string)

  default = {
    Environment = "dev"
    Project     = "chime-voice-connector"
  }
}

locals {
  voice_connector_name   = "voice-connector-main"
  voice_connector_region = "us-east-1"
}

resource "aws_chime_voice_connector" "main" {
  name               = local.voice_connector_name
  aws_region         = local.voice_connector_region
  require_encryption = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector_logging" "main" {
  voice_connector_id       = aws_chime_voice_connector.main.id
  enable_media_metric_logs = true
  enable_sip_logs          = false
}

output "voice_connector_id" {
  description = "The ID of the Chime Voice Connector."
  value       = aws_chime_voice_connector.main.id
}

output "voice_connector_outbound_host_name" {
  description = "The outbound host name of the Chime Voice Connector."
  value       = aws_chime_voice_connector.main.outbound_host_name
}

###############################################################################
# Greenfield Amazon Redshift deployment:
#   - Dedicated VPC with two subnets across two Availability Zones
#   - Redshift subnet group spanning both AZs (two-subnet endpoint access)
#   - Cluster encryption at rest with a customer-managed KMS key
#   - Master credentials managed natively by Redshift in Secrets Manager
#   - Audit logging to a private, encrypted, versioned S3 bucket
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# -----------------------------------------------------------------------------
# Static, well-known lookups only (no pre-existing infrastructure discovered)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used as the naming prefix and Project tag."
  type        = string
  default     = "data-platform"
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated Redshift VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "subnet_a_cidr" {
  description = "CIDR block for the first Redshift subnet (AZ 1)."
  type        = string
  default     = "10.0.1.0/24"

  validation {
    condition     = can(cidrnetmask(var.subnet_a_cidr))
    error_message = "subnet_a_cidr must be a valid IPv4 CIDR block."
  }
}

variable "subnet_b_cidr" {
  description = "CIDR block for the second Redshift subnet (AZ 2)."
  type        = string
  default     = "10.0.2.0/24"

  validation {
    condition     = can(cidrnetmask(var.subnet_b_cidr))
    error_message = "subnet_b_cidr must be a valid IPv4 CIDR block."
  }
}

variable "admin_cidr_blocks" {
  description = "Optional, tightly scoped admin CIDR blocks allowed to reach the Redshift port from outside the VPC. Must never include 0.0.0.0/0."
  type        = list(string)
  default     = []

  validation {
    condition     = length([for c in var.admin_cidr_blocks : c if c == "0.0.0.0/0" || c == "::/0"]) == 0
    error_message = "admin_cidr_blocks must not include 0.0.0.0/0 or ::/0."
  }
}

variable "database_name" {
  description = "Name of the initial database created in the cluster."
  type        = string
  default     = "analyticsdb"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{0,63}$", var.database_name))
    error_message = "database_name must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 64)."
  }
}

variable "master_username" {
  description = "Master username for the cluster (non-sensitive). The password itself is generated and rotated by Redshift in Secrets Manager."
  type        = string
  default     = "redshiftadmin"

  validation {
    condition     = can(regex("^[A-Za-z][A-Za-z0-9_]{0,127}$", var.master_username))
    error_message = "master_username must start with a letter and contain only letters, digits, and underscores (max 128)."
  }
}

variable "node_type" {
  description = "Redshift node type."
  type        = string
  default     = "ra3.xlplus"
}

variable "cluster_type" {
  description = "Redshift cluster type: single-node or multi-node."
  type        = string
  default     = "multi-node"

  validation {
    condition     = contains(["single-node", "multi-node"], var.cluster_type)
    error_message = "cluster_type must be 'single-node' or 'multi-node'."
  }
}

variable "number_of_nodes" {
  description = "Number of compute nodes (automatically forced to 1 when cluster_type is single-node)."
  type        = number
  default     = 2

  validation {
    condition     = var.number_of_nodes >= 1 && var.number_of_nodes <= 128
    error_message = "number_of_nodes must be between 1 and 128."
  }
}

variable "automated_snapshot_retention_period" {
  description = "Automated snapshot retention period in days (minimum 7)."
  type        = number
  default     = 7

  validation {
    condition     = var.automated_snapshot_retention_period >= 7 && var.automated_snapshot_retention_period <= 35
    error_message = "automated_snapshot_retention_period must be between 7 and 35 days."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  name_prefix        = var.project_name
  common_tags        = merge(var.tags, { Project = var.project_name })
  cluster_identifier = "${var.project_name}-redshift-cluster"
  subnet_group_name  = "${var.project_name}-redshift-subnet-group"
  audit_bucket_name  = "${var.project_name}-redshift-audit-logs-${random_id.bucket_suffix.hex}"
  final_snapshot_id  = "${var.project_name}-redshift-final-${random_id.bucket_suffix.hex}"
  redshift_port      = 5439
  number_of_nodes    = var.cluster_type == "single-node" ? 1 : var.number_of_nodes
}

# -----------------------------------------------------------------------------
# Networking: dedicated VPC, two subnets across AZs, IGW + routing
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "redshift_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-az1" })
}

resource "aws_subnet" "redshift_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-az2" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rt" })
}

resource "aws_route_table_association" "redshift_a" {
  subnet_id      = aws_subnet.redshift_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "redshift_b" {
  subnet_id      = aws_subnet.redshift_b.id
  route_table_id = aws_route_table.main.id
}

# -----------------------------------------------------------------------------
# Security group: engine port reachable only from the VPC CIDR and
# (optionally) tightly scoped admin CIDRs. Never 0.0.0.0/0 on 5439.
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift engine access restricted to the VPC CIDR and approved admin CIDRs"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift engine port from within the VPC"
    from_port   = local.redshift_port
    to_port     = local.redshift_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  dynamic "ingress" {
    for_each = var.admin_cidr_blocks

    content {
      description = "Redshift engine port from approved admin CIDR"
      from_port   = local.redshift_port
      to_port     = local.redshift_port
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
}

# -----------------------------------------------------------------------------
# Redshift subnet group spanning both Availability Zones
# -----------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = local.subnet_group_name
  description = "Redshift subnet group spanning two AZs for ${local.cluster_identifier}"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# KMS key for encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Customer managed key for ${local.cluster_identifier} encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

# -----------------------------------------------------------------------------
# Parameter group: enforce TLS for all connections
# -----------------------------------------------------------------------------

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-redshift-params"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# S3 bucket for Redshift audit logs (private, encrypted, versioned)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "redshift_audit_logs" {
  bucket = local.audit_bucket_name

  tags = merge(local.common_tags, { Name = local.audit_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  depends_on = [aws_s3_bucket_public_access_block.redshift_audit_logs]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RedshiftAuditLogAclCheck"
        Effect    = "Allow"
        Principal = { Service = "redshift.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.redshift_audit_logs.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "RedshiftAuditLogWrite"
        Effect    = "Allow"
        Principal = { Service = "redshift.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.redshift_audit_logs.arn}/audit/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Redshift cluster (private endpoint, encrypted, secret-managed credentials)
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier = local.cluster_identifier
  database_name      = var.database_name
  master_username    = var.master_username

  # Master password is generated, rotated, and stored in Secrets Manager by
  # Redshift itself. No secret value ever appears in this configuration.
  manage_master_password = true

  node_type       = var.node_type
  cluster_type    = var.cluster_type
  number_of_nodes = local.number_of_nodes
  port            = local.redshift_port

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  publicly_accessible          = false

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  automated_snapshot_retention_period = var.automated_snapshot_retention_period
  skip_final_snapshot                 = false
  final_snapshot_identifier           = local.final_snapshot_id

  logging {
    enable               = true
    log_destination_type = "s3"
    bucket_name          = aws_s3_bucket.redshift_audit_logs.id
    s3_key_prefix        = "audit/"
  }

  tags = merge(local.common_tags, { Name = local.cluster_identifier })

  depends_on = [aws_s3_bucket_policy.redshift_audit_logs]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "redshift_cluster_address" {
  description = "Hostname of the Redshift cluster endpoint."
  value       = aws_redshift_cluster.main.dns_name
}

output "redshift_cluster_port" {
  description = "Port on which the Redshift cluster accepts connections."
  value       = aws_redshift_cluster.main.port
}

output "redshift_cluster_endpoint" {
  description = "Full Redshift connection endpoint (address:port)."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_cluster_database_name" {
  description = "Initial database created on the cluster."
  value       = aws_redshift_cluster.main.database_name
}

output "redshift_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (created and rotated by Redshift)."
  value       = aws_redshift_cluster.main.master_password_secret_arn
}

output "redshift_cluster_subnet_group" {
  description = "Name of the Redshift subnet group providing endpoint access from two subnets."
  value       = aws_redshift_subnet_group.main.name
}

output "redshift_cluster_subnet_ids" {
  description = "IDs of the two subnets (one per Availability Zone) that provide cluster endpoint access."
  value       = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for consistent resource tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  master_username = "exampleadmin"

  tags = {
    Environment = var.environment
    Project     = "redshift-example"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Greenfield network
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "redshift-example-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, {
    Name = "redshift-example-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, {
    Name = "redshift-example-private-b"
  })
}

resource "aws_security_group" "redshift" {
  name        = "example-redshift-sg"
  description = "Restrict Redshift access to port 5439 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, {
    Name = "example-redshift-sg"
  })
}

# ------------------------------------------------------------------------------
# Redshift subnet group and example parameter group
# ------------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "example" {
  name        = "example-redshift-subnet-group"
  description = "Subnet group for the example Redshift cluster"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = local.tags
}

resource "aws_redshift_parameter_group" "example" {
  name        = "example-redshift-parameter-group"
  family      = "redshift-1.0"
  description = "Example parameter group attached to the example Redshift cluster"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "wlm_json_configuration"
    value = "[{\"user_group\":[\"example_user_group\"],\"query_concurrency\":5}]"
  }

  tags = local.tags
}

# ------------------------------------------------------------------------------
# Master credentials (generated, stored in Secrets Manager)
# ------------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift" {
  name        = "example/${var.environment}/redshift/master-password"
  description = "Master credentials for the example Redshift cluster"

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id = aws_secretsmanager_secret.redshift.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# ------------------------------------------------------------------------------
# Redshift cluster
# ------------------------------------------------------------------------------

resource "aws_redshift_cluster" "example" {
  cluster_identifier           = "example-redshift-cluster"
  database_name                = "exampledb"
  cluster_type                 = "single-node"
  node_type                    = "ra3.xlplus"
  master_username              = local.master_username
  master_password              = random_password.redshift_master.result
  cluster_subnet_group_name    = aws_redshift_subnet_group.example.name
  cluster_parameter_group_name = aws_redshift_parameter_group.example.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  publicly_accessible          = false
  encrypted                    = true
  skip_final_snapshot          = true

  tags = merge(local.tags, {
    Name            = "example-redshift-cluster"
    MasterSecretArn = aws_secretsmanager_secret.redshift.arn
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Event notifications: KMS-encrypted SNS topic wired to the parameter group
# ------------------------------------------------------------------------------

resource "aws_kms_key" "redshift_events" {
  description             = "KMS key used to encrypt the Redshift event notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowRedshiftToPublishEncryptedEvents"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "redshift_events" {
  name          = "alias/example-redshift-events"
  target_key_id = aws_kms_key.redshift_events.key_id
}

resource "aws_sns_topic" "redshift_events" {
  name              = "example-redshift-events"
  kms_master_key_id = aws_kms_key.redshift_events.arn

  tags = merge(local.tags, {
    Name = "example-redshift-events"
  })
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRedshiftEventPublish"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.redshift_events.arn
      }
    ]
  })
}

resource "aws_redshift_event_subscription" "redshift_events" {
  name          = "example-redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster-parameter-group"
  source_ids    = [aws_redshift_parameter_group.example.name]
  severity      = "INFO"
  enabled       = true

  depends_on = [aws_sns_topic_policy.redshift_events]

  tags = local.tags
}

# Basic AWS IAM group example.
#
# Creates:
#   - An IAM group (name configurable via variable with a default value)
#   - A least-privilege customer-managed policy scoped to a team S3 bucket
#     created in this same configuration, attached via aws_iam_group_policy_attachment
#   - A sample IAM user and group membership
#   - Outputs for downstream verification of the group name and ARN

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs (all defaults set so `terraform apply` runs unattended)
# -----------------------------------------------------------------------------

variable "iam_group_name" {
  description = "Name of the IAM group to create."
  type        = string
  default     = "developers"
}

variable "sample_user_name" {
  description = "Name of the sample IAM user added to the group."
  type        = string
  default     = "sample-developer"
}

variable "artifact_bucket_name_prefix" {
  description = "Name prefix for the S3 bucket the developers group is granted access to."
  type        = string
  default     = "developers-team-artifacts"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  artifact_bucket_name = "${var.artifact_bucket_name_prefix}-${random_id.bucket_suffix.hex}"

  common_tags = {
    ManagedBy   = "terraform"
    Component   = "iam-group-example"
    Environment = "sandbox"
  }
}

# -----------------------------------------------------------------------------
# Random suffix keeps the globally-unique S3 bucket name collision-free
# -----------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# Team artifacts bucket that anchors the least-privilege policy scope
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "team_artifacts" {
  bucket = local.artifact_bucket_name

  tags = merge(local.common_tags, {
    Name = local.artifact_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "team_artifacts" {
  bucket = aws_s3_bucket.team_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "team_artifacts" {
  bucket = aws_s3_bucket.team_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "team_artifacts" {
  bucket = aws_s3_bucket.team_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM group (IAM groups are not a taggable IAM resource type; no tags argument)
# -----------------------------------------------------------------------------

resource "aws_iam_group" "developers" {
  name = var.iam_group_name
  path = "/teams/"
}

# -----------------------------------------------------------------------------
# Least-privilege policy: explicit, scoped actions and resources only
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "developers_artifacts_access" {
  statement {
    sid     = "ListTeamArtifactsBucket"
    effect  = "Allow"
    actions = ["s3:ListBucket", "s3:GetBucketLocation"]

    resources = [
      aws_s3_bucket.team_artifacts.arn,
    ]
  }

  statement {
    sid     = "ManageTeamArtifactsObjects"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]

    resources = [
      "${aws_s3_bucket.team_artifacts.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "developers_artifacts_access" {
  name        = "developers-artifacts-access"
  description = "Least-privilege S3 access to the developers team artifacts bucket"
  policy      = data.aws_iam_policy_document.developers_artifacts_access.json

  tags = local.common_tags
}

resource "aws_iam_group_policy_attachment" "developers_artifacts_access" {
  group      = aws_iam_group.developers.name
  policy_arn = aws_iam_policy.developers_artifacts_access.arn
}

# -----------------------------------------------------------------------------
# Sample user and group membership
# -----------------------------------------------------------------------------

resource "aws_iam_user" "sample_developer" {
  name          = var.sample_user_name
  path          = "/teams/"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = var.sample_user_name
  })
}

resource "aws_iam_group_membership" "developers" {
  name  = "developers-team-membership"
  group = aws_iam_group.developers.name
  users = [aws_iam_user.sample_developer.name]
}

# -----------------------------------------------------------------------------
# Outputs for downstream verification
# -----------------------------------------------------------------------------

output "iam_group_name" {
  description = "Name of the developers IAM group."
  value       = aws_iam_group.developers.name
}

output "iam_group_arn" {
  description = "ARN of the developers IAM group."
  value       = aws_iam_group.developers.arn
}

output "iam_group_policy_arn" {
  description = "ARN of the customer-managed policy attached to the group."
  value       = aws_iam_policy.developers_artifacts_access.arn
}

output "sample_iam_user_name" {
  description = "Name of the sample IAM user belonging to the group."
  value       = aws_iam_user.sample_developer.name
}

# Website image storage: fully private S3 bucket served exclusively
# through CloudFront using Origin Access Control (OAC). Images are uploaded
# to the bucket (output below) and embedded on the website via the
# CloudFront distribution domain name - no public bucket access required.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Single user-controlled input: used strictly for naming and tagging.
# All infrastructure attributes are referenced via resource addresses.
# -----------------------------------------------------------------------------
variable "project_name" {
  description = "Short project name (lowercase letters, numbers, and hyphens) used for resource naming and tagging."
  type        = string
  default     = "my-website"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,48}[a-z0-9]$", var.project_name))
    error_message = "project_name must be 2-50 lowercase alphanumeric characters or hyphens so it forms a valid S3 bucket name."
  }
}

# -----------------------------------------------------------------------------
# Locals: single source of truth for derived names and tags.
# random_id guarantees a globally unique S3 bucket name (bucket names must be
# unique across all AWS accounts).
# -----------------------------------------------------------------------------
locals {
  bucket_name = "${var.project_name}-images-${random_id.suffix.hex}"
  origin_id   = "s3-website-images-${random_id.suffix.hex}"

  tags = {
    Name       = local.bucket_name
    project    = var.project_name
    purpose    = "website_image_assets"
    managed_by = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Unique name suffix
# -----------------------------------------------------------------------------
resource "random_id" "suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# S3 bucket for website images (stateful - protected from accidental destroy)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "website_images" {
  bucket = local.bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "website_images" {
  bucket = aws_s3_bucket.website_images.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "website_images" {
  bucket = aws_s3_bucket.website_images.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "website_images" {
  bucket = aws_s3_bucket.website_images.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "website_images" {
  bucket = aws_s3_bucket.website_images.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# -----------------------------------------------------------------------------
# CloudFront Origin Access Control: CloudFront signs every origin request
# with SigV4 ("always"), making CloudFront the only authorized reader of
# the otherwise fully private image bucket.
# -----------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "website_images" {
  name                              = "${var.project_name}-images-oac-${random_id.suffix.hex}"
  description                       = "OAC for the ${var.project_name} website images S3 origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# -----------------------------------------------------------------------------
# CloudFront distribution: the public, HTTPS-only entry point for images.
# -----------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "website_images" {
  enabled         = true
  is_ipv6_enabled = true
  price_class     = "PriceClass_100"

  origin {
    domain_name              = aws_s3_bucket.website_images.bucket_regional_domain_name
    origin_id                = local.origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.website_images.id
  }

  default_cache_behavior {
    target_origin_id = local.origin_id

    # Images are immutable static assets: allow and cache only GET and HEAD.
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    # AWS-managed "CachingOptimized" cache policy - a globally well-known,
    # static identifier (not an account-specific resource ID).
    cache_policy_id = "658327ea-f89d-4fab-a63d-7e88639e58f6"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  # Default CloudFront (*.cloudfront.net) viewer certificate - no custom domain.
  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = local.tags
}

# -----------------------------------------------------------------------------
# Least-privilege bucket policy: grants ONLY s3:GetObject to the
# cloudfront.amazonaws.com service principal, scoped to this bucket's object
# ARN and locked to THIS distribution via the AWS:SourceArn condition.
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "website_images_cloudfront_read" {
  statement {
    sid       = "AllowCloudFrontServicePrincipalRead"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.website_images.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.website_images.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "website_images" {
  bucket = aws_s3_bucket.website_images.id
  policy = data.aws_iam_policy_document.website_images_cloudfront_read.json

  # Ensure the public-access block and ownership controls are applied before
  # the bucket policy to avoid put-bucket-policy race conditions.
  depends_on = [
    aws_s3_bucket_public_access_block.website_images,
    aws_s3_bucket_ownership_controls.website_images,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "website_images_cdn_domain_name" {
  description = "Public CloudFront domain name. Use as the base URL when embedding image links on the website (e.g. https://<domain_name>/<image-key>)."
  value       = aws_cloudfront_distribution.website_images.domain_name
}

output "website_images_bucket_name" {
  description = "Name of the private S3 bucket where website images should be uploaded."
  value       = aws_s3_bucket.website_images.id
}

