  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Variables - only user-controlled, non-infrastructure values with unattended
# defaults. No secret values in any variable default or local.
# ------------------------------------------------------------------------------

variable "project_name" {
  description = "Short name used to prefix every autograder resource (also the CodeBuild project name)."
  type        = string
  default     = "cs101-autograder"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,43}[a-z0-9]$", var.project_name))
    error_message = "project_name must be 2-45 lowercase alphanumeric characters or hyphens (it feeds S3/KMS/IAM naming)."
  }
}

variable "github_repo_url" {
  description = "HTTPS clone URL of the GitHub repository holding the student submissions / grading harness."
  type        = string
  default     = "https://github.com/example-org/cs101-autograder.git"
}

variable "github_source_version" {
  description = "Branch, tag, or commit SHA of the student repository to check out and grade."
  type        = string
  default     = "main"
}

variable "results_retention_days" {
  description = "Days before graded results (and test reports) expire from the results bucket."
  type        = number
  default     = 90

  validation {
    condition     = var.results_retention_days >= 31
    error_message = "results_retention_days must be at least 31 so results outlive the 30-day STANDARD_IA transition."
  }
}

variable "log_retention_days" {
  description = "CloudWatch Logs retention (in days) for the CodeBuild build logs."
  type        = number
  default     = 30

  validation {
    condition     = contains([1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653], var.log_retention_days)
    error_message = "log_retention_days must be a valid CloudWatch Logs retention value (1, 3, 5, 7, 14, 30, ...)."
  }
}

variable "grading_timeout_seconds" {
  description = "Wall-clock budget (seconds) enforced on each student grading run inside the build."
  type        = number
  default     = 600

  validation {
    condition     = var.grading_timeout_seconds >= 10 && var.grading_timeout_seconds <= 3600
    error_message = "grading_timeout_seconds must be between 10 and 3600 seconds."
  }
}

variable "language_runtime" {
  description = "Language runtime label passed to the grader scripts (e.g. python3.11)."
  type        = string
  default     = "python3.11"
}

variable "grader_credential" {
  description = "Optional credential value (e.g. GitHub PAT or LMS API key) to store in Secrets Manager. Leave empty to auto-generate a random grader token at apply time."
  type        = string
  default     = ""
  sensitive   = true
}

variable "tags" {
  description = "Additional tags merged onto every resource."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  log_group_name      = "/aws/codebuild/${var.project_name}"
  log_group_arn       = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${local.log_group_name}"
  results_bucket_name = "${var.project_name}-results-${random_id.bucket_suffix.hex}"
  common_tags         = merge({ ManagedBy = "terraform", Project = var.project_name }, var.tags)
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_password" "grader_token" {
  length  = 32
  special = false
}

# ------------------------------------------------------------------------------
# Dedicated customer-managed KMS key (results bucket + CodeBuild logs + secrets)
# ------------------------------------------------------------------------------

resource "aws_kms_key" "autograder" {
  description             = "CMK used to encrypt the autograder results bucket, CodeBuild logs, and grader credentials"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsToUseTheKey"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.${data.aws_partition.current.partition}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = [
              local.log_group_arn,
              "${local.log_group_arn}:*",
            ]
          }
        }
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-results-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "autograder_results" {
  name          = "alias/${var.project_name}-results"
  target_key_id = aws_kms_key.autograder.key_id
}

# ------------------------------------------------------------------------------
# Results bucket (stateful grading data)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "autograder_results" {
  bucket        = local.results_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.results_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.autograder.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    id     = "expire-results"
    status = "Enabled"

    filter {
      prefix = "results/"
    }

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    expiration {
      days = var.results_retention_days
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  rule {
    id     = "expire-reports"
    status = "Enabled"

    filter {
      prefix = "reports/"
    }

    expiration {
      days = var.results_retention_days
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_policy" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

# ------------------------------------------------------------------------------
# CodeBuild service identity (least-privilege inline policy)
# ------------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_autograder" {
  name        = "${var.project_name}-codebuild-role"
  description = "Service role assumed by the ${var.project_name} CodeBuild autograder"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-codebuild-role"
  })
}

resource "aws_iam_role_policy" "codebuild_autograder" {
  name = "${var.project_name}-codebuild-inline"
  role = aws_iam_role.codebuild_autograder.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListResultsBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.autograder_results.arn,
        ]
      },
      {
        Sid    = "ReadWriteResultsObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:AbortMultipartUpload",
        ]
        Resource = [
          "${aws_s3_bucket.autograder_results.arn}/results/*",
          "${aws_s3_bucket.autograder_results.arn}/reports/*",
        ]
      },
      {
        Sid    = "WriteBuildLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild.arn,
          "${aws_cloudwatch_log_group.codebuild.arn}:*",
        ]
      },
      {
        Sid    = "UseResultsCMK"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = [
          aws_kms_key.autograder.arn,
        ]
      },
      {
        Sid    = "ReadGraderCredentials"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
        ]
        Resource = [
          aws_secretsmanager_secret.grader_credentials.arn,
        ]
      },
      {
        Sid    = "PublishTestReports"
        Effect = "Allow"
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:UpdateReport",
          "codebuild:BatchPutTestResults",
        ]
        Resource = [
          aws_codebuild_report_group.autograder_tests.arn,
        ]
      },
    ]
  })
}

# ------------------------------------------------------------------------------
# Central, encrypted build logging
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "codebuild" {
  name              = local.log_group_name
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.autograder.arn

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

# ------------------------------------------------------------------------------
# Grader credentials (Secrets Manager; injected as SECRETS_MANAGER env var)
# ------------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "grader_credentials" {
  name        = "${var.project_name}/grader-credentials"
  description = "Credentials used by the autograder (e.g. GitHub PAT for private repos or LMS API key)"
  kms_key_id  = aws_kms_key.autograder.arn

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-grader-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "grader_credentials" {
  secret_id     = aws_secretsmanager_secret.grader_credentials.id
  secret_string = var.grader_credential != "" ? var.grader_credential : random_password.grader_token.result
}

# ------------------------------------------------------------------------------
# Test report group (JUnit reports exported to S3)
# ------------------------------------------------------------------------------

resource "aws_codebuild_report_group" "autograder_tests" {
  name           = "${var.project_name}-test-reports"
  type           = "TEST"
  delete_reports = true

  export_config {
    type = "S3"

    s3_destination {
      bucket              = aws_s3_bucket.autograder_results.id
      encryption_disabled = false
      encryption_key      = aws_kms_key.autograder.arn
      packaging           = "ZIP"
      path                = "reports"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-test-reports"
  })
}

# ------------------------------------------------------------------------------
# CodeBuild autograder project
# ------------------------------------------------------------------------------

resource "aws_codebuild_project" "autograder" {
  name           = var.project_name
  description    = "Autograder that runs student submissions from GitHub and stores graded results in S3"
  service_role   = aws_iam_role.codebuild_autograder.arn
  build_timeout  = 60
  encryption_key = aws_kms_key.autograder.arn
  source_version = var.github_source_version

  artifacts {
    type                   = "S3"
    location               = aws_s3_bucket.autograder_results.id
    name                   = "${var.project_name}-results"
    path                   = "results"
    packaging              = "NONE"
    namespace_type         = "BUILD_ID"
    encryption_disabled    = false
    override_artifact_name = false
  }

  environment {
    type            = "LINUX_CONTAINER"
    image           = "aws/codebuild/standard:7.0"
    compute_type    = "BUILD_GENERAL1_SMALL"
    privileged_mode = true

    environment_variable {
      name  = "GRADING_TIMEOUT_SECONDS"
      value = tostring(var.grading_timeout_seconds)
    }

    environment_variable {
      name  = "LANGUAGE_RUNTIME"
      value = var.language_runtime
    }

    environment_variable {
      name  = "GRADER_CREDENTIALS"
      type  = "SECRETS_MANAGER"
      value = aws_secretsmanager_secret.grader_credentials.arn
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild.name
      status     = "ENABLED"
    }
  }

  source {
    type            = "GITHUB"
    location        = var.github_repo_url
    git_clone_depth = 1
    buildspec       = <<-BUILD_SPEC
      version: 0.2

      env:
        shell: bash

      phases:
        install:
          runtime-versions:
            python: "3.11"
          commands:
            - echo "Installing grader toolchain for runtime $${LANGUAGE_RUNTIME}"
            - python -m pip install --quiet --upgrade pip
            - python -m pip install --quiet pytest pytest-json-report

        pre_build:
          commands:
            - mkdir -p results reports
            - echo "Requested source version $${CODEBUILD_SOURCE_VERSION}"
            - echo "Resolved commit $${CODEBUILD_RESOLVED_SOURCE_VERSION}"
            - git rev-parse HEAD > results/resolved_commit.txt
            - printf '<?xml version="1.0" encoding="UTF-8"?>\n<testsuite name="autograder" tests="0" failures="0" errors="0"></testsuite>\n' > reports/junit.xml

        build:
          commands:
            - |
              echo "Running student submission under $${LANGUAGE_RUNTIME} (grading budget $${GRADING_TIMEOUT_SECONDS} seconds)"
              set +e
              timeout --signal=KILL "$${GRADING_TIMEOUT_SECONDS}" \
                python -m pytest tests/ \
                  --junitxml=reports/junit.xml \
                  --json-report --json-report-file=results/pytest-report.json \
                  -v > results/pytest-output.log 2>&1
              echo "$$?" > results/pytest_exit_code
              set -e
              echo "Student test execution captured in results/pytest-output.log"

        post_build:
          commands:
            - |
              TEST_EXIT_CODE=$$(cat results/pytest_exit_code)
              date -u +"%Y-%m-%dT%H:%M:%SZ" > results/graded_at.txt
              python -c "import json; status = 'PASSED' if '$${TEST_EXIT_CODE}' == '0' else 'FAILED'; json.dump({'status': status, 'exit_code': int('$${TEST_EXIT_CODE}'), 'source_version': '$${CODEBUILD_SOURCE_VERSION}', 'commit': '$${CODEBUILD_RESOLVED_SOURCE_VERSION}', 'runtime': '$${LANGUAGE_RUNTIME}'}, open('results/grades.json', 'w'), indent=2)"
              echo "Autograder run finished with status $${TEST_EXIT_CODE}"
              cat results/grades.json

      artifacts:
        base-directory: results
        files:
          - '**/*'
        discard-paths: no

      reports:
        "${aws_codebuild_report_group.autograder_tests.arn}":
          files:
            - 'reports/junit.xml'
          file-format: 'JUNITXML'
    BUILD_SPEC
  }

  tags = merge(local.common_tags, {
    Name = var.project_name
  })
}

# ------------------------------------------------------------------------------
# Scheduled (EventBridge) trigger - nightly post-deadline grading batch
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "nightly_grading" {
  name                = "${var.project_name}-nightly-grading"
  description         = "Nightly scheduled autograder run (post-deadline grading batch)"
  schedule_expression = "cron(0 6 * * ? *)"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-nightly-grading"
  })
}

resource "aws_iam_role" "event_start_build" {
  name        = "${var.project_name}-events-role"
  description = "Allows EventBridge to start the autograder CodeBuild project on schedule"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudwatch_event_rule.nightly_grading.arn
          }
        }
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-events-role"
  })
}

resource "aws_iam_role_policy" "event_start_build" {
  name = "${var.project_name}-events-startbuild"
  role = aws_iam_role.event_start_build.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartAutograderBuild"
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
        ]
        Resource = [
          aws_codebuild_project.autograder.arn,
        ]
      },
    ]
  })
}

resource "aws_cloudwatch_event_target" "start_build" {
  rule      = aws_cloudwatch_event_rule.nightly_grading.name
  target_id = "${var.project_name}-start-build"
  arn       = aws_codebuild_project.autograder.arn
  role_arn  = aws_iam_role.event_start_build.arn
}

# ------------------------------------------------------------------------------
# Outputs for downstream grading workflows
# ------------------------------------------------------------------------------

output "results_bucket_name" {
  description = "Name of the S3 bucket storing autograder results."
  value       = aws_s3_bucket.autograder_results.id
}

output "results_bucket_arn" {
  description = "ARN of the S3 bucket storing autograder results."
  value       = aws_s3_bucket.autograder_results.arn
}

output "codebuild_project_name" {
  description = "Name of the CodeBuild project that runs the autograder."
  value       = aws_codebuild_project.autograder.name
}

output "codebuild_project_arn" {
  description = "ARN of the CodeBuild project that runs the autograder."
  value       = aws_codebuild_project.autograder.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables - user-controlled, non-infrastructure inputs only.
# All variables have defaults so terraform apply runs fully unattended.
# ---------------------------------------------------------------------------

variable "github_repo_url" {
  description = "HTTPS clone URL of the GitHub repository containing the class assignments and grading harness."
  type        = string
  default     = "https://github.com/example-org/cs101-autograder.git"
}

variable "course_name" {
  description = "Name of the course this autograder serves (used for tagging and build metadata)."
  type        = string
  default     = "cs101"
}

variable "environment" {
  description = "Deployment environment name (used for tagging)."
  type        = string
  default     = "classroom"
}

variable "build_image" {
  description = "CodeBuild managed image used to execute student code in the grading environment."
  type        = string
  default     = "aws/codebuild/standard:7.0"
}

# ---------------------------------------------------------------------------
# Data sources - static, AWS-managed lookups only.
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_id" "results_bucket_suffix" {
  byte_length = 4
}

# ---------------------------------------------------------------------------
# In-band bootstrap token generator.
# In a fully automated greenfield pipeline there is no out-of-band source for
# a real GitHub PAT, so a random 40-character value (classic PAT shape) is
# generated here and persisted through the Secrets Manager chain. It is
# provider-marked sensitive so it never appears in plan output or logs.
# Rotate the value out-of-band via Secrets Manager before the first real run.
# ---------------------------------------------------------------------------

resource "random_password" "github_bootstrap_token" {
  length  = 40
  special = false
}

locals {
  project_name        = "autograder"
  log_group_name      = "/aws/codebuild/autograder"
  results_bucket_name = "autograder-results-${random_id.results_bucket_suffix.hex}"

  common_tags = {
    Project     = "cs-autograder"
    Course      = var.course_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  buildspec = <<-EOT
    version: 0.2

    phases:
      install:
        commands:
          - echo "Autograder build container started - network egress is restricted to private VPC endpoints only (no internet access)"
      pre_build:
        commands:
          - echo "Preparing offline grading sandbox for course ${var.course_name}"
          - mkdir -p grading-results
          - ls -la
      build:
        commands:
          - echo "Running grading harness for $COURSE_NAME (build $CODEBUILD_BUILD_ID)"
          - |
            if [ -f ./run_autograder.sh ]; then
              bash ./run_autograder.sh > grading-results/results.txt 2>&1 || true
            else
              echo "No run_autograder.sh found in the repository; nothing to grade." > grading-results/error.txt
            fi
          - echo "Grading finished at $(date -u)" >> grading-results/summary.txt
      post_build:
        commands:
          - echo "Uploading grading results to s3://$RESULTS_BUCKET via the S3 gateway VPC endpoint"

    artifacts:
      base-directory: grading-results
      files:
        - "**/*"
  EOT
}

# ---------------------------------------------------------------------------
# Network - isolated VPC with NO internet gateway and NO NAT gateway.
# ---------------------------------------------------------------------------

resource "aws_vpc" "autograder" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "autograder-vpc"
  })
}

resource "aws_subnet" "autograder_private_a" {
  vpc_id                  = aws_vpc.autograder.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "autograder-private-a"
  })
}

resource "aws_subnet" "autograder_private_b" {
  vpc_id                  = aws_vpc.autograder.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "autograder-private-b"
  })
}

# Private route table: only the implicit local VPC route. No internet egress.
resource "aws_route_table" "autograder_private" {
  vpc_id = aws_vpc.autograder.id

  tags = merge(local.common_tags, {
    Name = "autograder-private-route-table"
  })
}

resource "aws_route_table_association" "autograder_private_a" {
  subnet_id      = aws_subnet.autograder_private_a.id
  route_table_id = aws_route_table.autograder_private.id
}

resource "aws_route_table_association" "autograder_private_b" {
  subnet_id      = aws_subnet.autograder_private_b.id
  route_table_id = aws_route_table.autograder_private.id
}

# ---------------------------------------------------------------------------
# Security groups - separate rule resources are used so the CodeBuild and
# endpoint security groups can reference each other without a cycle.
# ---------------------------------------------------------------------------

resource "aws_security_group" "vpc_endpoints" {
  name        = "autograder-vpc-endpoints"
  description = "Allows HTTPS from autograder CodeBuild build containers into the private VPC interface endpoints"
  vpc_id      = aws_vpc.autograder.id

  tags = merge(local.common_tags, {
    Name = "autograder-vpc-endpoints"
  })
}

resource "aws_security_group" "codebuild" {
  name        = "autograder-codebuild"
  description = "Autograder build containers - no inbound access; egress limited to the S3 gateway endpoint, VPC interface endpoints, and VPC DNS"
  vpc_id      = aws_vpc.autograder.id

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild"
  })
}

resource "aws_vpc_security_group_ingress_rule" "endpoints_https_from_codebuild" {
  security_group_id            = aws_security_group.vpc_endpoints.id
  referenced_security_group_id = aws_security_group.codebuild.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  description                  = "HTTPS from autograder build containers to the VPC interface endpoints"

  tags = merge(local.common_tags, {
    Name = "autograder-endpoints-https-from-codebuild"
  })
}

# Egress to S3 is restricted to the prefix list exposed by the S3 Gateway
# endpoint created below - a computed resource attribute, so no prefix-list
# lookup (which is ambiguous across environments) and no hardcoded pl-* ID.
resource "aws_vpc_security_group_egress_rule" "codebuild_https_to_s3_prefix_list" {
  security_group_id = aws_security_group.codebuild.id
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  prefix_list_id    = aws_vpc_endpoint.s3_gateway.prefix_list_id
  description       = "HTTPS to S3 through the gateway VPC endpoint (grading results upload)"

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild-https-s3"
  })
}

resource "aws_vpc_security_group_egress_rule" "codebuild_https_to_endpoints" {
  security_group_id            = aws_security_group.codebuild.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.vpc_endpoints.id
  description                  = "HTTPS to the CodeBuild and CloudWatch Logs interface endpoints"

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild-https-endpoints"
  })
}

resource "aws_vpc_security_group_egress_rule" "codebuild_dns_tcp" {
  security_group_id = aws_security_group.codebuild.id
  ip_protocol       = "tcp"
  from_port         = 53
  to_port           = 53
  cidr_ipv4         = aws_vpc.autograder.cidr_block
  description       = "DNS (TCP) to the VPC resolver"

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild-dns-tcp"
  })
}

resource "aws_vpc_security_group_egress_rule" "codebuild_dns_udp" {
  security_group_id = aws_security_group.codebuild.id
  ip_protocol       = "udp"
  from_port         = 53
  to_port           = 53
  cidr_ipv4         = aws_vpc.autograder.cidr_block
  description       = "DNS (UDP) to the VPC resolver"

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild-dns-udp"
  })
}

# ---------------------------------------------------------------------------
# VPC endpoints - the only paths out of the build network.
# ---------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.autograder.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.autograder_private.id]

  tags = merge(local.common_tags, {
    Name = "autograder-s3-gateway-endpoint"
  })
}

resource "aws_vpc_endpoint" "codebuild" {
  vpc_id              = aws_vpc.autograder.id
  service_name        = "com.amazonaws.us-east-1.codebuild"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.autograder_private_a.id, aws_subnet.autograder_private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild-interface-endpoint"
  })
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.autograder.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.autograder_private_a.id, aws_subnet.autograder_private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "autograder-logs-interface-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Results bucket - stateful grading data.
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "autograder_results" {
  bucket = local.results_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "autograder-results"
  })
}

resource "aws_s3_bucket_public_access_block" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "autograder_results_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.autograder_results.arn,
      "${aws_s3_bucket.autograder_results.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "autograder_results" {
  bucket = aws_s3_bucket.autograder_results.id
  policy = data.aws_iam_policy_document.autograder_results_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.autograder_results]
}

# ---------------------------------------------------------------------------
# CloudWatch Logs for build output.
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "autograder" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

# ---------------------------------------------------------------------------
# CodeBuild service role - least-privilege inline policies.
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "autograder_codebuild" {
  name               = "autograder-codebuild-role"
  description        = "Service role for the offline autograder CodeBuild project"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json

  tags = merge(local.common_tags, {
    Name = "autograder-codebuild-role"
  })
}

data "aws_iam_policy_document" "codebuild_logs" {
  statement {
    sid    = "CodeBuildCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.autograder.arn,
      "${aws_cloudwatch_log_group.autograder.arn}:*",
    ]
  }
}

data "aws_iam_policy_document" "codebuild_s3" {
  statement {
    sid       = "AutograderResultsListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.autograder_results.arn]
  }

  statement {
    sid    = "AutograderResultsReadWriteObjects"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3_bucket.autograder_results.arn}/*"]
  }
}

data "aws_iam_policy_document" "codebuild_vpc" {
  statement {
    sid    = "CodeBuildVpcNetworking"
    effect = "Allow"

    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeVpcs",
    ]

    # These EC2 actions do not support resource-level permissions.
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "autograder_codebuild_logs" {
  name   = "autograder-codebuild-logs"
  role   = aws_iam_role.autograder_codebuild.id
  policy = data.aws_iam_policy_document.codebuild_logs.json
}

resource "aws_iam_role_policy" "autograder_codebuild_s3" {
  name   = "autograder-codebuild-s3-results"
  role   = aws_iam_role.autograder_codebuild.id
  policy = data.aws_iam_policy_document.codebuild_s3.json
}

resource "aws_iam_role_policy" "autograder_codebuild_vpc" {
  name   = "autograder-codebuild-vpc-networking"
  role   = aws_iam_role.autograder_codebuild.id
  policy = data.aws_iam_policy_document.codebuild_vpc.json
}

# ---------------------------------------------------------------------------
# GitHub credentials - generated in-band, stored in Secrets Manager, and
# exposed to CodeBuild only via the Secrets-Manager-backed source credential.
# No plaintext token appears anywhere in this configuration, locals, or
# variable defaults.
# ---------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "github_token" {
  name                    = "autograder/github-access-token"
  description             = "GitHub access token for the autograder CodeBuild project. Terraform writes a generated bootstrap value at apply time; rotate a real GitHub personal access token into this secret out-of-band via Secrets Manager before the first real grading run."
  recovery_window_in_days = 0

  tags = merge(local.common_tags, {
    Name = "autograder-github-access-token"
  })
}

resource "aws_secretsmanager_secret_version" "github_token" {
  secret_id     = aws_secretsmanager_secret.github_token.id
  secret_string = random_password.github_bootstrap_token.result

  # The bootstrap value is written once at apply time. Subsequent applies must
  # never overwrite an out-of-band rotation of the real GitHub PAT.
  lifecycle {
    ignore_changes = [secret_string]
  }
}

resource "aws_codebuild_source_credential" "github" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = aws_secretsmanager_secret_version.github_token.secret_string
}

# ---------------------------------------------------------------------------
# Autograder CodeBuild project - runs fully offline inside the private VPC.
# ---------------------------------------------------------------------------

resource "aws_codebuild_project" "autograder" {
  name          = local.project_name
  description   = "Offline autograder for ${var.course_name} - student code runs in an isolated VPC with no internet access"
  service_role  = aws_iam_role.autograder_codebuild.arn
  build_timeout = 60

  source {
    type                = "GITHUB"
    location            = var.github_repo_url
    buildspec           = local.buildspec
    git_clone_depth     = 1
    report_build_status = false
  }

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.autograder_results.id
    name           = "results"
    path           = "grading-results"
    namespace_type = "BUILD_ID"
    packaging      = "ZIP"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = var.build_image
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = false

    environment_variable {
      name  = "COURSE_NAME"
      value = var.course_name
    }

    environment_variable {
      name  = "RESULTS_BUCKET"
      value = aws_s3_bucket.autograder_results.bucket
    }
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder.id
    subnets            = [aws_subnet.autograder_private_a.id, aws_subnet.autograder_private_b.id]
    security_group_ids = [aws_security_group.codebuild.id]
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.autograder.name
      status     = "ENABLED"
    }
  }

  depends_on = [aws_codebuild_source_credential.github]

  tags = merge(local.common_tags, {
    Name = local.project_name
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "results_bucket_name" {
  description = "Name of the S3 bucket storing grading results."
  value       = aws_s3_bucket.autograder_results.id
}

output "codebuild_project_name" {
  description = "Name of the autograder CodeBuild project."
  value       = aws_codebuild_project.autograder.name
}

output "codebuild_log_group_name" {
  description = "CloudWatch Logs group containing autograder build logs."
  value       = aws_cloudwatch_log_group.autograder.name
}

###############################################################################
# Cat Picture Service
#
# Serverless web service behind a public HTTPS API:
#   POST /cats        -> upload a base64-encoded cat picture (S3 + DynamoDB)
#   GET  /cats/random -> fetch a random cat picture (presigned URL via Lambda)
#
# Architecture: API Gateway (REST) -> Lambda -> S3 (images) + DynamoDB (metadata)
# No VPC / security groups required; all traffic flows through API Gateway.
###############################################################################

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static, well-known provider metadata lookups only (no pre-existing infra).
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Project   = "cat-picture-service"
    ManagedBy = "terraform"
  }

  lambda_zip_path = "${path.module}/cat_service_lambda.zip"

  # Inline Lambda source. The handler routes on the API Gateway proxy event's
  # httpMethod + path to serve both upload (POST /cats) and random-fetch
  # (GET /cats/random) operations.
  lambda_code = <<-PYTHON
    import base64
    import json
    import os
    import random
    import time
    import uuid

    import boto3

    BUCKET_NAME = os.environ["CAT_PICTURES_BUCKET"]
    TABLE_NAME = os.environ["CAT_METADATA_TABLE"]

    s3_client = boto3.client("s3")
    cat_table = boto3.resource("dynamodb").Table(TABLE_NAME)


    def build_response(status_code, body, headers=None, is_base64_encoded=False):
        return {
            "statusCode": status_code,
            "headers": headers or {"Content-Type": "application/json"},
            "isBase64Encoded": is_base64_encoded,
            "body": body,
        }


    def json_response(status_code, payload):
        return build_response(status_code, json.dumps(payload))


    def request_content_type(event):
        headers = event.get("headers") or {}
        for name, value in headers.items():
            if str(name).lower() == "content-type" and value:
                candidate = str(value)
                if candidate.lower().startswith("image/"):
                    return candidate
        return "image/jpeg"


    def extract_image_bytes(event):
        body = event.get("body") or ""
        if not body:
            raise ValueError("empty request body")
        if event.get("isBase64Encoded"):
            decoded = base64.b64decode(body)
            try:
                body = decoded.decode("utf-8")
            except UnicodeDecodeError:
                return decoded
        return base64.b64decode(body)


    def upload_cat(event):
        try:
            image_bytes = extract_image_bytes(event)
        except (ValueError, TypeError):
            return json_response(
                400,
                {"message": "Request body must contain a base64-encoded cat picture."},
            )
        if not image_bytes:
            return json_response(400, {"message": "Request body must not be empty."})

        image_id = str(uuid.uuid4())
        s3_key = f"cat-pictures/{image_id}"
        content_type = request_content_type(event)

        s3_client.put_object(
            Bucket=BUCKET_NAME,
            Key=s3_key,
            Body=image_bytes,
            ContentType=content_type,
        )
        cat_table.put_item(
            Item={
                "ImageId": image_id,
                "S3Key": s3_key,
                "ContentType": content_type,
                "UploadedAt": int(time.time()),
            }
        )
        return json_response(201, {"imageId": image_id, "s3Key": s3_key})


    def random_cat(event):
        items = []
        scan_kwargs = {"ProjectionExpression": "ImageId, S3Key, ContentType"}
        while True:
            result = cat_table.scan(**scan_kwargs)
            items.extend(result.get("Items", []))
            last_evaluated_key = result.get("LastEvaluatedKey")
            if not last_evaluated_key:
                break
            scan_kwargs["ExclusiveStartKey"] = last_evaluated_key

        if not items:
            return json_response(
                404,
                {"message": "No cat pictures available yet. Upload one with POST /cats."},
            )

        chosen = random.choice(items)
        presigned_url = s3_client.generate_presigned_url(
            "get_object",
            Params={"Bucket": BUCKET_NAME, "Key": chosen["S3Key"]},
            ExpiresIn=300,
        )
        return json_response(
            200,
            {
                "imageId": chosen["ImageId"],
                "s3Key": chosen["S3Key"],
                "contentType": chosen.get("ContentType", "image/jpeg"),
                "imageUrl": presigned_url,
            },
        )


    def handler(event, context):
        http_method = (event.get("httpMethod") or "").upper()
        path = event.get("path") or ""
        route = f"{http_method} {path}"

        if route == "POST /cats":
            return upload_cat(event)
        if route == "GET /cats/random":
            return random_cat(event)
        return json_response(404, {"message": f"Unsupported route: {route}"})
  PYTHON
}

###############################################################################
# Lambda deployment package (built locally from the inline source above)
###############################################################################

data "archive_file" "cat_service" {
  type        = "zip"
  output_path = local.lambda_zip_path

  source {
    content  = local.lambda_code
    filename = "main.py"
  }
}

###############################################################################
# IAM: Lambda execution role (trust policy + managed + inline least-privilege)
###############################################################################

resource "aws_iam_role" "cat_service_exec" {
  name = "cat-service-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "cat-service-exec" })
}

resource "aws_iam_role_policy_attachment" "cat_service_basic_execution" {
  role       = aws_iam_role.cat_service_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "cat_service_s3_dynamodb" {
  name = "cat-service-s3-dynamodb"
  role = aws_iam_role.cat_service_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadAndWriteCatPictureObjects"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*",
        ]
      },
      {
        Sid    = "ReadWriteCatMetadata"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Scan",
        ]
        Resource = aws_dynamodb_table.cat_metadata.arn
      }
    ]
  })
}

###############################################################################
# IAM + account setting: allow API Gateway to publish metrics/logs to CloudWatch
###############################################################################

resource "aws_iam_role" "api_gateway_cloudwatch" {
  name = "cat-api-cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "cat-api-cloudwatch" })
}

resource "aws_iam_role_policy_attachment" "api_gateway_cloudwatch_push" {
  role       = aws_iam_role.api_gateway_cloudwatch.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "cat_api" {
  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.api_gateway_cloudwatch_push]
}

###############################################################################
# S3: cat picture storage (private, encrypted, versioned, TLS-only)
###############################################################################

resource "aws_s3_bucket" "cat_pictures" {
  bucket = "${data.aws_caller_identity.current.account_id}-cat-pictures"

  tags = merge(local.common_tags, { Name = "cat-pictures" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# Images are only ever served through the Lambda function (presigned URLs);
# this policy additionally denies any request not made over TLS.
resource "aws_s3_bucket_policy" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.cat_pictures]
}

###############################################################################
# DynamoDB: cat image metadata (ImageId -> S3 key) for random selection
###############################################################################

resource "aws_dynamodb_table" "cat_metadata" {
  name         = "cat-metadata"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "ImageId"

  attribute {
    name = "ImageId"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, { Name = "cat-metadata" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Lambda: cat picture service (upload + random retrieval)
###############################################################################

resource "aws_lambda_function" "cat_service" {
  function_name = "cat-service"
  description   = "Handles cat picture uploads (POST /cats) and random retrieval (GET /cats/random)."
  role          = aws_iam_role.cat_service_exec.arn
  runtime       = "python3.12"
  handler       = "main.handler"
  timeout       = 30
  memory_size   = 256

  filename         = data.archive_file.cat_service.output_path
  source_code_hash = data.archive_file.cat_service.output_base64sha256

  environment {
    variables = {
      CAT_PICTURES_BUCKET = aws_s3_bucket.cat_pictures.bucket
      CAT_METADATA_TABLE  = aws_dynamodb_table.cat_metadata.name
    }
  }

  tags = merge(local.common_tags, { Name = "cat-service" })

  depends_on = [
    aws_iam_role_policy_attachment.cat_service_basic_execution,
    aws_iam_role_policy.cat_service_s3_dynamodb,
  ]
}

resource "aws_lambda_permission" "apigw_invoke" {
  statement_id  = "AllowExecutionFromAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cat_service.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_api.execution_arn}/*/*/cats*"
}

###############################################################################
# API Gateway: public REST API (/cats POST, /cats/random GET)
###############################################################################

resource "aws_api_gateway_rest_api" "cat_api" {
  name        = "cat-api"
  description = "Public HTTPS entrypoint for uploading cat pictures and fetching random cat pictures."

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = merge(local.common_tags, { Name = "cat-api" })
}

resource "aws_api_gateway_resource" "cats" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  parent_id   = aws_api_gateway_rest_api.cat_api.root_resource_id
  path_part   = "cats"
}

resource "aws_api_gateway_resource" "random" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  parent_id   = aws_api_gateway_resource.cats.id
  path_part   = "random"
}

resource "aws_api_gateway_method" "cats_post" {
  rest_api_id   = aws_api_gateway_rest_api.cat_api.id
  resource_id   = aws_api_gateway_resource.cats.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "random_get" {
  rest_api_id   = aws_api_gateway_rest_api.cat_api.id
  resource_id   = aws_api_gateway_resource.random.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "cats_post" {
  rest_api_id             = aws_api_gateway_rest_api.cat_api.id
  resource_id             = aws_api_gateway_resource.cats.id
  http_method             = aws_api_gateway_method.cats_post.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_service.arn}/invocations"
}

resource "aws_api_gateway_integration" "random_get" {
  rest_api_id             = aws_api_gateway_rest_api.cat_api.id
  resource_id             = aws_api_gateway_resource.random.id
  http_method             = aws_api_gateway_method.random_get.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_service.arn}/invocations"
}

resource "aws_api_gateway_deployment" "prod" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_method.cats_post,
      aws_api_gateway_integration.cats_post,
      aws_api_gateway_method.random_get,
      aws_api_gateway_integration.random_get,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.cats_post,
    aws_api_gateway_integration.cats_post,
    aws_api_gateway_method.random_get,
    aws_api_gateway_integration.random_get,
    aws_lambda_permission.apigw_invoke,
  ]
}

resource "aws_api_gateway_stage" "prod" {
  rest_api_id   = aws_api_gateway_rest_api.cat_api.id
  deployment_id = aws_api_gateway_deployment.prod.id
  stage_name    = "prod"
  description   = "Production stage for the cat picture service."

  tags = merge(local.common_tags, { Name = "cat-api-prod" })
}

# Stage-level metrics and throttling (applies to every method on the stage) to
# limit abuse of this public API.
resource "aws_api_gateway_method_settings" "prod_all" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  stage_name  = aws_api_gateway_stage.prod.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled        = true
    throttling_burst_limit = 100
    throttling_rate_limit  = 50
  }

  depends_on = [aws_api_gateway_account.cat_api]
}

###############################################################################
# Outputs
###############################################################################

output "api_invoke_url" {
  description = "Base invoke URL of the prod stage of the cat picture API."
  value       = aws_api_gateway_stage.prod.invoke_url
}

output "upload_cat_picture_url" {
  description = "Full URL for uploading a base64-encoded cat picture (POST)."
  value       = "${aws_api_gateway_stage.prod.invoke_url}/cats"
}

output "random_cat_picture_url" {
  description = "Full URL for retrieving a random cat picture (GET)."
  value       = "${aws_api_gateway_stage.prod.invoke_url}/cats/random"
}

output "cat_pictures_bucket_name" {
  description = "Name of the S3 bucket storing cat pictures."
  value       = aws_s3_bucket.cat_pictures.bucket
}

output "cat_metadata_table_name" {
  description = "Name of the DynamoDB table storing cat picture metadata."
  value       = aws_dynamodb_table.cat_metadata.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resources as a tag."
  type        = string
  default     = "production"
}

variable "management_cidr" {
  description = "Single management CIDR permitted to reach the EC2 instance on TCP/22."
  type        = string
  default     = "10.0.0.0/8"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "backup_vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "backup_internet_gateway"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "backup_public_subnet"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "backup_public_route_table"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "main" {
  key_name   = "backup_ec2_key_pair"
  public_key = tls_private_key.main.public_key_openssh

  tags = {
    Name        = "backup_ec2_key_pair"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name        = "backup/ec2/ssh-private-key"
  description = "SSH private key material for the backup EC2 instance key pair."

  tags = {
    Name        = "backup_ssh_private_key"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.main.private_key_pem
}

resource "aws_security_group" "instance" {
  name        = "backup_instance_sg"
  description = "Restricts inbound access to the backed-up EC2 instance."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the management CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.management_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "backup_instance_security_group"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2" {
  name               = "backup_ec2_instance_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name        = "backup_ec2_instance_role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "backup_ec2_instance_profile"
  role = aws_iam_role.ec2.name
}

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the AWS Backup vault."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "backup_vault_kms_key"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "backup_service_role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name        = "backup_service_role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "backup_backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

data "aws_iam_policy_document" "backup_kms_access" {
  statement {
    sid    = "AllowBackupKmsOperationsOnVaultKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey"
    ]

    resources = [aws_kms_key.backup.arn]
  }
}

resource "aws_iam_role_policy" "backup_kms_access" {
  name   = "backup_kms_access"
  role   = aws_iam_role.backup.name
  policy = data.aws_iam_policy_document.backup_kms_access.json
}

resource "aws_backup_vault" "main" {
  name        = "backup_vault_daily"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name        = "backup_vault_daily"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "daily" {
  name = "daily_midnight_backup_plan"

  rule {
    rule_name         = "daily_midnight"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 0 * * ? *)"
    start_window      = 60
    completion_window = 120

    lifecycle {
      delete_after = 7
    }
  }

  tags = {
    Name        = "daily_midnight_backup_plan"
    Environment = var.environment
  }
}

resource "aws_backup_selection" "backup_enabled" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "backup_enabled_selection"
  plan_id      = aws_backup_plan.daily.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "BackupEnabled"
    value = "true"
  }
}

resource "aws_instance" "backup_instance" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  key_name                    = aws_key_pair.main.key_name
  associate_public_ip_address = true
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  tags = {
    Name          = "backup_ec2_instance"
    Environment   = var.environment
    BackupEnabled = "true"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "environment must be a non-empty string."
  }
}

locals {
  # Single source of truth for the Lambda function name so the function and
  # its pre-created CloudWatch log group always share the same name.
  lambda_function_name = "daily-scheduled-job-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Purpose     = "daily-scheduled-job"
  }
}

data "aws_partition" "current" {}

# Self-contained function code: a minimal python3.12 handler that logs the
# incoming event so every daily run is verifiable in CloudWatch Logs.
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/daily_job_lambda.zip"

  source_content = <<-EOT
    import json


    def lambda_handler(event, context):
        """Daily scheduled job handler, triggered every day at 07:00 UTC by EventBridge."""
        print("Daily job started: triggered by EventBridge schedule cron(0 7 * * ? *).")
        print("Received event: " + json.dumps(event, default=str))
        print("Daily job finished successfully.")
        return {
            "statusCode": 200,
            "body": json.dumps({"message": "daily job completed successfully"}),
        }
    EOT

  source_content_filename = "lambda_function.py"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "daily-job-lambda-exec-${var.environment}"
  description        = "Execution role for the daily scheduled job Lambda function."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Pre-created log group matching the Lambda function's default log location
# ("/aws/lambda/<function_name>") with a 14 day retention window.
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.lambda_function_name}"
  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_lambda_function" "daily_job" {
  function_name    = local.lambda_function_name
  description      = "Runs the daily scheduled job, triggered by EventBridge at 07:00 UTC every day."
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  memory_size      = 128
  timeout          = 30

  depends_on = [
    aws_cloudwatch_log_group.lambda_logs,
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]

  tags = local.common_tags
}

# Least-privilege invoke authorization, scoped to this specific rule only.
resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromDailyScheduleRule"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_0700_utc.arn
}

resource "aws_cloudwatch_event_rule" "daily_0700_utc" {
  name                = "daily-0700-utc-${var.environment}"
  description         = "Triggers the daily job Lambda function every day at 07:00 UTC."
  schedule_expression = "cron(0 7 * * ? *)"
  state               = "ENABLED"

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "lambda_daily_job" {
  rule      = aws_cloudwatch_event_rule.daily_0700_utc.name
  arn       = aws_lambda_function.daily_job.arn
  target_id = "daily-job-lambda"
}

output "lambda_function_name" {
  description = "Name of the Lambda function invoked daily by the EventBridge schedule."
  value       = aws_lambda_function.daily_job.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function invoked daily by the EventBridge schedule."
  value       = aws_lambda_function.daily_job.arn
}

output "eventbridge_rule_arn" {
  description = "ARN of the EventBridge rule that schedules the daily 07:00 UTC run."
  value       = aws_cloudwatch_event_rule.daily_0700_utc.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "production"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources"
  type        = map(string)
  default     = {}
}

variable "geo_restriction_type" {
  description = "CloudFront geo restriction type. One of: none, whitelist, blacklist"
  type        = string
  default     = "none"

  validation {
    condition     = contains(["none", "whitelist", "blacklist"], var.geo_restriction_type)
    error_message = "geo_restriction_type must be one of: none, whitelist, blacklist."
  }
}

variable "geo_restriction_countries" {
  description = "ISO 3166-1 alpha-2 country codes for whitelisting/blacklisting. Ignored when geo_restriction_type is none."
  type        = list(string)
  default     = []
}

locals {
  s3_origin_id = "s3-video-content-origin"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

# -----------------------------------------------------------------------------
# S3 Origin Bucket (private video content)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "video_content" {
  tags = merge(local.common_tags, { Name = "video-content-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    id     = "video-media-cost-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "INTELLIGENT_TIERING"
    }

    noncurrent_version_expiration {
      noncurrent_days = 180
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# -----------------------------------------------------------------------------
# S3 Log Bucket (CloudFront standard access logs)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudfront_logs" {
  tags = merge(local.common_tags, { Name = "cloudfront-logs-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }

  depends_on = [aws_s3_bucket_public_access_block.cloudfront_logs]
}

# -----------------------------------------------------------------------------
# CloudFront Origin Access Control (OAC)
# -----------------------------------------------------------------------------

resource "aws_cloudfront_origin_access_control" "s3_oac" {
  name                              = "video-content-oac-${var.environment}"
  description                       = "Origin Access Control for the private video content S3 origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# -----------------------------------------------------------------------------
# CloudFront Cache Policy tuned for large video media
# -----------------------------------------------------------------------------

resource "aws_cloudfront_cache_policy" "video_streaming" {
  name        = "video-streaming-cache-${var.environment}"
  comment     = "Long-TTL cache policy for pre-compressed video media; forwards Origin header for CORS and all query strings for cache-busting/versioned URLs"
  min_ttl     = 0
  default_ttl = 86400
  max_ttl     = 31536000

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }

    headers_config {
      header_behavior = "whitelist"
      headers {
        items = ["Origin"]
      }
    }

    query_strings_config {
      query_string_behavior = "all"
    }
  }
}

# -----------------------------------------------------------------------------
# CloudFront Distribution
# -----------------------------------------------------------------------------

resource "aws_cloudfront_distribution" "video_cdn" {
  enabled         = true
  is_ipv6_enabled = true
  http_version    = "http2and3"
  comment         = "Global video streaming CDN (${var.environment})"
  price_class     = "PriceClass_All"

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_id                = local.s3_origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_oac.id

    origin_shield {
      enabled = false
    }
  }

  default_cache_behavior {
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]

    cache_policy_id = aws_cloudfront_cache_policy.video_streaming.id

    # Video payloads are pre-compressed; no edge compression needed.
    compress = false
  }

  restrictions {
    geo_restriction {
      restriction_type = var.geo_restriction_type
      locations        = var.geo_restriction_countries
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  logging_config {
    include_cookies = false
    bucket          = aws_s3_bucket.cloudfront_logs.bucket_regional_domain_name
    prefix          = "cloudfront-logs/"
  }

  tags = merge(local.common_tags, { Name = "video-cdn-${var.environment}" })

  depends_on = [aws_s3_bucket_ownership_controls.cloudfront_logs]
}

# -----------------------------------------------------------------------------
# Bucket Policies (least privilege, scoped to this distribution only)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "video_content_policy" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontOACGetObject"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.video_content.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_cdn.arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_policy" "cloudfront_logs_policy" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontLogDelivery"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudfront_logs.arn}/cloudfront-logs/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_cdn.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cloudfront_domain_name" {
  description = "CloudFront distribution domain name to use for video playback URLs"
  value       = aws_cloudfront_distribution.video_cdn.domain_name
}

output "cloudfront_distribution_arn" {
  description = "ARN of the CloudFront video distribution"
  value       = aws_cloudfront_distribution.video_cdn.arn
}

output "video_content_bucket_name" {
  description = "Name of the private S3 origin bucket for video assets"
  value       = aws_s3_bucket.video_content.bucket
}

output "video_content_bucket_id" {
  description = "ID of the private S3 origin bucket for video assets"
  value       = aws_s3_bucket.video_content.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resource names and tags."
  type        = string
  default     = "prod"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "environment must be a non-empty string."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "video-streaming"
    ManagedBy   = "terraform"
  }

  asg_tags = merge(local.common_tags, {
    Name = "${var.environment}-video-server"
  })

  video_server_user_data = <<-EOS
    #!/bin/bash
    set -euo pipefail

    dnf install -y nginx

    cat > /usr/share/nginx/html/index.html <<'HTML'
    <!DOCTYPE html>
    <html>
      <head>
        <title>Video Streaming Service</title>
      </head>
      <body>
        <h1>Video Streaming Service</h1>
        <video controls width="960">
          <source src="/media/sample.mp4" type="video/mp4" />
          Your browser does not support HTML5 video.
        </video>
      </body>
    </html>
    HTML

    mkdir -p /usr/share/nginx/html/media
    aws s3 sync "s3://${aws_s3_bucket.video_content.bucket}/media/" /usr/share/nginx/html/media/ || true

    systemctl enable --now nginx
  EOS
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_elb_service_account" "main" {}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-streaming-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-streaming-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-gateway"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "${var.environment}-alb-sg"
  description = "Internet-facing ALB. Ingress limited to HTTP/HTTPS from the internet."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-alb-sg"
  })
}

resource "aws_vpc_security_group_egress_rule" "alb_to_video_servers" {
  security_group_id            = aws_security_group.alb.id
  referenced_security_group_id = aws_security_group.video_servers.id
  ip_protocol                  = "tcp"
  from_port                    = 80
  to_port                      = 80
  description                  = "ALB egress limited to the streaming-server security group"
}

resource "aws_security_group" "video_servers" {
  name        = "${var.environment}-video-servers-sg"
  description = "Streaming server tier. Ingress only from the ALB on the streaming port."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Streaming traffic from the ALB only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "HTTPS to the internet through the NAT gateway for package retrieval"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTP to the internet through the NAT gateway for package retrieval"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-servers-sg"
  })
}

resource "aws_s3_bucket" "video_content" {
  bucket = "${var.environment}-video-content-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-content"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.video_content.arn,
          "${aws_s3_bucket.video_content.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.video_content]
}

resource "aws_s3_bucket" "alb_logs" {
  bucket = "${var.environment}-alb-logs-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-alb-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDeliveryPutObject"
        Effect    = "Allow"
        Principal = { AWS = data.aws_elb_service_account.main.arn }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.alb_logs.arn}/alb-logs/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
      },
      {
        Sid       = "ELBLogDeliveryBucketCheck"
        Effect    = "Allow"
        Principal = { AWS = data.aws_elb_service_account.main.arn }
        Action    = "s3:GetBucketLocation"
        Resource  = aws_s3_bucket.alb_logs.arn
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.alb_logs.arn,
          "${aws_s3_bucket.alb_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

resource "aws_iam_role" "video_server_role" {
  name = "${var.environment}-video-server-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2ToAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-server-role"
  })
}

resource "aws_iam_policy" "video_content_read" {
  name        = "${var.environment}-video-content-read"
  description = "Least-privilege read access to the video content bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListVideoContentBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.video_content.arn
      },
      {
        Sid      = "ReadVideoContentObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.video_content.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "video_server_video_content_read" {
  role       = aws_iam_role.video_server_role.name
  policy_arn = aws_iam_policy.video_content_read.arn
}

resource "aws_iam_instance_profile" "video_server_profile" {
  name = "${var.environment}-video-server-profile"
  role = aws_iam_role.video_server_role.name
}

resource "aws_launch_template" "video_server" {
  name_prefix   = "${var.environment}-video-server-"
  description   = "Launch template for nginx-based video streaming servers"
  image_id      = data.aws_ami.al2023.id
  instance_type = "t3.medium"

  iam_instance_profile {
    name = aws_iam_instance_profile.video_server_profile.name
  }

  vpc_security_group_ids = [aws_security_group.video_servers.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  monitoring {
    enabled = true
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 20
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  user_data = base64encode(local.video_server_user_data)

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "${var.environment}-video-server"
    })
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_target_group" "video_tg" {
  name        = "${var.environment}-video-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-tg"
  })
}

resource "aws_lb" "video_streaming" {
  name               = "${var.environment}-video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = "alb-logs"
    enabled = true
  }

  depends_on = [aws_s3_bucket_policy.alb_logs]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-streaming-alb"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.video_streaming.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_tg.arn
  }
}

resource "aws_autoscaling_group" "video_servers" {
  name                = "${var.environment}-video-servers-asg"
  vpc_zone_identifier = aws_subnet.private[*].id
  target_group_arns   = [aws_lb_target_group.video_tg.arn]
  health_check_type   = "ELB"

  min_size         = 2
  desired_capacity = 2
  max_size         = 6

  health_check_grace_period = 300

  launch_template {
    id      = aws_launch_template.video_server.id
    version = "$Latest"
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 50
    }
  }

  dynamic "tag" {
    for_each = local.asg_tags

    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }
}

resource "aws_autoscaling_policy" "video_servers_cpu_target" {
  name                   = "${var.environment}-video-servers-cpu-target"
  autoscaling_group_name = aws_autoscaling_group.video_servers.name
  policy_type            = "TargetTrackingScaling"

  target_tracking_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ASGAverageCPUUtilization"
    }

    target_value = 60
  }
}

output "streaming_endpoint" {
  description = "Public DNS name of the video streaming Application Load Balancer."
  value       = aws_lb.video_streaming.dns_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_username = "dbadmin"

  common_tags = {
    ManagedBy = "terraform"
    Component = "rds-postgres"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Generated unique suffix for the database identifier
resource "random_id" "db" {
  byte_length = 8
}

# Generated master password (never hardcoded, never output)
resource "random_password" "master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  numeric          = true
  upper            = true
  lower            = true

  min_special = 1
  min_numeric = 1
  min_upper   = 1
  min_lower   = 1
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    { Name = "rds-vpc" },
  )
}

resource "aws_subnet" "db" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.common_tags,
    { Name = "rds-subnet-${count.index + 1}" },
  )
}

resource "aws_db_subnet_group" "db" {
  name       = "rds-db-subnet-group"
  subnet_ids = aws_subnet.db[*].id

  tags = local.common_tags
}

resource "aws_security_group" "db" {
  name        = "rds-db-sg"
  description = "Allow PostgreSQL access from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    { Name = "rds-db-sg" },
  )
}

resource "aws_secretsmanager_secret" "db" {
  name        = "rds/master-${random_id.db.hex}"
  description = "Master credentials for the rds-${random_id.db.hex} PostgreSQL instance"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.master.result
  })
}

resource "aws_db_instance" "db" {
  identifier     = "rds-${random_id.db.hex}"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_encrypted = true

  db_name  = "appdb"
  username = local.db_username
  password = random_password.master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.db.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false
  multi_az               = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "rds-${random_id.db.hex}-final"

  tags = merge(
    local.common_tags,
    { Name = "rds-${random_id.db.hex}" },
  )

  lifecycle {
    prevent_destroy = true
  }
}

output "rds_endpoint_address" {
  description = "Connection address of the RDS PostgreSQL instance"
  value       = aws_db_instance.db.address
}

output "secrets_manager_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the master credentials"
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Project     = "dolphinscheduler"
    ManagedBy   = "terraform"
    Environment = "production"
  }

  db_username = "dolphinscheduler_admin"
}

# ------------------------------------------------------------------
# Networking: VPC, Internet Gateway, Public Route Table, Subnets
# ------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-public-rt"
    }
  )
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-public-subnet-a"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-public-subnet-b"
    }
  )
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------
# Security Group for Database Access
# ------------------------------------------------------------------

resource "aws_security_group" "db" {
  name        = "dolphinscheduler-db-sg"
  description = "Security group for the Dolphinscheduler PostgreSQL database - restricts access to TCP 5432 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic back to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-db-sg"
    }
  )
}

# ------------------------------------------------------------------
# Master Credentials in Secrets Manager
# ------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "dolphinscheduler-db-master-credentials"
  description = "Master credentials for the Dolphinscheduler PostgreSQL database"

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-db-master-credentials"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

# ------------------------------------------------------------------
# RDS Subnet Group (requires subnets in at least two AZs)
# ------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "dolphinscheduler-db-subnet-group"
  description = "Subnet group for the Dolphinscheduler PostgreSQL database"

  subnet_ids = [
    aws_subnet.public_a.id,
    aws_subnet.public_b.id,
  ]

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-db-subnet-group"
    }
  )
}

# ------------------------------------------------------------------
# PostgreSQL Database Instance
# ------------------------------------------------------------------

resource "aws_db_instance" "dolphinscheduler" {
  identifier     = "dolphinscheduler"
  engine         = "postgres"
  engine_version = "17.1"
  instance_class = "db.t3.micro"

  allocated_storage = 5
  storage_encrypted = true

  db_name  = "dolphinscheduler"
  username = jsondecode(aws_secretsmanager_secret_version.db.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  auto_minor_version_upgrade = false
  backup_retention_period    = 7

  skip_final_snapshot = true

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_identifier   = "secure-postgres-db"
  db_name         = "appdb"
  master_username = "postgresadmin"

  common_tags = {
    Project     = "secure-postgres"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "postgres-vpc"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "postgres-private"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "postgres-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "postgres-private-b"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security group
# ---------------------------------------------------------------------------

resource "aws_security_group" "postgres" {
  name        = "secure-postgres-sg"
  description = "Allow PostgreSQL (TCP 5432) only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "secure-postgres-sg"
  })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "postgres" {
  description             = "KMS key for PostgreSQL RDS storage and Secrets Manager encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "postgres-db-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "postgres" {
  name          = "alias/postgres-db"
  target_key_id = aws_kms_key.postgres.arn
}

# ---------------------------------------------------------------------------
# Master credentials (generated, stored in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "postgres_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "postgres_master" {
  name                    = "rds/${local.db_identifier}/master"
  description             = "Master credentials for the ${local.db_identifier} PostgreSQL instance"
  kms_key_id              = aws_kms_key.postgres.arn
  recovery_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-master-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "postgres_master" {
  secret_id = aws_secretsmanager_secret.postgres_master.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = local.db_name
    username = local.master_username
    password = random_password.postgres_master.result
  })
}

# ---------------------------------------------------------------------------
# RDS
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "postgres" {
  name_prefix = "secure-postgres15-"
  family      = "postgres15"
  description = "Custom parameters for PostgreSQL 15"

  parameter {
    name         = "max_connections"
    value        = "100"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "shared_buffers"
    value        = "32768"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_db_subnet_group" "main" {
  name        = "secure-postgres-subnets"
  description = "Private subnets for the secure PostgreSQL RDS instance"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "secure-postgres-subnets"
  })
}

resource "random_id" "snapshot_suffix" {
  byte_length = 4
}

resource "aws_db_instance" "postgres" {
  identifier     = local.db_identifier
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  db_name               = local.db_name
  username              = local.master_username
  password              = random_password.postgres_master.result
  port                  = 5432

  multi_az               = true
  publicly_accessible    = false
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.postgres.arn
  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.postgres.name
  vpc_security_group_ids = [aws_security_group.postgres.id]

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"

  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-${random_id.snapshot_suffix.hex}"

  auto_minor_version_upgrade      = true
  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Variables
#------------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used as the Name tag prefix across all resources."
  type        = string
  default     = "airbyte-connector-tests"
}

variable "environment" {
  description = "Environment name applied to the Environment tag of every resource."
  type        = string
  default     = "dev"
}

variable "instance_class" {
  description = "RDS instance class for the PostgreSQL instance."
  type        = string
  default     = "db.t3.micro"
}

variable "master_username" {
  description = "Master username for the RDS PostgreSQL instance."
  type        = string
  default     = "airbyte_admin"

  validation {
    condition     = can(regex("^[a-zA-Z][a-zA-Z0-9_]{0,62}$", var.master_username))
    error_message = "Master username must start with a letter and contain only letters, digits, or underscores (max 63 characters)."
  }
}

variable "admin_cidr" {
  description = "Trusted admin CIDR (office/VPN range) allowed to connect to PostgreSQL on port 5432."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = var.admin_cidr != "0.0.0.0/0" && var.admin_cidr != "::/0" && can(cidrnetmask(var.admin_cidr))
    error_message = "admin_cidr must be a valid, restrictive IPv4 CIDR block; 0.0.0.0/0 is not permitted."
  }
}

#------------------------------------------------------------------------------
# Locals
#------------------------------------------------------------------------------

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

#------------------------------------------------------------------------------
# Static provider metadata: available AZs
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Networking: dedicated VPC, public subnets, internet gateway, routing
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

#------------------------------------------------------------------------------
# RDS subnet group (public subnets, required for a publicly accessible DB)
#------------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-db-subnet-group"
  })
}

#------------------------------------------------------------------------------
# Security group: PostgreSQL ingress restricted to the trusted admin CIDR only
#------------------------------------------------------------------------------

resource "aws_security_group" "postgres" {
  name        = "${var.project_name}-postgres-sg"
  description = "PostgreSQL access for the Airbyte connector test RDS instance (restricted ingress)."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from trusted admin CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-postgres-sg"
  })
}

#------------------------------------------------------------------------------
# Master credentials: generated password stored in Secrets Manager
#------------------------------------------------------------------------------

resource "random_password" "master" {
  length           = 24
  special          = true
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${var.project_name}-db-master-credentials"
  description = "Master credentials for the Airbyte connector test PostgreSQL instance."

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-db-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.master.result
    engine   = aws_db_instance.main.engine
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
  })
}

#------------------------------------------------------------------------------
# RDS PostgreSQL 15 instance (dev/test lifecycle, RDS-managed defaults)
#------------------------------------------------------------------------------

resource "aws_db_instance" "main" {
  identifier     = "${var.project_name}-postgres"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "airbyte"
  username = var.master_username
  password = random_password.master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  publicly_accessible    = true
  multi_az               = false

  auto_minor_version_upgrade = true
  apply_immediately          = true
  backup_retention_period    = 1
  skip_final_snapshot        = true
  deletion_protection        = false
  copy_tags_to_snapshot      = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-postgres"
  })

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Outputs for the Airbyte test harness (no secret values are ever emitted)
#------------------------------------------------------------------------------

output "rds_endpoint_address" {
  description = "RDS PostgreSQL endpoint address."
  value       = aws_db_instance.main.address
}

output "rds_port" {
  description = "RDS PostgreSQL listening port."
  value       = aws_db_instance.main.port
}

output "rds_database_name" {
  description = "Initial database name on the RDS PostgreSQL instance."
  value       = aws_db_instance.main.db_name
}

output "rds_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (retrieve the value via AWS SDK/CLI only)."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "allowed_db_cidr_blocks" {
  description = "CIDR blocks explicitly allowed to reach MySQL on port 3306. Never set to 0.0.0.0/0."
  type        = list(string)
  default     = ["10.0.0.0/16"]

  validation {
    condition     = alltrue([for cidr in var.allowed_db_cidr_blocks : cidr != "0.0.0.0/0" && cidr != "::/0"])
    error_message = "Open ingress (0.0.0.0/0 or ::/0) is not permitted for the database security group."
  }
}

locals {
  name_prefix   = "main"
  db_identifier = "${local.name_prefix}-mysql-db"
  db_username   = "dbadmin"
  db_name       = "appdb"
  db_port       = 3306

  common_tags = {
    ManagedBy   = "terraform"
    Project     = "mysql-rds"
    Environment = "greenfield"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-0" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-1" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict MySQL (3306) ingress to explicitly approved CIDR blocks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from approved CIDR blocks"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = var.allowed_db_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-sg" })
}

resource "random_password" "db" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_creds" {
  name        = "${local.name_prefix}/rds/${local.db_identifier}/master-credentials"
  description = "Master credentials for the ${local.db_identifier} MySQL instance"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-creds" })
}

resource "aws_secretsmanager_secret_version" "db_creds" {
  secret_id = aws_secretsmanager_secret.db_creds.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db.result
    engine   = "mysql"
    port     = aws_db_instance.main.port
    host     = aws_db_instance.main.address
    dbname   = local.db_name
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "DB subnet group spanning two AZs for ${local.db_identifier}"
  subnet_ids  = [aws_subnet.public_0.id, aws_subnet.public_1.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_db_instance" "main" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "5.7"
  instance_class = "db.t3.micro"

  allocated_storage = 10
  storage_type      = "gp2"
  storage_encrypted = true

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = local.db_identifier })
}

output "rds_endpoint" {
  description = "Connection endpoint (host:port) of the MySQL RDS instance"
  value       = aws_db_instance.main.endpoint
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials"
  value       = aws_secretsmanager_secret.db_creds.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata only (greenfield-safe lookup)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "db_master_username" {
  description = "Master username for the RDS MySQL 5.7 instance (never 'admin' or 'root')."
  type        = string
  default     = "dbadmin"
}

variable "allowed_admin_cidr_blocks" {
  description = "CIDR blocks allowed to connect to the database on TCP 3306. Defaults to 0.0.0.0/0 because the user explicitly requested a publicly accessible RDS instance; scope this down to an admin CIDR in real deployments."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  db_identifier = "mysql57-${var.environment}-db"

  common_tags = {
    Environment = var.environment
    Project     = "rds-mysql-5-7"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Network foundation (greenfield: created from scratch)
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-public-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# RDS subnet group (references only subnets created in this configuration)
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "rds" {
  name       = "mysql57-${var.environment}-db-subnet-group"
  subnet_ids = [aws_subnet.public[0].id, aws_subnet.public[1].id]

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-db-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Security group: ingress restricted to TCP 3306 only
# ---------------------------------------------------------------------------
resource "aws_security_group" "rds_public" {
  name        = "mysql57-${var.environment}-rds-sg"
  description = "Public access to the RDS MySQL instance on TCP 3306 only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from allowed CIDR blocks (default 0.0.0.0/0 per public-access requirement)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_admin_cidr_blocks
  }

  egress {
    description = "Outbound MySQL to the VPC CIDR only (replication/diagnostics)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-rds-sg"
  })
}

# ---------------------------------------------------------------------------
# Randomly generated master password (never plaintext in config)
# ---------------------------------------------------------------------------
resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?" # excludes '/', '@', '"' and space (RDS-restricted characters)
}

# ---------------------------------------------------------------------------
# Secrets Manager storage for the master password
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "db" {
  name                    = "rds/mysql57/${var.environment}/master-password"
  description             = "Master password for the ${local.db_identifier} RDS MySQL instance"
  recovery_window_in_days = 7

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id     = aws_secretsmanager_secret.db.id
  secret_string = random_password.db_master_password.result
}

# ---------------------------------------------------------------------------
# RDS MySQL 5.7 instance: 200 GB gp3, db.t3.micro, publicly accessible
# ---------------------------------------------------------------------------
resource "aws_db_instance" "mysql_db" {
  identifier = local.db_identifier

  engine                  = "mysql"
  engine_version          = "5.7.44"
  instance_class          = "db.t3.micro"
  allocated_storage       = 200
  max_allocated_storage   = 250
  storage_type            = "gp3"
  storage_encrypted       = true
  port                    = 3306
  publicly_accessible     = true
  multi_az                = false
  auto_minor_version_upgrade = true

  db_name                = null
  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds_public.id]

  username = var.db_master_username
  password = random_password.db_master_password.result

  deletion_protection     = true
  backup_retention_period = 7
  copy_tags_to_snapshot   = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-snapshot"

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (password value is never exposed; only the secret ARN)
# ---------------------------------------------------------------------------
output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the RDS MySQL 5.7 instance."
  value       = aws_db_instance.mysql_db.endpoint
}

output "db_instance_address" {
  description = "Hostname of the RDS MySQL 5.7 instance."
  value       = aws_db_instance.mysql_db.address
}

output "db_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master password."
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment label applied as a tag to all resources."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "app-postgres-db"
  db_username = "app_admin"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking: custom VPC, private subnets across two AZs, DB subnet group
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-1"
  })
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-2"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "DB subnet group for the ${local.name_prefix} PostgreSQL instance"
  subnet_ids  = [aws_subnet.private_1.id, aws_subnet.private_2.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Database security group: ingress restricted to TCP 5432 from the VPC only
# ---------------------------------------------------------------------------

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict PostgreSQL ingress to TCP 5432 from the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# ---------------------------------------------------------------------------
# Master credentials: generated password stored in Secrets Manager
# ---------------------------------------------------------------------------

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.name_prefix}-credentials"
  description = "Master credentials for the ${local.name_prefix} PostgreSQL instance"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master_password.result
  })
}

# ---------------------------------------------------------------------------
# PostgreSQL RDS instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "main" {
  identifier     = local.name_prefix
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  allocated_storage     = 5
  max_allocated_storage = 50
  storage_type          = "gp3"

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  username = local.db_username
  password = random_password.db_master_password.result

  multi_az                   = false
  storage_encrypted          = true
  deletion_protection        = true
  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  maintenance_window         = "Mon:00:00-Mon:03:00"
  copy_tags_to_snapshot      = true

  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"

  tags = merge(local.common_tags, {
    Name                       = local.name_prefix
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_credentials.arn
  })

  depends_on = [aws_secretsmanager_secret_version.db_credentials]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  option_group_name = "option-group-pike"
  audit_bucket_name = "option-group-pike-audit-logs"
  audit_role_name   = "rds-sqlserver-audit-role"
  audit_policy_name = "rds-sqlserver-audit-s3-policy"

  common_tags = {
    Project   = "rds-sqlserver-ee-option-group"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# S3 bucket that receives SQL Server audit logs (stateful: prevent_destroy)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "audit_logs" {
  bucket = local.audit_bucket_name

  tags = merge(
    local.common_tags,
    {
      Name = local.audit_bucket_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Deny any request to the bucket or its objects that is not made over TLS.
# Actions are explicitly enumerated (no wildcard principal combined with a
# wildcard action).
resource "aws_s3_bucket_policy" "audit_logs_tls_only" {
  bucket = aws_s3_bucket.audit_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:DeleteObject",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListMultipartUploadParts",
          "s3:PutObject",
        ]
        Resource = [
          aws_s3_bucket.audit_logs.arn,
          "${aws_s3_bucket.audit_logs.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.audit_logs,
    aws_s3_bucket_server_side_encryption_configuration.audit_logs,
    aws_s3_bucket_versioning.audit_logs,
  ]
}

# -----------------------------------------------------------------------------
# IAM role trusted by RDS for SQLSERVER_AUDIT, plus least-privilege S3 policy
# -----------------------------------------------------------------------------
resource "aws_iam_role" "rds_sqlserver_audit" {
  name = local.audit_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRdsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = local.audit_role_name
    },
  )
}

resource "aws_iam_policy" "rds_sqlserver_audit_s3" {
  name        = local.audit_policy_name
  description = "Least-privilege S3 access for RDS SQL Server audit log delivery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PutAuditLogObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.audit_logs.arn}/*"]
      },
      {
        Sid      = "ListAuditLogBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.audit_logs.arn]
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = local.audit_policy_name
    },
  )
}

resource "aws_iam_role_policy_attachment" "rds_sqlserver_audit_s3" {
  role       = aws_iam_role.rds_sqlserver_audit.name
  policy_arn = aws_iam_policy.rds_sqlserver_audit_s3.arn
}

# -----------------------------------------------------------------------------
# RDS option group for SQL Server EE (major version 11 -> "11.00")
# -----------------------------------------------------------------------------
resource "aws_db_option_group" "option_group_pike" {
  name                     = local.option_group_name
  option_group_description = "SQL Server EE option group with TDE and S3 audit logging"
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  option {
    option_name = "TDE"
  }

  option {
    option_name = "SQLSERVER_AUDIT"

    option_settings {
      name  = "IAM_ROLE_ARN"
      value = aws_iam_role.rds_sqlserver_audit.arn
    }

    option_settings {
      name  = "S3_BUCKET_ARN"
      value = aws_s3_bucket.audit_logs.arn
    }
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.option_group_name
    },
  )

  depends_on = [
    aws_iam_role_policy_attachment.rds_sqlserver_audit_s3,
    aws_s3_bucket_policy.audit_logs_tls_only,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# User-controlled variables (no credentials, IDs, or infrastructure attributes)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Short name used to prefix and tag all resources (lowercase letters, digits, hyphens)."
  type        = string
  default     = "aurora-proxy"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,61}[a-z0-9]$", var.project_name))
    error_message = "project_name must be 3-63 lowercase alphanumeric characters or hyphens, starting with a letter."
  }
}

variable "master_username" {
  description = "Master username for the Aurora MySQL cluster (never use 'admin')."
  type        = string
  default     = "aurora_admin"

  validation {
    condition     = var.master_username != "admin" && can(regex("^[a-zA-Z][a-zA-Z0-9_]{0,62}$", var.master_username))
    error_message = "master_username must be 1-63 alphanumeric or underscore characters and must not be 'admin'."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = var.project_name

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
    Project     = var.project_name
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Runtime-generated database credentials and Secrets Manager storage
# -----------------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 26
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "random_id" "final_snapshot" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}-db-master"
  description = "Master credentials for the ${local.name_prefix} Aurora MySQL cluster"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.db_master.result
  })
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

# Aurora cluster security group: MySQL ingress ONLY from the RDS Proxy SG
resource "aws_security_group" "db_cluster" {
  name        = "${local.name_prefix}-db-cluster-sg"
  description = "Aurora MySQL cluster - allow MySQL only from the RDS Proxy security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from RDS Proxy only"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.rds_proxy.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-cluster-sg"
  })
}

# RDS Proxy security group: MySQL ingress ONLY from the VPC CIDR
resource "aws_security_group" "rds_proxy" {
  name        = "${local.name_prefix}-rds-proxy-sg"
  description = "RDS Proxy - allow MySQL from within the VPC, egress limited to MySQL and Secrets Manager"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL to the Aurora cluster within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS to the Secrets Manager interface endpoint within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-proxy-sg"
  })
}

# Secrets Manager endpoint security group: HTTPS ingress ONLY from the VPC CIDR
resource "aws_security_group" "secrets_endpoint" {
  name        = "${local.name_prefix}-secrets-endpoint-sg"
  description = "Secrets Manager interface endpoint - allow HTTPS from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secrets-endpoint-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# Private Secrets Manager interface endpoint so the proxy can retrieve
# credentials without internet or NAT access
resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.secrets_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secretsmanager-endpoint"
  })
}

# -----------------------------------------------------------------------------
# IAM role for RDS Proxy (least privilege)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "rds_proxy" {
  name = "${local.name_prefix}-rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-proxy-role"
  })
}

resource "aws_iam_role_policy" "rds_proxy_secrets" {
  name = "${local.name_prefix}-rds-proxy-secrets-policy"
  role = aws_iam_role.rds_proxy.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadProxySecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = [aws_secretsmanager_secret.db_master.arn]
      },
      {
        Sid      = "DecryptProxySecret"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = ["*"]
        Condition = {
          StringEquals = {
            "kms:ViaService" = "secretsmanager.us-east-1.amazonaws.com"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Aurora MySQL cluster
# -----------------------------------------------------------------------------

resource "aws_rds_cluster" "main" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  engine                    = "aurora-mysql"
  engine_version            = "8.0.mysql_aurora.3.08.0"
  engine_mode               = "provisioned"
  database_name             = "appdb"
  master_username           = var.master_username
  master_password           = random_password.db_master.result
  db_subnet_group_name      = aws_db_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.db_cluster.id]
  storage_encrypted         = true
  backup_retention_period   = 7
  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-${random_id.final_snapshot.hex}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "main" {
  count = 2

  identifier                            = "${local.name_prefix}-instance-${count.index}"
  cluster_identifier                    = aws_rds_cluster.main.id
  engine                                = aws_rds_cluster.main.engine
  engine_version                        = aws_rds_cluster.main.engine_version
  instance_class                        = "db.r6g.large"
  db_subnet_group_name                  = aws_db_subnet_group.main.name
  availability_zone                     = element(data.aws_availability_zones.available.names, count.index)
  publicly_accessible                   = false
  auto_minor_version_upgrade            = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# RDS Proxy
# -----------------------------------------------------------------------------

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_subnet_ids         = aws_subnet.private[*].id
  vpc_security_group_ids = [aws_security_group.rds_proxy.id]
  require_tls            = true
  debug_logging          = false

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora master credentials from Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_master.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-proxy"
  })

  depends_on = [
    aws_iam_role_policy.rds_proxy_secrets,
    aws_secretsmanager_secret_version.db_master,
    aws_vpc_endpoint.secretsmanager,
  ]
}

# NOTE: aws_db_proxy_default_target_group does not support tagging at the
# provider/RDS API level. Tagging compliance is satisfied by the parent
# aws_db_proxy.main, which carries the merged common_tags.
resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

resource "aws_db_proxy_target" "main" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.cluster_identifier

  depends_on = [aws_rds_cluster_instance.main]
}

# -----------------------------------------------------------------------------
# Outputs (non-sensitive endpoints only)
# -----------------------------------------------------------------------------

output "aurora_writer_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.endpoint
}

output "aurora_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.reader_endpoint
}

output "rds_proxy_endpoint" {
  description = "Endpoint of the RDS Proxy"
  value       = aws_db_proxy.main.endpoint
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "bundle_id" {
  description = "Lightsail bundle ID that defines the instance size. Must be a valid bundle identifier (e.g. nano_3_0, micro_3_0)."
  type        = string
  default     = "nano_3_0"

  validation {
    condition     = length(trimspace(var.bundle_id)) > 0
    error_message = "bundle_id must be a non-empty Lightsail bundle identifier, e.g. nano_3_0."
  }
}

variable "environment" {
  description = "Environment name applied to all taggable Lightsail resource tags."
  type        = string
  default     = "dev"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "environment must be a non-empty value."
  }
}

locals {
  instance_name  = "app-server-01"
  key_pair_name  = "app-server-01-key"
  static_ip_name = "app-server-01-ip"

  base_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_lightsail_key_pair" "app" {
  name = local.key_pair_name

  tags = merge(local.base_tags, { Name = local.key_pair_name })
}

resource "aws_lightsail_instance" "app" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.app.name

  add_on {
    type          = "AutoSnapshot"
    status        = "Enabled"
    snapshot_time = "06:00"
  }

  tags = merge(local.base_tags, { Name = local.instance_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_instance_public_ports" "app" {
  instance_name = aws_lightsail_instance.app.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
  }
}

resource "aws_lightsail_static_ip" "app" {
  name = local.static_ip_name
}

resource "aws_lightsail_static_ip_attachment" "app" {
  static_ip_name = aws_lightsail_static_ip.app.name
  instance_name  = aws_lightsail_instance.app.name
}

output "instance_name" {
  description = "Name of the Lightsail instance."
  value       = aws_lightsail_instance.app.name
}

output "static_public_ip" {
  description = "Static public IP address attached to the Lightsail instance (persists across stop/start)."
  value       = aws_lightsail_static_ip.app.ip_address
}

output "availability_zone" {
  description = "Availability zone hosting the Lightsail instance."
  value       = aws_lightsail_instance.app.availability_zone
}

output "instance_arn" {
  description = "ARN of the Lightsail instance."
  value       = aws_lightsail_instance.app.arn
}

output "key_pair_fingerprint" {
  description = "Fingerprint of the Lightsail SSH key pair."
  value       = aws_lightsail_key_pair.app.fingerprint
}

output "ssh_public_key" {
  description = "Public key material of the Lightsail SSH key pair."
  value       = aws_lightsail_key_pair.app.public_key
  sensitive   = true
}

output "ssh_private_key" {
  description = "Private key material of the Lightsail SSH key pair (encrypted by Lightsail)."
  value       = aws_lightsail_key_pair.app.private_key
  sensitive   = true
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Variables — non-infrastructure values only, all defaulted so that
# `terraform apply` runs unattended.
#------------------------------------------------------------------------------

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "web-dualstack"
}

variable "blueprint_id" {
  description = "Lightsail blueprint (operating system image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance size) for the instance."
  type        = string
  default     = "nano_3_0"
}

variable "admin_ssh_cidrs" {
  description = "IPv4 CIDR blocks permitted to reach TCP 22 (SSH). Replace the documentation-range default with your administrator networks."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "admin_ssh_ipv6_cidrs" {
  description = "IPv6 CIDR blocks permitted to reach TCP 22 (SSH). Replace the documentation-range default with your administrator networks."
  type        = list(string)
  default     = ["2001:db8::/32"]
}

variable "tags" {
  description = "Tags applied to the Lightsail instance and key pair. Note: aws_lightsail_static_ip does not support tagging in the AWS provider schema, so the static IP is left untagged."
  type        = map(string)
  default = {
    Name      = "web-dualstack"
    ManagedBy = "terraform"
  }
}

#------------------------------------------------------------------------------
# Data source — static, well-known AZ metadata for the current region
# (the AZ name is never hardcoded).
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Lightsail key pair for SSH access. The generated private key material is
# never embedded in this configuration, in variables/locals, or in outputs.
#------------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "web" {
  name = "${var.instance_name}-key"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Lightsail instance — dualstack is declared via ip_address_type = "dualstack"
# (the provider schema's only supported mechanism for dual addressing): the
# instance receives a public IPv4 address plus auto-assigned public IPv6
# addresses. Lightsail manages its own networking outside of any VPC, so no
# VPC/subnet/security-group resources are used.
#------------------------------------------------------------------------------

resource "aws_lightsail_instance" "web" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.web.name
  ip_address_type   = "dualstack"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Instance firewall — replaces the permissive defaults with least-privilege
# rules:
#   TCP 80 / TCP 443 : open to the world over IPv4 and IPv6 (public web access)
#   TCP 22 (SSH)     : restricted to the administrator CIDR variables
#------------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "web" {
  instance_name = aws_lightsail_instance.web.name

  port_info {
    from_port  = 80
    to_port    = 80
    protocol   = "tcp"
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    from_port  = 443
    to_port    = 443
    protocol   = "tcp"
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    from_port  = 22
    to_port    = 22
    protocol   = "tcp"
    cidrs      = var.admin_ssh_cidrs
    ipv6_cidrs = var.admin_ssh_ipv6_cidrs
  }
}

#------------------------------------------------------------------------------
# Static IP — keeps the public IPv4 address stable across stop/start, while
# the IPv6 address remains auto-assigned by Lightsail. This resource does not
# support tags in the provider schema, so no tags argument is set here.
#------------------------------------------------------------------------------

resource "aws_lightsail_static_ip" "web" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_static_ip_attachment" "web" {
  static_ip_name = aws_lightsail_static_ip.web.name
  instance_name  = aws_lightsail_instance.web.name
}

#------------------------------------------------------------------------------
# Outputs — dualstack endpoints (none contain secrets).
#------------------------------------------------------------------------------

output "public_ipv4_address" {
  description = "Stable public IPv4 address of the Lightsail instance (static IP)."
  value       = aws_lightsail_static_ip.web.ip_address
}

output "ipv6_addresses" {
  description = "Auto-assigned public IPv6 addresses of the Lightsail instance (dualstack)."
  value       = aws_lightsail_instance.web.ipv6_addresses
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "master_username" {
  description = "Master username for the Lightsail MySQL database (must not be a reserved word)."
  type        = string
  default     = "dbadmin"
}

variable "tags" {
  description = "Application tags applied to all managed resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  relational_database_name = "app-mysql-db"
  master_database_name     = "appdb"
  final_snapshot_name      = "${local.relational_database_name}-final-snapshot"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "lightsail/mysql/${local.relational_database_name}"
  description = "Master credentials for the Lightsail MySQL database."

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_database" "main" {
  relational_database_name     = local.relational_database_name
  availability_zone            = data.aws_availability_zones.available.names[0]
  blueprint_id                 = "mysql_8_0"
  bundle_id                    = "micro_2_0"
  master_database_name         = local.master_database_name
  master_username              = var.master_username
  master_password              = random_password.db_master.result
  backup_retention_enabled     = true
  preferred_backup_window      = "16:00-16:30"
  preferred_maintenance_window = "Tue:17:00-Tue:17:30"
  publicly_accessible          = false
  apply_immediately            = false
  skip_final_snapshot          = false
  final_snapshot_name          = local.final_snapshot_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.db_master.result
    engine   = "mysql"
    host     = aws_lightsail_database.main.master_endpoint_address
    port     = aws_lightsail_database.main.master_endpoint_port
    dbname   = local.master_database_name
  })
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Lightsail MySQL master credentials."
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resource tags"
  type        = string
  default     = "dev"
}

variable "disk_size_gb" {
  description = "Size of the Lightsail disk in GB"
  type        = number
  default     = 32
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  instance_name = "app_instance"
  disk_name     = "app_data_disk"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "lightsail-disk-attachment"
  }
}

resource "aws_lightsail_key_pair" "main" {
  name = "${local.instance_name}-key"

  tags = local.common_tags
}

resource "aws_lightsail_instance" "app_instance" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = local.common_tags
}

resource "aws_lightsail_instance_public_ports" "app_instance_ports" {
  instance_name = aws_lightsail_instance.app_instance.name

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }
}

resource "aws_lightsail_disk" "app_data_disk" {
  name              = local.disk_name
  size_in_gb        = var.disk_size_gb
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_disk_attachment" "app_data_disk_attachment" {
  disk_name     = aws_lightsail_disk.app_data_disk.name
  instance_name = aws_lightsail_instance.app_instance.name
  disk_path     = "/dev/xvdf"
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail instance"
  value       = aws_lightsail_instance.app_instance.public_ip_address
}

output "disk_name" {
  description = "Name of the Lightsail disk attached to the instance"
  value       = aws_lightsail_disk.app_data_disk.name
}

output "disk_attachment_path" {
  description = "Device path at which the disk is attached on the instance"
  value       = aws_lightsail_disk_attachment.app_data_disk_attachment.disk_path
}

# Lightsail Certificate
# Issues a Lightsail (ACM-backed) TLS certificate for a primary domain with
# optional subject alternative names. DNS CNAME validation records are exposed
# as outputs so they can be registered in the domain's DNS zone out-of-band.

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "domain_name" {
  description = "Primary fully-qualified domain name the Lightsail certificate is issued for."
  type        = string
  default     = "example.com"

  validation {
    condition     = can(regex("^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}$", var.domain_name))
    error_message = "domain_name must be a valid FQDN containing only lowercase letters, digits, hyphens, and dots (e.g. example.com)."
  }
}

variable "alternative_names" {
  description = "Optional set of subject alternative names (FQDNs) to include in the certificate."
  type        = set(string)
  default     = []

  validation {
    condition = alltrue([
      for name in var.alternative_names :
      can(regex("^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}$", name))
    ])
    error_message = "Each alternative name must be a valid FQDN containing only lowercase letters, digits, hyphens, and dots (e.g. www.example.com)."
  }
}

variable "environment" {
  description = "Environment label applied to resource tags for ownership and cost tracking."
  type        = string
  default     = "production"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]{0,18}[a-z0-9])?$", var.environment))
    error_message = "environment must be 1-20 lowercase alphanumeric characters or hyphens."
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Lightsail certificate names accept lowercase alphanumeric characters and
  # hyphens only (1-255 chars). Derive a stable, human-readable, per-domain
  # unique name from the primary domain.
  certificate_name = "main-${replace(var.domain_name, ".", "-")}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Lightsail Certificate
# ------------------------------------------------------------------------------

resource "aws_lightsail_certificate" "main" {
  name        = local.certificate_name
  domain_name = var.domain_name

  # Schema-bound argument name for SANs; the provider automatically adds
  # domain_name as a SAN, so no value transformation is required here.
  subject_alternative_names = var.alternative_names

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "certificate_name" {
  description = "Name of the Lightsail certificate."
  value       = aws_lightsail_certificate.main.name
}

output "certificate_arn" {
  description = "ARN of the Lightsail certificate."
  value       = aws_lightsail_certificate.main.arn
}

output "certificate_created_at" {
  description = "Creation timestamp of the Lightsail certificate (issuance progress is observable via the domain_validation_records output, which populates once DNS validation begins)."
  value       = aws_lightsail_certificate.main.created_at
}

output "domain_validation_records" {
  description = "DNS validation options that must be registered in the domain's DNS zone (out-of-band) so Lightsail can validate and issue the certificate."
  value       = aws_lightsail_certificate.main.domain_validation_options
}

output "domain_validation_cname_records" {
  description = "Convenience view of the CNAME validation records (name/type/value) ready to be added to the domain's DNS zone."
  value = {
    for record in aws_lightsail_certificate.main.domain_validation_options :
    record.resource_record_name => {
      name  = record.resource_record_name
      type  = record.resource_record_type
      value = record.resource_record_value
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables (user-controlled values with unattended-apply defaults)
# ------------------------------------------------------------------------------

variable "environment" {
  description = "Environment name applied as the Environment tag on all taggable resources."
  type        = string
  default     = "prod"
}

variable "backup_plan_tag_value" {
  description = "Value of the BackupPlan resource tag that enrolls resources into the AWS Backup plan."
  type        = string
  default     = "long-term-archive-and-backup"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "prod"
    Purpose     = "long-term-archive-and-backup"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Data sources (static, well-known metadata lookups only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  archive_bucket_name = "long-term-storage-${local.account_id}-archive"
  backup_bucket_name  = "long-term-storage-${local.account_id}-backup"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })

  backup_role_name      = "aws-backup-long-term-service-role"
  backup_vault_name     = "long-term-backup-vault"
  backup_plan_name      = "long-term-backup-plan"
  backup_selection_name = "long-term-tag-based-selection"

  backup_managed_policy_backup_arn  = "arn:${local.partition}:iam::aws:policy/AWSBackupServiceRolePolicyForBackup"
  backup_managed_policy_restore_arn = "arn:${local.partition}:iam::aws:policy/AWSBackupServiceRolePolicyForRestores"

  noncurrent_version_retention_days = 2557 # ~7 years
}

# ------------------------------------------------------------------------------
# Central customer-managed KMS key
# ------------------------------------------------------------------------------

resource "aws_kms_key" "long_term_storage" {
  description             = "Central customer-managed key for long-term archive and backup encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "long-term-storage-key"
  })
}

resource "aws_kms_alias" "long_term_storage" {
  name          = "alias/long-term-storage"
  target_key_id = aws_kms_key.long_term_storage.key_id
}

# ------------------------------------------------------------------------------
# Primary long-term archive bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "archive" {
  bucket = local.archive_bucket_name

  tags = merge(local.common_tags, {
    Name = local.archive_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "archive" {
  bucket = aws_s3_bucket.archive.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "archive" {
  bucket = aws_s3_bucket.archive.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.long_term_storage.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "archive" {
  bucket = aws_s3_bucket.archive.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "archive" {
  bucket = aws_s3_bucket.archive.id

  rule {
    id     = "long-term-tiering-and-expiry"
    status = "Enabled"

    filter {}

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    transition {
      days          = 90
      storage_class = "GLACIER"
    }

    transition {
      days          = 365
      storage_class = "DEEP_ARCHIVE"
    }

    noncurrent_version_expiration {
      noncurrent_days = local.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "archive_tls_only" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.archive.arn,
      "${aws_s3_bucket.archive.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "archive" {
  bucket = aws_s3_bucket.archive.id
  policy = data.aws_iam_policy_document.archive_tls_only.json

  depends_on = [aws_s3_bucket_public_access_block.archive]
}

# ------------------------------------------------------------------------------
# Immutable WORM backup bucket (Object Lock in COMPLIANCE mode)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "backup" {
  bucket              = local.backup_bucket_name
  object_lock_enabled = true

  tags = merge(local.common_tags, {
    Name = local.backup_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.long_term_storage.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_object_lock_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  depends_on = [aws_s3_bucket_versioning.backup]

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 90
    }
  }
}

data "aws_iam_policy_document" "backup_tls_only" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.backup.arn,
      "${aws_s3_bucket.backup.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "backup" {
  bucket = aws_s3_bucket.backup.id
  policy = data.aws_iam_policy_document.backup_tls_only.json

  depends_on = [aws_s3_bucket_public_access_block.backup]
}

# ------------------------------------------------------------------------------
# Account-level S3 public access protection
# ------------------------------------------------------------------------------

resource "aws_s3_account_public_access_block" "main" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# AWS Backup IAM role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowAWSBackupToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = local.backup_role_name
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(local.common_tags, {
    Name = local.backup_role_name
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = local.backup_managed_policy_backup_arn
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = local.backup_managed_policy_restore_arn
}

# ------------------------------------------------------------------------------
# AWS Backup vault (KMS-encrypted, vault-locked)
# ------------------------------------------------------------------------------

resource "aws_backup_vault" "main" {
  name        = local.backup_vault_name
  kms_key_arn = aws_kms_key.long_term_storage.arn

  tags = merge(local.common_tags, {
    Name = local.backup_vault_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "main" {
  backup_vault_name  = aws_backup_vault.main.name
  min_retention_days = 90
}

# ------------------------------------------------------------------------------
# AWS Backup plan (daily / weekly / monthly)
# lifecycle values are reconciled with AWS Backup API constraints:
#   - delete_after must be >= 90 days (also enforced by vault lock)
#   - cold retention must be >= 90 days (delete_after >= cold_storage_after + 90)
# ------------------------------------------------------------------------------

resource "aws_backup_plan" "main" {
  name = local.backup_plan_name

  tags = merge(local.common_tags, {
    Name = local.backup_plan_name
  })

  rule {
    rule_name         = "daily"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 * * ? *)"

    lifecycle {
      delete_after = 90
    }
  }

  rule {
    rule_name         = "weekly"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 ? * MON *)"

    lifecycle {
      cold_storage_after = 90
      delete_after       = 180
    }
  }

  rule {
    rule_name         = "monthly"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 1 * ? *)"

    lifecycle {
      cold_storage_after = 90
      delete_after       = 365
    }
  }
}

# ------------------------------------------------------------------------------
# Tag-based backup selection
# Note: aws_backup_selection is a non-taggable AWS resource (the underlying
# CreateBackupSelection API does not support tags), so no tags argument is set.
# ------------------------------------------------------------------------------

resource "aws_backup_selection" "main" {
  name         = local.backup_selection_name
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "BackupPlan"
    value = var.backup_plan_tag_value
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restore,
  ]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "archive_bucket_name" {
  description = "Name of the long-term archive S3 bucket."
  value       = aws_s3_bucket.archive.id
}

output "archive_bucket_arn" {
  description = "ARN of the long-term archive S3 bucket."
  value       = aws_s3_bucket.archive.arn
}

output "backup_bucket_name" {
  description = "Name of the immutable backup S3 bucket."
  value       = aws_s3_bucket.backup.id
}

output "backup_bucket_arn" {
  description = "ARN of the immutable backup S3 bucket."
  value       = aws_s3_bucket.backup.arn
}

output "kms_key_arn" {
  description = "ARN of the central customer-managed KMS key."
  value       = aws_kms_key.long_term_storage.arn
}

output "backup_vault_arn" {
  description = "ARN of the encrypted AWS Backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan."
  value       = aws_backup_plan.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Snake_case name of the S3 Glacier vault."
  type        = string
  default     = "archive_data_vault"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{2,49}$", var.vault_name))
    error_message = "Vault name must be snake_case: lowercase letters, digits, and underscores, 3-50 characters, starting with a letter."
  }
}

variable "tags" {
  description = "Tags applied to all resources for consistent labeling."
  type        = map(string)
  default = {
    Environment = "production"
    Name        = "archive_data_vault"
    ManagedBy   = "terraform"
  }
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  vault_name = var.vault_name

  vault_access_role_name = "${local.vault_name}-access-role"

  vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${local.vault_name}"

  glacier_vault_actions = [
    "glacier:InitiateJob",
    "glacier:DescribeJob",
    "glacier:GetJobOutput",
    "glacier:DescribeVault",
    "glacier:ListJobs",
  ]

  glacier_destructive_actions = [
    "glacier:DeleteArchive",
    "glacier:DeleteVault",
  ]
}

resource "aws_glacier_vault" "main" {
  name = local.vault_name
  tags = var.tags

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowVaultAccessOverTLS"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.vault_access.arn
        }
        Action   = local.glacier_vault_actions
        Resource = local.vault_arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "true"
          }
        }
      },
      {
        Sid    = "DenyDestructiveActionsToNonAdminPrincipals"
        Effect = "Deny"
        Principal = {
          AWS = aws_iam_role.vault_access.arn
        }
        Action   = local.glacier_destructive_actions
        Resource = local.vault_arn
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "vault_access" {
  name = local.vault_access_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeVaultAccessRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "glacier_read_only" {
  role       = aws_iam_role.vault_access.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSGlacierReadOnlyAccess"
}

resource "aws_iam_role_policy" "vault_access" {
  name = "glacier-vault-scoped-access"
  role = aws_iam_role.vault_access.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ScopedGlacierVaultAccess"
        Effect   = "Allow"
        Action   = local.glacier_vault_actions
        Resource = aws_glacier_vault.main.arn
      }
    ]
  })
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier vault."
  value       = aws_glacier_vault.main.arn
}

output "glacier_vault_name" {
  description = "Name of the S3 Glacier vault."
  value       = aws_glacier_vault.main.name
}

output "vault_access_role_arn" {
  description = "ARN of the IAM role authorized to access the Glacier vault."
  value       = aws_iam_role.vault_access.arn
}

###############################################################################
# main.tf
#
# Internet-facing Network Load Balancer (NLB) in front of a single t2.micro
# EC2 instance running a lightweight HTTP server on port 80.
#
# Fully self-contained: VPC, subnets, IGW, routing, security group, EC2
# target, NLB, target group, listener, and attachment are all declared here.
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project     = "nlb-ec2-demo"
  environment = "dev"

  common_tags = {
    project     = local.project
    environment = local.environment
    managed_by  = "terraform"
  }
}

###############################################################################
# Data sources (static/well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security
###############################################################################

resource "aws_security_group" "nlb_target" {
  name        = "${local.project}-nlb-target-sg"
  description = "Allow HTTP to the NLB target from anywhere (NLB preserves client source IPs)"
  vpc_id      = aws_vpc.main.id

  # Justification: an internet-facing NLB preserves the client source IP for
  # TCP traffic, so the target security group must accept port 80 from
  # 0.0.0.0/0. Port 80 is the only publicly allowed inbound port; no other
  # inbound ports are open.
  ingress {
    description = "HTTP from anywhere (internet-facing NLB preserves client source IPs)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-nlb-target-sg"
  })
}

###############################################################################
# EC2 target instance
###############################################################################

resource "aws_instance" "web" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_a.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.nlb_target.id]

  root_block_device {
    encrypted             = true
    volume_size           = 8
    volume_type           = "gp3"
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data_replace_on_change = true

  user_data = <<-EOF
#!/bin/bash
set -euxo pipefail

# Install and start nginx from the Amazon Linux 2023 repositories so the
# NLB TCP health checks on port 80 pass.
dnf install -y nginx

echo "<h1>Hello from $(hostname -f) behind an internet-facing NLB</h1>" > /usr/share/nginx/html/index.html

systemctl enable nginx
systemctl start nginx
  EOF

  tags = merge(local.common_tags, {
    Name = "${local.project}-web"
  })
}

###############################################################################
# Network Load Balancer
###############################################################################

resource "aws_lb" "nlb" {
  name               = "${local.project}-nlb"
  load_balancer_type = "network"
  internal           = false
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  # The only target lives in one AZ; cross-zone load balancing lets the NLB
  # node in the second AZ forward traffic to it.
  enable_cross_zone_load_balancing = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-nlb"
  })
}

resource "aws_lb_target_group" "web" {
  name        = "${local.project}-tg"
  port        = 80
  protocol    = "TCP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "80"
    interval            = 30
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.nlb.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-http-listener"
  })
}

resource "aws_lb_target_group_attachment" "web" {
  target_group_arn = aws_lb_target_group.web.arn
  target_id        = aws_instance.web.id
  port             = 80
}

###############################################################################
# Outputs
###############################################################################

output "nlb_dns_name" {
  description = "Public DNS name of the internet-facing NLB (primary test endpoint)"
  value       = aws_lb.nlb.dns_name
}

output "nlb_arn" {
  description = "ARN of the Network Load Balancer"
  value       = aws_lb.nlb.arn
}

output "web_instance_id" {
  description = "Instance ID of the EC2 target behind the NLB"
  value       = aws_instance.web.id
}

output "web_instance_public_ip" {
  description = "Public IPv4 address of the EC2 target behind the NLB"
  value       = aws_instance.web.public_ip
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  name_prefix       = "nlb-eip"
  environment       = "production"
  access_log_prefix = "nlb-access-logs"
  log_bucket_name   = "nlb-access-logs-${data.aws_caller_identity.current.account_id}"
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = local.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = local.environment
  }
}

resource "aws_subnet" "public_az1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-az1"
    Environment = local.environment
  }
}

resource "aws_subnet" "public_az2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-az2"
    Environment = local.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = local.environment
  }
}

resource "aws_route_table_association" "public_az1" {
  subnet_id      = aws_subnet.public_az1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az2" {
  subnet_id      = aws_subnet.public_az2.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Static Elastic IPs for the Network Load Balancer (one per AZ)
# -----------------------------------------------------------------------------

resource "aws_eip" "nlb_az1" {
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-eip-az1"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "nlb_az2" {
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-eip-az2"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# S3 bucket for NLB access logging
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "access_logs" {
  bucket = local.log_bucket_name

  tags = {
    Name        = "${local.name_prefix}-access-logs"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDeliveryPutObject"
        Effect    = "Allow"
        Principal = {
          Service = "logdelivery.elasticloadbalancing.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.access_logs.arn}/${local.access_log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Internet-facing Network Load Balancer with explicitly specified Elastic IPs
# -----------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-nlb"
  load_balancer_type = "network"
  internal           = false
  ip_address_type    = "ipv4"

  subnet_mapping {
    subnet_id     = aws_subnet.public_az1.id
    allocation_id = aws_eip.nlb_az1.id
  }

  subnet_mapping {
    subnet_id     = aws_subnet.public_az2.id
    allocation_id = aws_eip.nlb_az2.id
  }

  access_logs {
    bucket  = aws_s3_bucket.access_logs.id
    prefix  = local.access_log_prefix
    enabled = true
  }

  tags = {
    Name        = "${local.name_prefix}-nlb"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group" "main" {
  name     = "${local.name_prefix}-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "traffic-port"
    interval            = 30
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name        = "${local.name_prefix}-tg"
    Environment = local.environment
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name        = "${local.name_prefix}-listener-80"
    Environment = local.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "nlb_dns_name" {
  description = "Public DNS name of the Network Load Balancer."
  value       = aws_lb.main.dns_name
}

output "nlb_static_ip_az1" {
  description = "Static Elastic IP serving the Network Load Balancer in the first AZ."
  value       = aws_eip.nlb_az1.public_ip
}

output "nlb_static_ip_az2" {
  description = "Static Elastic IP serving the Network Load Balancer in the second AZ."
  value       = aws_eip.nlb_az2.public_ip
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for consistent Name/Environment tags across all resources"
  type        = string
  default     = "alb-redirect"
}

locals {
  common_tags = {
    Name        = var.project_name
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = local.common_tags
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = local.common_tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = local.common_tags
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "${var.project_name}-alb-sg"
  description = "Public web ports for the internet-facing redirect ALB"
  vpc_id      = aws_vpc.main.id

  # Justification: this is an internet-facing ALB whose sole purpose is to
  # redirect public web traffic; TCP/80 is the entry point that issues the
  # HTTP -> HTTPS redirect.
  ingress {
    description = "HTTP from anywhere; listener issues a permanent redirect to HTTPS"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Justification: TCP/443 is the redirect destination, so it is opened for
  # public web traffic destined for this load balancer only.
  ingress {
    description = "HTTPS from anywhere; the redirect destination"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_lb" "alb" {
  name                       = var.project_name
  load_balancer_type         = "application"
  internal                   = false
  ip_address_type            = "ipv4"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = local.common_tags
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
      host        = "#{host}"
      path        = "#{path}"
      query       = "#{query}"
    }
  }

  tags = local.common_tags
}

output "alb_dns_name" {
  description = "Public DNS name of the ALB; send an HTTP request here to verify the 301 redirect"
  value       = aws_lb.alb.dns_name
}

output "http_listener_arn" {
  description = "ARN of the HTTP listener that performs the permanent redirect"
  value       = aws_lb_listener.http.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resources for consistent tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-zA-Z0-9][a-zA-Z0-9-]{0,19}$", var.environment))
    error_message = "Environment must be 1-20 alphanumeric characters or hyphens."
  }
}

# --- Static/well-known data lookups only (no pre-existing infrastructure) ---

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  vpc_cidr = "10.0.0.0/16"

  az_count           = 2
  availability_zones = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  subnet_az_map = {
    for idx, az in local.availability_zones :
    az => cidrsubnet(local.vpc_cidr, 8, idx + 1)
  }

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# --- Inspection VPC networking ---

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-public-rt"
  })
}

resource "aws_subnet" "appliance" {
  for_each = local.subnet_az_map

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = each.value
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-public-${each.key}"
  })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.appliance

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# --- Security groups ---

resource "aws_security_group" "appliance_sg" {
  name        = "gwlb-appliance-sg"
  description = "Permit inbound GENEVE (UDP/6081) traffic from within the inspection VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "GENEVE-encapsulated traffic from the inspection VPC"
    from_port   = 6081
    to_port     = 6081
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-sg"
  })
}

resource "aws_security_group" "ssm_endpoints" {
  name        = "gwlb-ssm-endpoints-sg"
  description = "Permit HTTPS from within the inspection VPC to the SSM interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the inspection VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-ssm-endpoints-sg"
  })
}

# Interface endpoints so the keyless (no public IP, no SSH) appliances can
# reach AWS Systems Manager for management access.
resource "aws_vpc_endpoint" "ssm" {
  for_each = toset(["ssm", "ssmmessages", "ec2messages"])

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [for subnet in aws_subnet.appliance : subnet.id]
  security_group_ids  = [aws_security_group.ssm_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-${each.key}-endpoint"
  })
}

# --- Appliance IAM (keyless management via SSM) ---

resource "aws_iam_role" "appliance_ssm" {
  name = "gwlb-appliance-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "appliance_ssm_core" {
  role       = aws_iam_role.appliance_ssm.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "appliance" {
  name = "gwlb-appliance-instance-profile"
  role = aws_iam_role.appliance_ssm.name

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-instance-profile"
  })
}

# --- Appliance instances ---

resource "aws_instance" "appliance" {
  for_each = aws_subnet.appliance

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = each.value.id
  vpc_security_group_ids      = [aws_security_group.appliance_sg.id]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.appliance.name

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-${each.key}"
  })
}

# --- Gateway Load Balancer ---

resource "aws_lb_target_group" "gwlb_targets" {
  name        = "gwlb-targets"
  target_type = "instance"
  protocol    = "GENEVE"
  port        = 6081
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "traffic-port"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-targets"
  })
}

resource "aws_lb" "gwlb" {
  name               = "gwlb-inspection"
  load_balancer_type = "gateway"

  subnets = [for subnet in aws_subnet.appliance : subnet.id]

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection"
  })
}

resource "aws_lb_listener" "gwlb" {
  load_balancer_arn = aws_lb.gwlb.arn
  protocol          = "GENEVE"
  port              = 6081

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.gwlb_targets.arn
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-listener"
  })
}

resource "aws_lb_target_group_attachment" "appliance" {
  for_each = aws_instance.appliance

  target_group_arn = aws_lb_target_group.gwlb_targets.arn
  target_id        = each.value.id
  port             = 6081
}

resource "aws_vpc_endpoint_service" "gwlb" {
  acceptance_required        = false
  gateway_load_balancer_arns = [aws_lb.gwlb.arn]
  allowed_principals         = [local.account_root_arn]

  tags = merge(local.common_tags, {
    Name = "gwlb-endpoint-service"
  })
}

# --- Outputs for downstream consumer VPCs ---

output "gateway_load_balancer_arn" {
  description = "ARN of the Gateway Load Balancer."
  value       = aws_lb.gwlb.arn
}

output "gateway_load_balancer_arn_suffix" {
  description = "ARN suffix of the Gateway Load Balancer (useful for CloudWatch metrics and alarms)."
  value       = aws_lb.gwlb.arn_suffix
}

output "gateway_load_balancer_endpoint_service_name" {
  description = "Service name that downstream consumer VPCs use to create Gateway Load Balancer endpoints."
  value       = aws_vpc_endpoint_service.gwlb.service_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  name_prefix = "alb-demo"
  environment = "dev"
  log_prefix  = "alb-access-logs"

  common_tags = {
    Environment = local.environment
  }
}

# ---------------------------------------------------------------------------
# Network foundation
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Ingress for the public Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

resource "aws_security_group" "targets" {
  name        = "${local.name_prefix}-targets-sg"
  description = "Ingress for ALB backend instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-targets-sg"
  })
}

# ---------------------------------------------------------------------------
# Target group, load balancer, listener
# ---------------------------------------------------------------------------

resource "aws_lb_target_group" "app" {
  name        = "${local.name_prefix}-tg"
  vpc_id      = aws_vpc.main.id
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"

  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tg"
  })
}

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-alb"
  load_balancer_type = "application"
  internal           = false

  security_groups = [aws_security_group.alb.id]
  subnets         = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.log_prefix
    enabled = true
  }

  depends_on = [aws_s3_bucket_policy.alb_logs]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-http-listener"
  })
}

# ---------------------------------------------------------------------------
# Backend instances
# ---------------------------------------------------------------------------

resource "aws_instance" "app" {
  count = 2

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public[count.index].id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.targets.id]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    echo "<h1>Hello from $(hostname -f)</h1>" > /var/www/html/index.html
    systemctl enable --now httpd
  EOF

  user_data_replace_on_change = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  depends_on = [aws_route_table_association.public]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-${count.index + 1}"
  })
}

resource "aws_lb_target_group_attachment" "app" {
  count = 2

  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.app[count.index].id
  port             = 80
}

# ---------------------------------------------------------------------------
# ALB access log bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "alb_logs" {
  bucket = "${local.name_prefix}-alb-logs-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-logs"
  })
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "alb_logs" {
  statement {
    sid    = "AllowELBLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.alb_logs.id}/${local.log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id
  policy = data.aws_iam_policy_document.alb_logs.json

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer"
  value       = aws_lb.main.dns_name
}

output "alb_target_group_arn" {
  description = "ARN of the ALB target group"
  value       = aws_lb_target_group.app.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "prod"
}

variable "common_tags" {
  description = "Common tags applied consistently to all resources."
  type        = map(string)
  default = {
    Project   = "greenfield-data-platform"
    Owner     = "platform-team"
    ManagedBy = "terraform"
  }
}

locals {
  name          = "${var.environment}-postgres"
  db_identifier = "${local.name}-db"
  common_tags   = merge(var.common_tags, { Environment = var.environment })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${count.index + 1}"
    Tier = "database"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.db_identifier}-subnets"
  description = "Private subnets spanning multiple AZs for the ${local.name} database tier"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-subnets"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "postgres" {
  name        = "${local.db_identifier}-sg"
  description = "Restrict ingress to PostgreSQL (TCP 5432) from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-sg"
  })
}

resource "aws_kms_key" "rds" {
  description             = "Customer managed key for ${local.name} storage encryption and Performance Insights"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-rds-key"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_parameter_group" "main" {
  name        = "${local.db_identifier}-params"
  family      = "postgres16"
  description = "Custom PostgreSQL 16 parameters for ${local.db_identifier}"

  parameter {
    name  = "max_connections"
    value = "200"
  }

  parameter {
    name  = "shared_preload_libraries"
    value = "pg_stat_statements"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-params"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_db_instance" "main" {
  identifier     = local.db_identifier
  engine         = "postgresql"
  engine_version = "16.4"
  instance_class = "db.t4g.large"

  allocated_storage     = 50
  max_allocated_storage = 500
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name                     = "appdb"
  username                    = "dbadmin"
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  parameter_group_name   = aws_db_parameter_group.main.name
  multi_az               = true
  publicly_accessible    = false
  port                   = 5432

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-${random_id.final_snapshot_suffix.hex}"

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the PostgreSQL instance."
  value       = aws_db_instance.main.endpoint
}

output "db_instance_address" {
  description = "DNS address of the PostgreSQL instance."
  value       = aws_db_instance.main.address
}

output "db_instance_port" {
  description = "Port the PostgreSQL instance listens on."
  value       = aws_db_instance.main.port
}

output "db_master_user_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials (secret value is never exposed)."
  value       = aws_db_instance.main.master_user_secret[0].secret_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata: AZs available in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

variable "project_name" {
  description = "Project name used for resource naming and the Project tag."
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Environment name used for resource naming and the Environment tag."
  type        = string
  default     = "production"
}

locals {
  name_prefix     = "${var.project_name}-${var.environment}"
  master_username = "dbadmin"
  db_name         = "appdb"
  db_port         = 3306

  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

# --- Network foundation (greenfield: everything is created here) ---

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Subnet group spanning two AZs for ${local.name_prefix} RDS instances"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# --- Network access control: MySQL reachable only from inside the VPC ---

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow MySQL traffic only from within the ${local.name_prefix} VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the VPC CIDR only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

# --- Master credentials: generated securely, stored in Secrets Manager ---

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#%*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.name_prefix}-db-master-credentials"
  description = "Master credentials for the ${local.name_prefix} primary MySQL instance"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username             = local.master_username
    password             = random_password.db_master_password.result
    engine               = "mysql"
    host                 = aws_db_instance.primary.address
    port                 = local.db_port
    dbname               = local.db_name
    dbInstanceIdentifier = aws_db_instance.primary.identifier
  })
}

# --- Shared parameter group (family matches the pinned engine version) ---

resource "aws_db_parameter_group" "mysql" {
  name        = "${local.name_prefix}-mysql-params"
  family      = "mysql8.0"
  description = "Shared parameter group for ${local.name_prefix} primary and replica"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-params"
  })
}

# --- Primary MySQL instance ---

resource "aws_db_instance" "primary" {
  identifier     = "${local.name_prefix}-primary"
  engine         = "mysql"
  engine_version = "8.0.36"
  instance_class = "db.t3.medium"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"

  db_name  = local.db_name
  username = local.master_username
  password = random_password.db_master_password.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  port                = local.db_port
  publicly_accessible = false
  multi_az            = false

  storage_encrypted       = true
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-primary-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary"
  })
}

# --- Read replica (native replication, same network, sizing, and encryption) ---

resource "aws_db_instance" "replica" {
  identifier          = "${local.name_prefix}-replica"
  replicate_source_db = aws_db_instance.primary.arn
  instance_class      = "db.t3.medium"

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  storage_encrypted   = true

  copy_tags_to_snapshot      = true
  deletion_protection        = true
  auto_minor_version_upgrade = true

  skip_final_snapshot = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-replica"
  })
}

# --- Outputs ---

output "primary_db_endpoint" {
  description = "Connection endpoint (hostname) of the primary MySQL instance."
  value       = aws_db_instance.primary.address
}

output "replica_db_endpoint" {
  description = "Connection endpoint (hostname) of the MySQL read replica."
  value       = aws_db_instance.replica.address
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master credentials (the secret value itself is never exposed)."
  value       = aws_secretsmanager_secret.db_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  env         = lower(var.environment)
  name_prefix = "db-restore-${local.env}"

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.0.0/24", "10.0.1.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.11.0/24"]

  # Master username stored in Secrets Manager; password is generated by random_password.
  db_username   = "dbadmin"
  backup_prefix = "backups/mysql-xtrabackup/"

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

#-------------------------------------------------------------------------------
# Network foundation
#-------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

#-------------------------------------------------------------------------------
# Database security group
#-------------------------------------------------------------------------------

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow MySQL (3306) only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # No egress rules declared: the database requires no outbound access, and
  # Terraform removes the default allow-all egress rule when none is specified.

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

#-------------------------------------------------------------------------------
# Customer-managed KMS key (RDS storage encryption + S3 backup SSE-KMS)
#-------------------------------------------------------------------------------

resource "aws_kms_key" "rds" {
  description             = "Customer managed key for RDS storage encryption and S3 backup bucket SSE-KMS"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-kms"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.rds.key_id
}

#-------------------------------------------------------------------------------
# Backup source bucket (Percona XtraBackup files for MySQL S3 import)
#-------------------------------------------------------------------------------

resource "aws_s3_bucket" "db_backup" {
  bucket        = "${local.name_prefix}-backup-${random_id.suffix.hex}"
  force_destroy = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-backup-${random_id.suffix.hex}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.rds.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.db_backup.arn,
          "${aws_s3_bucket.db_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

#-------------------------------------------------------------------------------
# RDS-to-S3 import IAM role
#-------------------------------------------------------------------------------

resource "aws_iam_role" "rds_s3_import" {
  name = "${local.name_prefix}-rds-s3-import"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRdsAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-s3-import"
  })
}

resource "aws_iam_role_policy" "rds_s3_import" {
  name = "${local.name_prefix}-s3-import-access"
  role = aws_iam_role.rds_s3_import.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListBackupBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.db_backup.arn
      },
      {
        Sid      = "ReadBackupObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource = "${aws_s3_bucket.db_backup.arn}/*"
      }
    ]
  })
}

# The ingestion role must be able to decrypt the SSE-KMS protected backup objects.
resource "aws_iam_policy" "rds_kms_decrypt" {
  name        = "${local.name_prefix}-rds-kms-decrypt"
  description = "Allow the RDS S3 ingestion role to decrypt backup objects protected by the customer managed KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptBackupObjects"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:DescribeKey"]
        Resource = aws_kms_key.rds.arn
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-kms-decrypt"
  })
}

resource "aws_iam_role_policy_attachment" "rds_kms_decrypt" {
  role       = aws_iam_role.rds_s3_import.name
  policy_arn = aws_iam_policy.rds_kms_decrypt.arn
}

#-------------------------------------------------------------------------------
# Master credentials in Secrets Manager
#-------------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}/db-master-credentials"
  description = "Master credentials for the ${local.name_prefix}-restored-db MySQL instance"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id

  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

#-------------------------------------------------------------------------------
# MySQL database restored from S3 (Percona XtraBackup import)
#-------------------------------------------------------------------------------

resource "aws_db_instance" "restored_db" {
  identifier     = "${local.name_prefix}-restored-db"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name = "appdb"
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  port                   = 3306
  publicly_accessible    = false
  multi_az               = true

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-${random_id.suffix.hex}"

  # Backup files (Percona XtraBackup format) must be uploaded to
  # s3://<bucket>/backups/mysql-xtrabackup/ before this instance can be created.
  # The bucket and instance are both provisioned in the provider region (us-east-1).
  s3_import {
    source_engine         = "mysql"
    source_engine_version = "8.0"
    bucket_name           = aws_s3_bucket.db_backup.bucket
    bucket_prefix         = local.backup_prefix
    ingestion_role        = aws_iam_role.rds_s3_import.arn
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-restored-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

#-------------------------------------------------------------------------------
# Outputs
#-------------------------------------------------------------------------------

output "rds_endpoint_address" {
  description = "Connection endpoint (hostname) of the restored MySQL DB instance."
  value       = aws_db_instance.restored_db.address
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the DB master credentials (secret value is never exposed; retrieve it via secretsmanager:GetSecretValue)."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "tags" {
  description = "Additional tags applied consistently to all resources."
  type        = map(string)
  default     = {}
}

locals {
  db_identifier               = "myapp-mysql"
  db_name                     = "myappdb"
  db_username                 = "dbadmin"
  vpc_name                    = "myapp-vpc"
  subnet_group_name           = "myapp-rds-subnet-group"
  security_group_name         = "myapp-rds-mysql-sg"
  secret_name                 = "myapp/mysql/master"
  final_snapshot_identifier   = "myapp-mysql-final-snapshot"
  initial_snapshot_identifier = "myapp-mysql-initial-snapshot"

  common_tags = merge(var.tags)
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_subnet" "rds_az0" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-rds-az0"
  })
}

resource "aws_subnet" "rds_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-rds-az1"
  })
}

resource "aws_db_subnet_group" "rds" {
  name       = local.subnet_group_name
  subnet_ids = [aws_subnet.rds_az0.id, aws_subnet.rds_az1.id]

  tags = merge(local.common_tags, {
    Name = local.subnet_group_name
  })
}

resource "aws_security_group" "rds" {
  name        = local.security_group_name
  description = "Allow MySQL access only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the VPC CIDR only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL traffic restricted to the VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = local.security_group_name
  })
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = local.secret_name
  description = "Master credentials for the ${local.db_identifier} MySQL instance"

  tags = merge(local.common_tags, {
    Name = local.secret_name
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
    engine   = "mysql"
    port     = 3306
    host     = aws_db_instance.mysql.address
    dbname   = aws_db_instance.mysql.db_name
  })
}

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = local.final_snapshot_identifier

  timeouts {
    create = "40m"
    update = "80m"
    delete = "60m"
  }

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_snapshot" "mysql_snapshot" {
  db_instance_identifier = aws_db_instance.mysql.identifier
  db_snapshot_identifier = local.initial_snapshot_identifier

  tags = merge(local.common_tags, {
    Name = local.initial_snapshot_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint of the MySQL instance."
  value       = aws_db_instance.mysql.endpoint
}

output "db_instance_identifier" {
  description = "Identifier of the MySQL instance."
  value       = aws_db_instance.mysql.identifier
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

output "db_snapshot_identifier" {
  description = "Identifier of the manual MySQL snapshot."
  value       = aws_db_snapshot.mysql_snapshot.db_snapshot_identifier
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "efs-backup"
}

locals {
  name_prefix = "${var.project_name}-${var.environment_name}"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment_name
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-mount-target-sg"
  description = "Permits NFS (TCP 2049) ingress only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-mount-target-sg"
  })
}

resource "aws_kms_key" "efs" {
  description             = "Customer-managed KMS key used to encrypt the EFS file system at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${local.name_prefix}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "efs" {
  creation_token   = "${local.name_prefix}-efs"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  backup_policy {
    status = "ENABLED"
  }
}

resource "aws_efs_file_system_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceEncryptionInTransit"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.efs.arn
        Condition = {
          BoolIfExists = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_efs_mount_target" "efs" {
  for_each = {
    for idx, subnet_id in aws_subnet.private[*].id : tostring(idx) => subnet_id
  }

  file_system_id  = aws_efs_file_system.efs.id
  subnet_id       = each.value
  security_groups = [aws_security_group.efs.id]
}

output "efs_file_system_id" {
  description = "The ID of the EFS file system."
  value       = aws_efs_file_system.efs.id
}

output "efs_dns_name" {
  description = "The DNS name of the EFS file system (mount point)."
  value       = aws_efs_file_system.efs.dns_name
}

output "efs_backup_policy_status" {
  description = "The status of the EFS automatic backup policy."
  value       = aws_efs_backup_policy.efs.backup_policy[0].status
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_subnet" "public" {
  for_each = {
    for idx, az in slice(data.aws_availability_zones.available.names, 0, length(local.public_subnet_cidrs)) :
    az => local.public_subnet_cidrs[idx]
  }

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = each.value
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "main-public-subnet-${each.key}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "main-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag applied to every resource in this configuration"
  type        = string
  default     = "dedicated-vpc"

  validation {
    condition     = length(var.vpc_name) > 0
    error_message = "vpc_name must be a non-empty string."
  }
}

resource "aws_vpc" "dedicated_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "dedicated"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "dedicated_igw" {
  vpc_id = aws_vpc.dedicated_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route_table" "outbound" {
  vpc_id = aws_vpc.dedicated_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.dedicated_igw.id
  }

  tags = {
    Name = var.vpc_name
  }
}

terraform {
  required_version = ">= 1.3.0"

