}

locals {
  vpc_cidr    = "192.168.0.0/16"
  domain_name = "windomain.local"
  ad_dns_ip   = "192.168.56.102"

  common_tags = {
    Environment = "greenfield"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "windomain-vpc"
    }
